/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20200916-10","meetingId":"r02-cm09","date":"2020年9月16日","dateIso":"2020-09-16","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時０８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を14件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"大沢副委員長","kind":"質問・要望","question":"本日の予定は、お手元に配付しています予定表のとおりです。なお、石田秀男委員長は、本日、欠席とのご連絡をいただいております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"初めに、(1)「理事者から発言を求められている件について」を行います。本件につきまして、副区長から説明願います。","respondent":"桑村副区長","answer":"本日は、お時間をいただきありがとうあります。本定例会に提案予定をしております第５６号議案、令和２年度品川区一般会計補正予算につきましては、医療提供体制の確保や中小事業者への家賃助成など、新型コロナウイルス感染防止と経済・社会活動の支援を図るものです。","id":"exchange-002"},{"speaker":"大沢副委員長","kind":"確認","question":"説明が終わりました。本件につきまして、特にご確認などはよろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"大沢副委員長","kind":"確認","question":"ただいま副区長から説明がありました中途議決につきましては、後ほど、議事日程の確認の中で局長からも案内がありますが、私からも簡単に説明します。翌２４日には総務委員会での総合審査を実施し、補正予算の審査が終わりましたら、少々時間を空けて議会運営委員会での採決方法確認、本会議開会、中途議決と進めていく予定であります。以上で、本件を終了いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"中塚委員","kind":"提案","question":"しかも、今回の事情は誰に起きてもおかしくないという視点からも必要なのかと思いまして、具体的に、例えばですけれども、文書質問という形がとれないか、今回、急に対応というわけには、検討時間の関係もあって難しいのかもしれませんけれども、やはり何らかの形で質問を保障する仕組みを検討することが我々に必要になってくるのではないかと思いますので、皆さんのご意見も伺いたいし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"大沢副委員長","kind":"質問","question":"今の中塚委員のご意見、一応、拝聴するということにとどめしますので、ご了解願います。ないようですので、それぞれ説明のあったとおり取り扱うこととします。議事日程等に変更が生じる部分について、差し替えの資料を配付いたします。資料はお手元におそろいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"大沢副委員長","kind":"質問","question":"配付漏れはないということで進めます。ただいま配付した資料Ｎｏ.３－２は、９月１８日の運営案について、質問者の順序などを修正したものです。資料Ｎｏ.８－２は、この後の議題で局長より説明があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大沢副委員長","kind":"確認","question":"さよう決定いたします。なお、総括質疑および意見表明の氏名報告、併せて意見表明の原稿の提出の期限につきましては、予定表に記載のとおりですので、各会派への周知のほどよろしくお願いいたします。最後に、新型コロナウイルス感染症への対応について、こちらは９月３日に全会派から理事候補者が参加する理事候補者会の中で確認された内容ですので、特段ご意見はよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"大沢副委員長","kind":"質問","question":"(1)の「日程について」から(3)の「質問者の氏名報告について」までの３件を一括して局長より説明願います。","respondent":"米田区議会事務局長","answer":"本会議２日目、１１月２７日金曜日の午前ですが、小学生の傍聴を例年どおり予定しています。続きまして、(3)「質問者の氏名報告について」ですが、予定表裏面にありますように、１０月６日火曜日、午後５時までに、質問者の氏名を事務局へ報告いただければと思います。","id":"exchange-009"},{"speaker":"大沢副委員長","kind":"質問","question":"ないようですので、第４回定例会の一般質問者の氏名につきましては、１０月６日火曜日までに、事務局へお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"大沢副委員長","kind":"意見","question":"本件については、８月２４日の議会運営委員会において取りまとめを議長一任とさせていただいたものであります。議長よりお願いいたします。","respondent":"渡辺議長、米田区議会事務局長","answer":"具体的な説明は、この後、局長よりお願いしたいと思いますが、考え方として、なるべく各会派からのご提案を尊重し、過去の予算要望の経緯などを参考にしながら検討させていただきました。対応していく予定のものといたしましては、まず政務活動費にかかわる第三者機関設置に関する経費ですが、これまでも予算計上しておりまして、引き続き予算要望をしてまいりたいと考えております。","id":"exchange-011"},{"speaker":"中塚委員","kind":"提案","question":"発言、よろしいですか。ご説明ありがとうございました。何項目かにわたってご説明がありましたが、やはり事前に資料でまとめておいていただけると分かりやすいので、ご検討いただけたらというのが１点です。これは議長に聞くことになるのか、委員会の視察で議運を追加したいということですけれども、基本的にこの提案については賛同しています。","respondent":"渡辺議長","answer":"最後のところです。議運での視察として想定される内容ですが、やはり昨今、議会改革が活発化しております。これは一番ふさわしい、検討する委員会が議運であろうという想定で、特に議会改革の項目が多いであろうというところです。","id":"exchange-012"},{"speaker":"大沢副委員長","kind":"意見","question":"ただいま議長より説明をいただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"大沢副委員長","kind":"意見","question":"局長より一括して説明願います。","respondent":"米田区議会事務局長","answer":"(1)「東京都道路整備事業推進大会について」ですが、河川大会のことも含めてご説明をします。道路整備事業推進大会ですが、第３１回大会については、１０月１９日月曜日に、書面開催となりました。こちらにつきましては、８月１９日の建設委員会でも報告済みです。","id":"exchange-014"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/883739?Template=document&Id=5376#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":12223,"voices":38}},{"id":"r02-20200918-4","meetingId":"r02-c-settlement","date":"2020年9月18日","dateIso":"2020-09-18","committee":"決算特別委員会","time":"午後 ２時５１分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"渡部副委員長","kind":"意見","question":"同じく副委員長に推挙いただきました、自民・無所属・子ども未来の渡部茂です。あくつ委員長を支えてしっかり頑張ってまいりたいと思いますが、くれぐれも委員の皆様には円滑な運営にご協力賜りますよう、よろしくお願いを申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/470470?Template=document&Id=1482#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":2017,"voices":17}},{"id":"r02-20200923-6","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"区民委員会","time":"午前１０時００分～午後 ２時３５分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件抜き出しています。","topics":[{"id":"topic-01","title":"第５７号議案、品川区印鑑条例の一部を改正する条例","agenda":"第５７号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"であるにもかかわらず、同行しないと駄目ということはいかがなものかという思いが少しあるのですけれども、その辺についていかがですかということが１点です。もう１点は、公布の日からですけれども、大体これ条例は本会議で、この委員会でまずどうなるかもまだ分かりませんし、本会議でどうなっていくか分からないですけれども、もしこの議案が可決されたら、いつぐらいから実施されるのか教えてください。","respondent":"木村戸籍住民課長","answer":"１点目の、来られない方がいらっしゃった場合という、基本的には同行されて、お見えになって確認をするということが前提になっておりますので、基本的にはその場合はできないというか、来ていただかないとできないというような形になります。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"この品川区の成年後見センターが出しているパンフレットというか、冊子ですけれども、そうすると成年後見というところでいうと、保佐人型や補助人型、そこもこの成年後見の制度の中には入ってくるということなのでしょうか。","respondent":"木村戸籍住民課長","answer":"今回の対象というところは、いわゆる成年後見というところが入ってくる、いわゆる保佐や補助、そのような方々はこの中には入ってこないという形です。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"国のほうで、不当に差別されないよう必要な措置を講ずることとなったということで法改正があって、先ほど課長もおっしゃったように、成年被後見人というだけで排除されることがないようにということだったのですが、具体的にどのような場面で、どのような差別的な状況に、本人は認識できなかったとしても、そのように明記されることで、どういった分野、多分すごい広くだと思うのですけれども。","respondent":"木村戸籍住民課長","answer":"実際の場面では、例えば公務員の採用などというところで、いわゆる試験を受けられないというようなところに、成年被後見人と明記されていたり、各資格試験などの申込みの条件の中に明記がされていたりと、そのような部分で、いわゆる受けられないといいますか。","id":"exchange-003"}]},{"id":"topic-02","title":"令和２年陳情第４０号、品川区でのたばこ対策","agenda":"令和２年陳情第４０号、品川区でのたばこ対策","exchanges":[{"speaker":"藤原委員","kind":"確認","question":"３番目の、小池都知事が都議会での答弁で、地域の実情に応じた区市町村の取り組みを積極的に支援すると言ったのは、これはまず言ったのか確認です。間違いなく言ったのか。３番の下から２行目です。なっていますよね。ここは区が排除されたのかということの確認、それと排除されていないのであるならば、費用を全額支給することも表明しましたと書いてありますけれども、それも確認です。お願いします。","respondent":"黛生活安全担当課長","answer":"１点目です。知事の発言ですが、このような趣旨の発言をされたというように認識をしています。それと２点目です。","id":"exchange-004"},{"speaker":"藤原委員","kind":"質問・要望","question":"これすごく大事で、今回判断するのに。本当に小池知事がそのような趣旨のことを答弁したのかしないのかという確認をさせていただきたいと思います。","respondent":"黛生活安全担当課長","answer":"申し訳ございません。明確に知事の発言内容については、私のほうで認識をしていないところですが、このような制度が現在整っており、既に運用されているという事実はあります。","id":"exchange-005"},{"speaker":"藤原委員","kind":"確認","question":"そうすると、運用されているということは、知事がこのような発言をしたということは明確に確認はしていないけれども、全額支給はしますよというように考えてよろしいということですね。改めて。","respondent":"黛生活安全担当課長","answer":"一定の条件を満たしたものについてという条件がつきますが、委員ご指摘のとおりです。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"この受動喫煙防止条例が施行されてというところから、この間喫煙率というものは分かるでしょうか。ちょっと課が違うのでしょうか。こうした吸う場所もなくなっていくというところでも、そして健康を守っていくというところでも、喫煙率は減ってきているのではないかと思うのですけれども、区のほうでの認識はどうなっているのかということをお聞きしたいです。","respondent":"黛生活安全担当課長","answer":"指定喫煙所を今後も増やしていくのかという点と、併せて３点目の助成制度をつくることによって整備を進めていくという点についてなのですが、これについては先ほど説明させていただきましたとおり、喫煙者と非喫煙者。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして喫煙者を減らしていくという考えで、健康プランなども進んでいるかと思うのですが、そうしたほかの施策といいますか、対策との兼ね合いというか、そのようなところと整合性というのですか、増やしていくというところでいいのかなと私は感じるのですけれども、その辺の考えを伺いたいと思います。","respondent":"黛生活安全担当課長","answer":"委員もご指摘のとおり、確かに区として健康プランなどの中で禁煙を勧めていくというような方向性にいるということは認識していますが、本件については、それとちょっと切り離して考えているというところがございまして、現実にたばこのポイ捨て、それから匂い。","id":"exchange-008"},{"speaker":"小芝委員","kind":"確認","question":"ちょっと幾つか確認と質問をしたいのですけれども、今年の４月から改正健康増進法と、あと東京都の防止条例のほうが施行されて、それで原則喫茶店等でも喫煙して、例えば飲食をしながらの喫煙というものはできなくなったわけですが、一方では喫煙ブースのようなものを置いて、そこで喫煙するような取り組みもされているお店もありますけれども、何となく、確認をしたわけではないですが。","respondent":"黛生活安全担当課長","answer":"今委員からご質問のありました屋内の喫煙所につきましては、これ担当が健康課のほうになりまして、私どものほうで把握していないという実情です。","id":"exchange-009"},{"speaker":"小芝委員","kind":"質問・要望","question":"そのようなところで、区のほうでも防止対策はしっかり進められていると思いますけれども、何かもっと積極的に、例えば掲示をするなどして、ポイ捨て禁止というものを、されているとは思うのですが、もっと広めていただきたいと思います。どのようにお考えでしょうか。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおり、一部においてそうした事実があるということは、当担当としても認識をしていますが、実は大多数の喫煙者の方につきましては、ルールとマナーを守って喫煙をされている方のほうが多いということが、これは肌感覚なのですけれども。","id":"exchange-010"},{"speaker":"小芝委員","kind":"質問","question":"私も一部の方のこの節操ない態度が、逆に何でしょうか、受動喫煙対策はもちろん大事なのですけれども、一方では喫煙する自由とは言わないですが、そういった方たち、本当にルールを守って喫煙をされている方が喫煙をすることで何とか、息抜きでやっているのですけれども、受動喫煙の弊害ではないですが、何とか過ごしやすい環境を整えていってもらいたいと思います。これは意見として言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"大倉委員","kind":"質問・要望","question":"少しお伺いしたいのが、早期開放で喫煙所が９か所中６か所、今再開していて、閉鎖中その周りで、やはり閉鎖はされているけれども吸っている方などもいるのかなということは思ったのですが、その辺でたばこのポイ捨てが、やはり閉鎖されたことで増えているなどというような認識はあるのでしょうか。","respondent":"黛生活安全担当課長","answer":"２点目の今後の対応ですが、やはり委員ご指摘のとおり、喫煙者、それから非喫煙者、この共存を図っていくという意味においては、喫煙所というものは重要だというふうに認識をしております。","id":"exchange-012"},{"speaker":"大倉委員","kind":"確認","question":"助成制度、ちょっと１点確認なのですけれども、これも先ほどの質問の中でありましたが、都のほうの予算で１０分の１０出て、それで区がそこで、その助成を使って喫煙所の設置をしていくことができるということの認識でいいでしょうかということで、それはいろいろな設置については場所と、また周りの方の理解がということだったのですけれども、そういうものができれば。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおり、民間が新しい指定喫煙所を作る際の助成がどの程度出るのかということは、ちょっと今調査研究していますが、例えば私どものほうで新たに指定喫煙所を作るというような状況におきまして、かかりました費用につきましては。","id":"exchange-013"},{"speaker":"つる副委員長","kind":"確認","question":"各委員が質問していただいたところの確認のようなところもあるのですが、冒頭の藤原委員のほうであった小池知事の答弁については、２０１８年６月１９日の本会議での小池知事の答弁、各会派からの質問に対する答弁という認識でいます。そこをまず最初に教えてもらえますか。","respondent":"黛生活安全担当課長","answer":"民間の方が喫煙所を設置、いわゆる自分の店舗などに喫煙所を設置するときの、この助成金の活用につきましては担当外、健康課のほうで所轄しておりますことから、私のほうで、申し訳ありませんが、ちょっと把握してございません。","id":"exchange-014"},{"speaker":"つる副委員長","kind":"確認","question":"だから独自でというところになると思いますが、その確認と、２の指定喫煙所の中で、公園、駅周辺、庁舎等に指定喫煙所を配置していただくようとあるのですが、公園についてはこの間様々な議論も質疑もあって、当然公園というものは公の園ですから、もう本当に小さいお子さんから高齢者までが憩う場所としてあるわけですけれども、いろいろな名称、児童遊園、防災広場、様々あるわけです。","respondent":"黛生活安全担当課長","answer":"１点目の助成金のところですが、現在都において実施をされている、民間が喫煙所を設置するときに助成金を出すというものについては、利用される方は利用できるはずです。","id":"exchange-015"},{"speaker":"つる副委員長","kind":"確認","question":"その都の予算の活用という部分では、これは民間で実は喫煙専用室などを店舗で設ける場合に１０分の９、３００万円上限というものがあって、その後の資料を全然追いかけていないので何も、私も大変申し訳ない、資料を確認していない中での質疑になっているから、今現在違うのかもしれないですけれども、そうすると、その店舗内に、いわゆる屋内に設けたところであっても。","respondent":"黛生活安全担当課長","answer":"例えばなのですが、ある店舗において喫煙所を作りますというようになったときに、それを、先ほどもご説明しましたが、ではせっかくなので指定喫煙所として皆に開放してもいいですよと言っていただけるご理解のある事業者につきましては、例えば他の区の例ですけれども。","id":"exchange-016"},{"speaker":"つる副委員長","kind":"確認","question":"最後にします。だと思うのですけれども、その確認と、では今後そうした、より積極的な、望まない受動喫煙をしっかりと、少しでも一方で対応を取っていくというところでの、今後の課題や認識、やり方、ありようなど、その辺を、こうしていくという現状は今はないと思うのですが、考えとして何かあれば、それを教えていただければと思います。","respondent":"黛生活安全担当課長","answer":"今までは非喫煙者と喫煙者の共存を目指して頑張ってきたところですが、その前提に新型コロナウイルスの感染を拡大させないのだという新しい課題を乗せて、これからは進めていかなければならないというふうに考えているところでございまして、そうした意味においては。","id":"exchange-017"},{"speaker":"大倉委員","kind":"質問","question":"先ほどもちょっと質疑で伺いましたが、一番最初の開放というところは今いろいろ工夫しながら検討していっているということ、また、いわゆる適切な配置についても、今コロナウイルスの関係で課題があるけれども、しっかりと運営に向けて取り組んでいくということでありますので、そういったことで、助成金についても今調査研究して、これから進めていくということでありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"提案","question":"ただ、そこにきちんとしたすみ分けや、望まない受動喫煙の対策が行政としてどう取っていけるのかというところは、ちょっと今後また１つ、これまでもやっていただきましたけれども、これからもしっかりと、様々な観点からやっていかなければならないというところもあるので、１つそういった課題はあるのかなという部分はありますが、この望まない受動喫煙防止対策を区に対して推進してほしいと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"意見","question":"やはり人の命や健康を守るということですし、吸っている人は自ら自分の体を害して、そしてさらに周辺に被害を与えるというところでも、年々喫煙者は減っていっているという中でも、年間受動喫煙が原因で亡くなられる方は１万人を超えているという状況もあることから、さらに増やしていくとか、そのようなことではなく。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問","question":"結論を出すで、趣旨採択でお願いします。望まない受動喫煙防止を推進するためということが大前提になって、それ以下、推進するための理由が述べられていると私は判断しております。なので、趣旨を採択するということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"くにば委員","kind":"質問・要望","question":"最後のこの３番の部分ですけれども、現に調査研究中、一連の助成金制度についてということで、こちらも他区の状況なども踏まえて、もろもろ勘案した上でゆっくりと調査研究のほうしていって、分煙ということをきちんと区のほうでも推進していただきたいと思っているので、すぐにというよりは、きちんと調査研究を進めていただきたいということで、全体的に趣旨採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"松本委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いします。そういった民間のアイデアを後押ししていくというようなことは、これはやはりすみ分けというところや、段階的に減らしていくという中でも、我々としてもやはり取り組んでいくべきというふうに考えていますので、趣旨採択というふうに考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"}]},{"id":"topic-03","title":"の第５６号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"の第５６号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"くにば委員","kind":"質問","question":"順にお伺いします。は町会・自治会物品補助金についてです。こちらが限度額５万円で１００の町会等にということで、トータル５００万円。こちらの、まず５万円という上限の予算について、私のほうでもろもろ試算してみたのですが、まず所感として、これはかなり過剰な予算ではないかというふうに捉えています。マスクに関しても１枚２０円、これが２万円分買うにしても、やはりすごい量ですよね。","respondent":"川島地域活動課長","answer":"それから執行率もなかなか難しいご質問ではありますが、今、私どもの見積り、品川区内に２０１町会・自治会がございまして、その半分程度で予算を使うだろう、予算というか、この補助を使っていただけるだろうということで、ざっくりと予算を組ませていただいております。","id":"exchange-024"},{"speaker":"くにば委員","kind":"質問・要望","question":"まだこちら、もう少し実施まで時間があると思うのですけれども、例えばこちらの見直しに関してなどをどうなさる予定があるのかということが１つと、あとはこちらマスク、消毒液等ということで、ほかに、今私が挙げたものがその２点だけなのですけれども、どのような消耗品というものを想定されているのか、そしてこちらの消耗品を購入した際に。","respondent":"川島地域活動課長","answer":"それから今回のこの補助の執行に当たりましては、要綱を制定しましてやるということで、領収書を当然添付していただいて、流用などができないような形で、その辺の縛りをかけるという予定です。","id":"exchange-025"},{"speaker":"くにば委員","kind":"質問","question":"これが、もちろん今回の予算で、例えばこれ半年、来年分ぐらいまで足りてしまうと思うのです。アルコール消毒液に関しては。なので、このバスハイク、餅つきというものはあくまで例示だと思うのですけれども、ほかにどのようなことを想定していて、これだけの予算を使うぐらいのマスクや消毒液などが必要であると考えているのか、そちらについてお伺いします。","respondent":"川島地域活動課長","answer":"その期待というか、これからイベントができるような元気なまちになっていただきたいというような思いからやったものでして、なかなか考えが難しいところではありますが、予算をしっかり執行するという意味では、これはほかの補助金でも同じことですけれども、事前に申請を受けて。","id":"exchange-026"},{"speaker":"くにば委員","kind":"質問・要望","question":"３か月後餅つき、こちら正月も恐らく行われないところが多いかなと。待合スペース３密解消対策について、こちらですけれども、このＬＩＮＥで住所や世帯主、世帯員情報を入力するという、こちらについてもろもろ調べた中では、恐らく取り組んでいる自治体というものはまだないのかなとは思うのですけれども、そちらについてほかに取り組まれている自治体があるかどうかをひとつご答弁いただきたいです。","respondent":"木村戸籍住民課長","answer":"今後ですけれども、これはちょっとまだ来年度の予算要求という形で、今後のご提案という形になると思いますが、今委員のおっしゃられた、いわゆる役所に来なくて済むというのですか、申請も発行も郵送されるというような形のサービスを。","id":"exchange-027"},{"speaker":"くにば委員","kind":"提案","question":"ざっくり申し上げますと、費用対効果に見合わないのではないかという部分を懸念していまして、今想定されている中で、このＬＩＮＥの今回の取組で、例えば月間何件ぐらいの利用を想定してこちらの予算を組んでいるのか、こちらの事業をしようとしているのかという、その利用率の想定について伺いたいのと、あとはＬＩＮＥの公式アカウントの現在の登録者数について伺いたいのと、あと今のご答弁で。","respondent":"木村戸籍住民課長","answer":"それと利用料の想定なのですけれども、先ほどご説明したマイナンバーカードを提示すると届書が出てくるという形が今の仕組みなのですが、毎日１件程度あります。","id":"exchange-028"},{"speaker":"くにば委員","kind":"確認","question":"最後におっしゃっていた戸籍等のものに関しては、品川区のホームページにダウンロードできる形の書式のものが、ファイルがあるということでしょうか。ちょっと私が見た限りでは、例えば住民票の申請に関して、あとは転出届、転入届に関して、ホームページのほうから取得できるファイルがなかったように思うのですけれども、そちら私の確認不足かもしれないので、もう一度ご答弁お願いします。","respondent":"木村戸籍住民課長","answer":"実際に婚姻届などの様式ですけれども、そちらの戸籍の、いわゆる汎用の様式のようなところは、今ホームページで公開しております。ただ、ちょっと分かりにくいですので、また改善してまいりたいと思いますが、今ダウンロードできるようになっております。","id":"exchange-029"},{"speaker":"くにば委員","kind":"提案","question":"そうですね。これでもう一つ私のほうから、提案を含めて申し上げるのですけれども、これは結局目的として待合スペースの３密解消、要するにこの待合室に滞在する時間をいかに短くできるかという利便性の向上も含めてなのですが、これは既にホームページのほうで、戸籍住民課窓口リアルタイム混雑状況確認のページというものがありますよね。","respondent":"木村戸籍住民課長","answer":"逆にそちらのほうに、今おっしゃられたＬＩＮＥ側に飛ぶ、このような形でやればすぐできますというような形のご案内を載せてリンクを貼るであるとか、そのような形の取組が有効ではないのかなというふうに、今のところ考えています。","id":"exchange-030"},{"speaker":"くにば委員","kind":"意見","question":"すみません。そこの一歩手前で申し上げた、ＬＩＮＥの今の総合メニュー、品川区公式アカウントのＬＩＮＥの総合メニューの中にこれも１つ付け加えるということで、それと同様に現在の混雑状況のページというものを追加するということは、それは難しいことなのかどうか、お分かりになる範囲で。","respondent":"木村戸籍住民課長","answer":"基本的にはそちらのやり方も取れると思いますので、ぜひそのような形でやっていきたいと思います。","id":"exchange-031"},{"speaker":"くにば委員","kind":"質問","question":"こちらの事業内容２番目のマイナンバーカード受付予約ツール導入、こちらに関しても、これは基本的にインターネットから予約できるようにするということで、これはホームページのみという認識でよろしいのでしょうか。","respondent":"木村戸籍住民課長","answer":"区民にはネット環境をお持ちでない方などもいらっしゃいますので、電話での受付もするというような形で考えております。","id":"exchange-032"},{"speaker":"くにば委員","kind":"質問","question":"例えば渋谷区等でしているのですけれども、こういった行政の窓口の予約というものがＬＩＮＥのメニューのほうから同様にできるのですが、その取組を同様の意味合いであるのであれば、ＬＩＮＥで追加したらいいのではないかと思うのが１つあるのですけれども、そちらに関して、そもそも話合いの土台に上がっていたのかどうか、ご認識なさっていたのかどうか。","respondent":"木村戸籍住民課長","answer":"それからメニューの追加はできるということです。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問","question":"これ、例えば国のGo Toのような形でごり押しで、やると言ったのだから、感染拡大はこれだけ進んでいるけれども事業は一気に進めてしまうというような形にならないかどうかという懸念がありますので、そこの部分と、もしそこをお考えなのであれば、具体的にこちらのキャンペーンを休止したり、見直しをしたりする際の、東京都などの感染者数もそうなのですけれども。","respondent":"古巻文化観光課長","answer":"具体的な、何というのですか、そういった要件につきましては、東京都の４段階の中で、色づけで状況のランクづけをしていますけれども、あれが最大の状況になった場合には当然できないのだろうなというか、そもそもお客さんが多分いらっしゃらないだろうというふうに考えますので。","id":"exchange-034"},{"speaker":"くにば委員","kind":"質問・要望","question":"ただ、そこに関しては、感染拡大防止という観点からもきちんと中止をして、中止をするべき、休止をすべきというときには、ぜひともきちんと判断していただいて休止をしていただきたいと私のほうは要望として思っているのですけれども、そこに関してご答弁いただいている形で注視していくということでお願いしたいと思います。","respondent":"古巻文化観光課長","answer":"ところがこの間、７月、８月ぐらいの利用ということで、大体その２万人の１％程度というふうに聞いていますので、もうほとんど利用がない状況で、外気を取り入れた飲食を伴うクルーズをやったりなどということで、少しいろいろな試みはしていますけれども。","id":"exchange-035"},{"speaker":"くにば委員","kind":"提案","question":"利用率が１％まで下がってしまったということで、非常に厳しいという現状がよく分かりました。これはあくまで提案というか、今思いついたことの１つなのですけれども、結局１％ぐらいに落ち込んでいて、これ１万人に到達するのはやはりなかなか難しいのではないかなと。","respondent":"古巻文化観光課長","answer":"柔軟性につきましては、ちょっとどこまで柔軟にできるかというところはありますけれども、目的が屋形船の利用を呼び戻す、再び使っていただけるような、もしくはきちんと安全なのだということがイメージとして皆さんに伝わる、そのようなことが重要だと思っていますので。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問・要望","question":"屋形船の事業者がそれだけ大変な思いをしている中、何とか区のほうで、この将来ずっと続いていってほしい屋形船の事業者について、全力で支援のほうを続けていってほしいと考えています。もう１点、こちら１４か所の施設で、今まで、体温測定器を導入するまで、現状までの間でこの施設を利用したことによって感染してしまったというような報告が、この１４施設はなかったのかどうか、以上の点を伺います。","respondent":"古巻文化観光課長","answer":"最後、３点目にご質問のあった、今までに施設利用の中で何か感染者が出たことがあるかということですけれども、現状体育館も含めて、文化スポーツ振興部の施設でそういった感染者が出たというようなことは認識はございませんので、しっかり皆さん、使われる方は。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"それが使われる必要がないのであれば、この１４か所については今回の予算での自立タイプのみを使う、それでその、要するに余ることになった、余分になることになったハンディタイプを別の施設等に回すなどの形で、この自立スタンドタイプで全て賄えるようになるのかどうか、賄えるようになるのであれば、その今使っているハンディタイプを別の施設に回すことができるかどうか伺います。","respondent":"古巻文化観光課長","answer":"自立スタンドタイプで一定の範囲での対応は可能になると思うので、今ほどの数は必要なくなってくるのかなというふうにも考えられます。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問・要望","question":"こちらの体温測定器に関しては、もう無論世界中でもスタンダードで使われているものでありまして、当然ながらその効果に関しては実証されていることであります。今回の、ようやくこのスタンドタイプの予算がついたということなので、区が管理している施設においてはぜひともこちらの体温測定器、ハンディタイプも含めて、導入のほう確実に進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やっぱり１０万円の特別給付金、申請書を送付するよりもマイナンバーで、オンラインで申請するほうが速いという、そういったこともあって、連日戸籍の窓口が本当にいっぱいになっていたなという、私も見ましたけれども、でもこれも、もともとなかなか普及しないマイナンバーを区民の方に給付金と結びつけて普及させようという感じがしてならなかったんですが。","respondent":"木村戸籍住民課長","answer":"それで、ご指摘のとおり１０万円の関係、今、マイナポイントの関係になりますとか、今後の使用用途というんですか、これから持っていたほうがいいんじゃないかと、いわゆる、そういう需要が喚起されたということになると思うのですけれども、件数的には。","id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"ちょっと意見を述べて次にいきたいと思います。次に、順番がばらばらかもしれないんですが、都市型観光プランのところで、水辺の魅力アップのほうは、これはクルーズツアーおよびウォーキングツアーを実施して、観光マップを作成して、フォトコンテストの開催。倒産というか、ちょっともう閉めざるを得ないというところは出ていないのか、そこを伺いたいと思います。","respondent":"古巻文化観光課長","answer":"水辺の魅力アップのほうですけれども、こちらは区と観光協会が連携いたしまして進めていくもので、事業によっては当然、マップの作成であったりとか、船の運航の委託というのはありますけれども、あとは全体の総括的な意味では品川区のほうでやっていくという考え方です。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問","question":"その屋形船を運営されているところというのは何か所くらいあるのでしょうか。","respondent":"古巻文化観光課長","answer":"失礼しました。この企画に参加するということでは、区内の業者ですけれども、１０事業者がいると把握しております。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問","question":"という声も寄せていただいていたんですけども、こうした屋形船の協会というんですか、何ていうか分からないですけど、そういうところと協議したりした結果でこういう策につながったというところなのか、それを伺いたいと思います。","respondent":"古巻文化観光課長","answer":"１０事業者の対象の選定ですけれども、キャンペーンを含めて、魅力アップの事業を考えていまして、それは区内の屋形船業者ということですけれども、事業者にご参加いただく形になっています。","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"品川区家賃支援給付金についてですが、国および区の実施する家賃支援給付金に独自の上乗せ給付を実施するということなんですけれども、補助金によくあるスキームというんですか、国が何分の１で、都が何分の１で、区が何分の１という、そもそものそういうスキームというものではなくて、区は乗せなくてもいいけど独自に乗せたということなのかというのを伺いたいんですが。","respondent":"遠藤商業・ものづくり課長","answer":"家賃支援の上乗せ給付の考え方ですけれども、まず国のほうが一番最初に、いわゆる、なかなか固定費の負担が大きいということで、国のほうで進めたところでございまして、そこに東京都のほうが、７月ぐらいだったと思いますけれども。","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"分かりました。独自で乗せたということで、それでやっぱり対象がすごく気になるところだったんですけれども、都の家賃支援給付金の交付決定を受けている者が対象者。で、区内の事業者であるというところなんですけど、これは、要は全て品川区の対象にというようになってくるんですか。この都の家賃支援給付金の交付決定を受けている者というのはどういうものなのか教えていただきたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"そこの部分だけちょっと変えさせていただいて、あとは速やかに支給させていただきたいというところで、一番簡単な方法ということで、東京都のそのまま金額の２分１という形でさせていただいたところです。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"この一番下のアスタリスクのところで、７億円が地方創生臨時交付金ということですけれども、この地方創生臨時交付金というのは、コロナ対策、コロナウイルス感染症対策地方創生交付金ということで、コロナ対策なら、様々使えたけれども、それをここに７億円全て充てたという、そういう考え方なんでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"地方創生臨時交付金の対象というところなんですけれども、こちらの充当につきましては、財政部門のほうで検討したところでございまして、私ども全部で約１１億円今回、予算計上されているかと思いますが、私どものほうで全額充当するということでは聞いているとことです。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。本当にこの事業所の固定費、家賃だったりというところは、コロナになる前から負担になっていたという議論もあるので、本当にこの地域支援給付金、さらに区が独自で上乗せしていくというのは良いことだと思っていますので、私もこれは、また申請かと言われたんですけど、こういうのが出るよと周知したときに。それが、どういうふうな、簡易な形にされているのかどうか。","respondent":"遠藤商業・ものづくり課長","answer":"申請につきましても、今までは基本的に郵送なり、あるいは持ち込みでという形でさせていただいたんですが、いろんな給付金の中でオンラインを使った申請に大分皆様慣れてきているようなところもありますので、今回はオンラインをできるだけ使っていただいて。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"最後にちょっと細かいところ、体温測定器のところなんですが、この自立スタンドタイプというのは、全身が写る形で、そして熱があると、先ほど何か警報が鳴るというようなことだと聞こえたと思うんですけど、熱があると警報が鳴って、職員とか、対応する方が出てくるという感じのものになるということなのか、ちょっとどんなものなのかを伺いたいと思います。","respondent":"古巻文化観光課長","answer":"設定によって、多分、何度以上とか、いろんな調整ができると思うんですけれども、設定温度以上の方がいらっしゃったときには、何らかの形で、音声もできるでしょうし、ブザー的なこともできるでしょうし、分かるようになって。","id":"exchange-048"},{"speaker":"藤原委員","kind":"質問","question":"体温測定器の部分でお伺いしますけれども、自立スタンドタイプを入れますという報告ですけれども、答弁を伺っていたら、きゅりあんのほうには、非接触で体温を測るのは入っていますよという報告だったんですけど、現時点で、きゅりあんにスタンドタイプの体温測定器ってありますよね。入って、使用していますよね、現時点できゅりあんに。それとは別の機械を入れるんですか。","respondent":"古巻文化観光課長","answer":"それをまたさらに補う形で、大きい施設ですので、足りない部分は区の予算である程度フォローするというような形で考えています。","id":"exchange-049"},{"speaker":"藤原委員","kind":"質問","question":"私の勘違いでなければ、文化振興事業団が独自で買って、スタンド型の測定器は入れているわけですね。だから、文化振興事業団が主催の事業でそれを使っているということですよね。区が買うということは、いわゆる、あそこで、７階でも、８階でも、６階でも、５階でも、やるときに、有料であるかもしれないけれども、貸してくださいといったら、区で購入する測定器はお貸しするんですか。","respondent":"古巻文化観光課長","answer":"運用については、ちょっとまだ十分文化振興事業団と協議が調っているわけではないので、それは今後、細かいところを含めまして、しっかりご案内していきたいと思いますけれども、きゅりあんは今回２台入れるということで、受付の窓口とか入口に、大ホール。","id":"exchange-050"},{"speaker":"藤原委員","kind":"質問","question":"台数２台ということですけれども、こういうところに予算を使っても、区民の理解というのは私は得られると思うんです。それだけの台数、だから同じ日に３台要るわけですよね。だから、そこのＡ、Ｂ面に使うのと、Ｃ、Ｄ、Ｅ面に使うのと、８階で使うのと、少なくとも３台はという声が出てくる。だけど、新型コロナは把握しないわけじゃないですか。ですよね。それで、８階で使っていました。どうでしょうか。","respondent":"古巻文化観光課長","answer":"現在の文化振興事業団側の運営に関しましては、限られた利用範囲というところで、ある程度、制限がかかっているところがあると思いますが、それをある程度、もう少し柔軟に利用ができるような形で２台追加しますし、今後。","id":"exchange-051"},{"speaker":"藤原委員","kind":"質問","question":"しつこくてごめんなさいね。自分にとってはこれは大事なので。今おっしゃいました、課でハンディタイプを持っていますと。そうしたら、その課で持っているのは臨機応変に貸し出すんですか。きゅりあんの。貸していただけますかと。有料でもいいですけど、無償でも。貸してくれるんですか。そういう答弁に聞こえちゃいます。","respondent":"古巻文化観光課長","answer":"実際貸し出すかどうかというのは、ここは、いわゆる備品の貸し出しをほかにもやっていますけれども、それと同列に扱うのか、無料なのか、有料なのか、そのあたりはまだしっかりしたガイドラインを作っていませんので、今日、意見をいただいておりますので、その点も含めて。","id":"exchange-052"},{"speaker":"藤原委員","kind":"質問・要望","question":"一般の人が１つの施設を１回借りるわけですけれども、今、文化振興事業団で持っているもの、新しく区で２台買う、補正予算可決されればですけれども、買うものを含めて、もうあそこの施設で行う事業自体が、文化振興事業団、もしくは一般の方でも、瀬戸際で守るという意識でいていただきたいと思っているので、こんなにしつこく珍しく質問してしまっているのですけれども、よろしくお願いいたします。","respondent":"古巻文化観光課長","answer":"そういったところで、きちんと把握できるように体制を整えることはとても重要なことだと思います。すぐに１００％、全てをというのは、なかなか限られた予算の中でやっていくのは難しいですけれども、なるべくしっかり対応していくというような形で、進めたいと思います。","id":"exchange-053"},{"speaker":"藤原委員","kind":"質問・要望","question":"次ですけれども、町会や自治会に限度額５万円ということですけれども、私、個人の感覚だと、個人ですから、例えばこの委員会が始まるときに委員長からお話が出ましたけれども、今、こういうことでこういう形で委員会はします。個人ですよ。理由と目的に出ていますよね。それでいいのかということと、そうすると、品川区にある事業者は、国、都、区から、３つから助成を受けられるのかという確認です。","respondent":"川島地域活動課長、古巻文化観光課長、遠藤商業・ものづくり課長","answer":"先ほど来、イベント実施施設、事業を強調して私もお話をし過ぎて説明がちょっと不足していたところはありますが、事業実施というところだけではなくて。区が認識している風評被害に関しましては、今回の新型コロナウイルス感染症の拡大の時期において、区内の感染が初めて確認されたのが。家賃支援給付金は、国、都、区、それぞれからという形になります。それぞれから受けることができるという形になっております。","id":"exchange-054"},{"speaker":"藤原委員","kind":"質問・要望","question":"最後に、私もいろいろな意味で品川区の産業、自治体、復活していただきたい思いは本当にあるのです。本当に１年に一遍の１０月の中旬、毎年、品川区は品川からお祭りが始まって大井で終わるのですね、１０月の中旬。決して経済とかを止めたいとか、新型コロナウイルスが怖いから全部事業を今、規制したいという意味で伺ったのではありませんので、そこはぜひ理解していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"松本委員","kind":"質問","question":"というのも餅つきということは、かなり人が密集してやると、相当密になるというのは間違いないし、かけ声もあるということで、これはいろいろな町会イベントの中でも結構、御神輿とかはもちろん声を出しますけれども、餅つきは飛沫感染ということを考えたときに、大きな感染の可能性としては比較的あり得るところだと思うので。","respondent":"川島地域活動課長","answer":"先ほど来、同様のご指摘が増えているところではありますが、こちら、昨年度の区の補助、申請されてやる事業の中で、多かったものを例示させていたものですので、当然、これから先、どういうふうな感染状況になるか、現状では当然できないというのは分かっております。","id":"exchange-056"},{"speaker":"松本委員","kind":"意見","question":"そこはやっぱり決定していただいたほうが間違いなく誤解は避けられるのではないかと思うのですけれども、あと、これは最終的には要綱で出していくという話にもありましたけれども、もっと前提のところで、町会の在り方とかイベントの在り方というのを、コロナは別に今年だけで終わるとは限らないので、本当は在り方も、これまでのイベント的なものというのを、この場でやるところだけではなくて。","respondent":"川島地域活動課長","answer":"ご指摘の感染リスクを下げるような取り組みのところというのは、申請のところでしっかり協議の中で指導というか、させていただければと思います。","id":"exchange-057"},{"speaker":"松本委員","kind":"質問","question":"マイナンバーというのは、本当はちゃんとやっていくべきだと我々は思っているところで、確かに今急いでやっていらっしゃるというところで、インターネット予約ができるようになって、日曜日だけだった電話予約を平日分も受け付けるということで、どのくらい待ち時間が削減されるのか、電話予約をされている方がオンタイムで行った場合、すぐ受付がスタートするのか。","respondent":"木村戸籍住民課長","answer":"今、考えている形といたしましては、特定の例えば３時、３時半の間とかというような形で、この受け付けは、いわゆるマックスより少し多目にとっておいて、余裕を持たせておいて、その間に予約外の方でいきなりこれ聞きたい、あれ聞きたいということも受け付けられるような。","id":"exchange-058"},{"speaker":"松本委員","kind":"確認","question":"確認になるのですけれども、予約、その時間で予約した人のほうが、飛び込みの方たちよりも、ある意味優先されるというふうに考えてよろしいですか。","respondent":"木村戸籍住民課長","answer":"そのような形で、それから、基本的にその時間に予約して来ていただいた方を優先するという形です。","id":"exchange-059"},{"speaker":"松本委員","kind":"意見","question":"今の点はわかりました。次に家賃支援給付金ですけれども、これも国の方の話からすると、事務委託費の問題がいろいろとこの間、色々な給付金の話でありましたけども、こちらのシステム構築と事務委託等というところで、これは具体的に事務委託というのはどういったところにされているのかお答えいただければと思います。","respondent":"遠藤商業・ものづくり課長","answer":"現在のところ、考えておりますのが、時間がないものですので、ある程度実績のあるところを考えておりまして、そこと契約を結べるように進めているところになっております。","id":"exchange-060"},{"speaker":"松本委員","kind":"質問","question":"これは随意契約という形でやっていくということだと思うのですけれども、これはまだどこかというところは決まっていない、まだ予算をとっていない、ここは特に協議とか具体的な対策をとるということはやられていないということですか。","respondent":"遠藤商業・ものづくり課長","answer":"こちらのほうで今、探してあたりをつけているような状況です。ですので、今回の補正予算が可決されましたら、内部手続といいますか、このような形で進めて、本会議、定例会で予算決定いただければ、速やかに契約するという形で進めているところです。","id":"exchange-061"},{"speaker":"松本委員","kind":"質問・要望","question":"先ほども申し上げた政府の方ではかなり高額なところになっていて、額としては全然違うのですけれども、そのあたりはどうしても多分、企業側もこのタイミングである程度高めの見積りを出してくるのではないかなというふうに思っていますので、ぜひそのあたり、費用の精査をいただければと思います。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"小芝委員","kind":"質問","question":"幾つか質問します。品川区の町会、自治会の感染症対策についてお聞きします。そこでお聞きしたいのですが、先ほど、品川区の町会が２００を超えるという答弁をいただいておりましたけれども、こちらその半分ということで、例年の年末といいますか、歳末、年始にかけた活動が大体１００町会ぐらいで行われているという認識でよろしいでしょうか。","respondent":"川島地域活動課長","answer":"品川区の今の町会、自治会数が２０１町会あります。歳末の活動というところでやったものではなくて、ざっくり町会、自治会の半数程度のものを活動の支援になればというような形で計上させていただいたところです。","id":"exchange-063"},{"speaker":"小芝委員","kind":"質問","question":"こちらのほう、いつから申請ができるような形でお考えでしょうか。","respondent":"川島地域活動課長","answer":"こちら予算の議決をいただきまして、速やかに要綱のほう作りまして、実際、事前に相談等いただければ、その辺の相談と並行しながら申請の手続等を進めていきたいと考えていますので、なるべく間のないように迅速に対応します。","id":"exchange-064"},{"speaker":"小芝委員","kind":"質問・要望","question":"待合スペースの三密解消対策についてお聞きをいたします。確認ですが、住民異動届出書等の作成時間短縮ということで、スマートフォンのＬＩＮＥでＱＲコード化したものを窓口で読み取るという、これは窓口に読み取るタブレットが設置されているのか、役所の職員さんが来て直接フェイストゥーフェイスで読み取り作業するのか、どういう流れなんでしょうか。","respondent":"木村戸籍住民課長","answer":"そちらのうちの１台がマイナンバーカードを読み込ませてやると届出が自動作成されるという形で、この機能でお客さんは、スマホでＱＲコードをかざしていただくと出るということでございまして、基本的に職員が介在するとかお預かりで何とかという形ではなくて。","id":"exchange-065"},{"speaker":"小芝委員","kind":"質問・要望","question":"家賃支援給付金について質問いたします。対象見込み７,２００件ということですけれども、こちら東京都の家賃の支援給付の申請をされたのがおおよそこのぐらいの件数ということでよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"私どもで分かっていますのが、いわゆる製造業の部分については、３１.４％が、調査の中でいわゆる賃料を払って運営しているというところで、それから、情報通信業ですと、大体かなりのところ、１００％にほぼ近いのではないかなと考えているところです。","id":"exchange-066"},{"speaker":"小芝委員","kind":"意見","question":"内訳の助成額で１件あたり１０万円ということですけれども、これって私、計算間違っていたら申しわけないのですが、家賃が大体８０万超えるようなケースではないかなという気がしているのですけれども、その辺のほう、家賃は１０万ぐらいのところもありますし、なぜこの金額設定になっているのか。","respondent":"遠藤商業・ものづくり課長","answer":"当然一つの事業所で複数持っているところもありますので、そういう意味では、必ずしも１件の家賃で８０万円というわけではないと考えているところです。","id":"exchange-067"},{"speaker":"小芝委員","kind":"質問・要望","question":"都市型観光プラン推進事業についてお聞きします。そういう中でこのキャンペーン、今、コロナ禍の状況ですので大変だと思いますけれども、進めていただきたいと思います。そういうところで１つ質問しますが、乗船料の補助、こちらは品川区在住の方を対象にしているものなのか、それ以外の方も含むのか、お答え願います。","respondent":"古巻文化観光課長","answer":"乗船料の助成対象に関しましては、区内の事業者を使った場合に助成いたしますという形ですので、特に利用者については、特定の何か、区民でなければいけないとか、そういったような制限は考えてございませんで、広く使っていただくように事業を進めていきたいと考えています。","id":"exchange-068"},{"speaker":"小芝委員","kind":"質問・要望","question":"団体で新年会とかをやればまた話は変わりますけれども、そういう中で、品川区民の方々を優先してというわけではないですけれども、広く地域の方々にもこのキャンペーンを周知していただきたいと思うのですけれども、お考えをお聞かせいただけばと思います。","respondent":"古巻文化観光課長","answer":"今、ご指摘がありましたことにつきましては、区としても認識をしておりまして、水辺の方は、屋形船は非常に身近な存在だと思うのですけれども、それ以外の方々は、存在自体はよく知っているにしても、乗る機会がなかなかないという方もいらっしゃるといると考えています。","id":"exchange-069"},{"speaker":"大倉委員","kind":"質問・要望","question":"これは、東京都の助成金は３０万円、区のほうも５万円上乗せして３５万円なのですけれども、何か機能的に特筆してこういうのを選んだのかというところなのか、たまたま選んだものなのか、何か選んだ基準みたいな、こういうのがいいのでこういうのを選びましたみたいなのがあれば教えていただきたいのと、基本的にはこういう施設については安全に利用していただきたいのですが。","respondent":"古巻文化観光課長","answer":"機器の選定の考え方ですけれども、基本的には人の手を介在しなくても、自立をしていて、来館者の方がご自身で映るとそれで自動的に測定される、そういったものを選んだということで、金額の考え方については、地方創生臨時交付金の枠が決まっている関係で。","id":"exchange-070"},{"speaker":"大倉委員","kind":"質問","question":"分かりました。熱があると、何か警報が鳴って職員さんが来て対応する。体温は平常だけどマスクはつけてないとなると、警報が鳴って職員さんがマスクをつけるように促すようになっているという感じですか。","respondent":"古巻文化観光課長","answer":"そのような形で、マスクをしていただいて、体温が平熱であるということを確認できると。ある程度ガイドラインに則った運用になると思いますが、マスクについては、着用をお願いしているにもかかわらず、してなかった場合はきちんと現場の職員が対応するという形になると思います。","id":"exchange-071"},{"speaker":"大倉委員","kind":"質問","question":"最後に、先ほど藤原委員からお話があったように、この台数は、まさにいろいろなところで、有料も含め、無料も含め、区民の方が利用するところで、どういうふうに使われるかという検討もされてこの台数になっているかと思うのですけれども、台数の考え方は、どういうふうにこの２台というのを出されたのかを教えていただけますでしょうか。","respondent":"古巻文化観光課長","answer":"基本的には、施設の入り口ではかるということになると思いますので、例えば、きゅりあんですと、メインは７階と８階になるのでそのようにお話ししましたけれども、文化センターは各入り口で１台ですけれども、荏原文化センターに関しては、プールの入り口が別にありますが。","id":"exchange-072"},{"speaker":"つる副委員長","kind":"質問","question":"区の単独の一般財源でやるか、それとも、この枠の中での進捗状況を見て、そうした展開も検討の余地があるかどうかというところも含めて、大前提は感染拡大をさせないということが１つあるわけですが、今、国全体の方向性でも経済との両輪として示されている中で、そういう意味において今の部分はどういうお考えができるか、もし現段階で見解があれば教えてください。","respondent":"古巻文化観光課長","answer":"事業の具体的な進め方という部分でいうと、検討の詳細まではまだ固まってない部分がありますので、今いただいたご意見も含めて、乗船するきっかけをしっかりつくっていくということと。","id":"exchange-073"},{"speaker":"つる副委員長","kind":"提案","question":"私も事前に確認してないので、大変申し訳ない、確認の部分もあるのですが、今回、歴史館に対する寄附金が５０万円、匿名であるかと思うのですが、これについては、購入予定物品は展示什器とあるわけですけれども、歴史館については、もう既に非接触型の体温計が置かれているとか、自立スタンドタイプのものが設置されているのでしょうか。事前に確認できなかったので、教えてください。","respondent":"古巻文化観光課長","answer":"歴史館につきましては、ほかの文化センターと同様、非接触型の人が操作するタイプがあります。","id":"exchange-074"},{"speaker":"つる副委員長","kind":"質問","question":"展示什器というのは具体的にどういうものを購入予定されているのかということと、匿名でいらっしゃるけれども、区としては当然その方を把握されているという寄附のあり方なのか、それとも、それも含めて匿名でいらっしゃるのか、逆に、こういう物品を購入しましたと、寄附をいただいた方にどのような形で今までお伝えしていたのか、その辺を教えてください。","respondent":"古巻文化観光課長","answer":"今回に関しましては展示什器ということで、そんな大きなものではないのですけれども、展示のケースを購入予定です。展示品を展示するケースを新調したいというところがあるようですので、そちらを購入するという計画で今進めているところです。","id":"exchange-075"},{"speaker":"つる副委員長","kind":"質問・要望","question":"次は、家賃支援給付金についてです。教えていただきたいところも含めてなのですが、国のほうは、６カ月分を一括支給という認識で、３００万円。これを活用しているという前提で、東京都の家賃支援給付金は使えます。そうすると、家賃の７９.１％が国、東京都、区から給付してもらえると。こういう計算でまず合っているか教えてください。","respondent":"遠藤商業・ものづくり課長","answer":"７５万円以下ですと、３カ月分は東京都と私どもの考えになっているので、おおむね８割を３つの団体から支給するような形になってあります。","id":"exchange-076"},{"speaker":"つる副委員長","kind":"確認","question":"これも事前に詳細に資料を見て確認して、ここはどうですかと確認できればよかったのですが、もしかしたら説明の冒頭にあったのかもしれないですけれども、ちょっと私も失念したかどうか分からないですけれども、この事業内容の２の（１）の参考で東京都の概要を一覧で出していただいています。確認です。","respondent":"遠藤商業・ものづくり課長","answer":"参考の一番の下段かと思いますけれども、おっしゃるとおりです。資料に間違いがございまして、大変失礼いたしました。","id":"exchange-077"},{"speaker":"つる副委員長","kind":"質問","question":"要は、区としてどれだけ給付されるのだろうと計算していったときに、金額、私の計算間違いかなと思ったら、今ご答弁いただいたとおりの３万１,２５０円になるのだろうと。そうすると、上から６.２５万円、１２.５万円、３.１２５万円、６.２５万円、こういう最大給付、それの２分の１を品川区が給付するということでよろしいですか。その点、答弁をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"副委員長のおっしゃるとおりです。","id":"exchange-078"},{"speaker":"つる副委員長","kind":"確認","question":"先ほど来、各委員の質疑の中でここまで確認の質疑がなかったのですが、実際、給付されたときに違うではないかとなってしまうとよろしくないと思ったので、あえて確認をさせていただきましたが、分かりました。それが、中小企業等の７５万円以下でやっていくと、６.２５万円の半分だから３万１,２５０円の３カ月だと、約１０万円弱になるからアベレージで１０万円と、そういう認識でよろしいでしょうか。","respondent":"遠藤商業・ものづくり課長","answer":"家賃の平均では８５万円ぐらいを想定していますので、約１０万円ぐらいになるだろうというところで、７５万円ですと３ヶ月分で９万３,７５０円になるかと思いますが、もう少し高いという見込みです。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/645301?Template=document&Id=2878#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":62375,"voices":206}},{"id":"r02-20200923-7","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"厚生委員会","time":"午前１０時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を107件抜き出しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(2)から先に行います。 それでは","agenda":"冒頭申し上げましたとおり、取り上げる順番を変更し、議案審査(2)から先に行います。 それでは","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"いろいろありますので、順番に質問したいと思います。最初の介護サービス利用者負担増分の補助の件ですけれども、この３,２００万円弱ですか、これで事業者の全部を、６月１日に遡及してやり、それから来年の３月までということだと思うのですが、率直にカバーできるのでしょうか。お伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"ただし、ご本人がこういう制度があると知りつつも同意をしないということであれば、この制度の俎上には乗ってこないのですが、対象とされるサービスにおいて、この２区分上位に同意しますといったケースにつきましては、全てこの補助金の対象とする、そういう予定でおります。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"これまでは、要するに負担が増えるから、利用者の同意ということになっています。それでこれからは、区が負担するということになりますと、利用者は当然同意してしまうことになると思うのですが、そうすると、今までより爆発的に増えると思うのです。だから、今までの数字よりどんどん増えていくのではないかと思うのですけれども、それでもカバーできるのですか。","respondent":"宮尾高齢者福祉課長","answer":"あくまでも見込みですので、１００％ということは言い切れないかもしれませんが、それでも、今委員にご指摘いただいたことも含めて、当然ながら、この制度ができたら同意しますよ、という方も出てくるだろうという想定の下、今回。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"それで、新聞で見たのですけれども、例えば長野県の飯田市、１０万人ほどの町ですが、そこでは８,１００万円の予算を組んでいるのです。４０万人の品川は３,１００万円で、違和感を感じたのですが、それは大丈夫ということですか。","respondent":"宮尾高齢者福祉課長","answer":"飯田市の制度を私は直接そこまで深く見てはいないのですが、先ほどから言っていますけれども、これまでの受給実績、それから今回の制度を導入することによって増えるであろう部分、そういったことも全て想定に入れて、今回の金額の要求を出させていただいているものです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"要するにこれは、介護事業者の減収への補填対策だと。むしろ、国が減収を補償していくべきだという批判が多々あったと思うのですけれども、そういう観点から、区としても、この制度を設ける前の前提として、国に対して減収補填、利用料に負担を転嫁するのではなく、そもそも国が補償すべきではないかという要請を行うべきだったと、私は思うのですが、そういうことはやられたのですか。","respondent":"宮尾高齢者福祉課長","answer":"それで、国の方も今のところ、年度末までというような考えを持っているようです。それにつきましては、今ちょうど来年に向けて介護報酬が検討されているというふうに聞いておりますので、その動向をしっかりと見続けていきたいというふうに思っております。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"利用者間で不公平が生じるという問題点もあるのですけれども、その不公平が生じる原因となっているのは減収補填を利用料にかぶせたというところにあるとも思うのです。だから、私としては、その点も国に要請していただきたいと思うのですけれども、区のお考えとしては、その減収補填を利用料にかぶせた点に原因があるとはお考えになっていないのですか。その点、いかがでしょう。","respondent":"宮尾高齢者福祉課長","answer":"国も東京都も、この間、新型コロナウイルス感染症対策ということでいろいろな補助制度を設けたりしております。品川区が一保険者としてこの点に関して要請等を行うという具体的な考えは現時点ではございません。","id":"exchange-005"},{"speaker":"おくの委員","kind":"質問・要望","question":"それで次に行きたいと思います。介護サービス従事者、高齢者福祉施設で２,７００人、障害福祉サービス従事者あるいは障害者福祉施設で８００人ということで、全て対象になさっているということでしたが、高齢者福祉施設での２,７００人に、例えば、車の運転手の方は含まれているのでしょうか。含まれていないというふうにも聞いたのですけれど、いかがでしょうか。それをお伺いいたします。いかがでしょう。","respondent":"宮尾高齢者福祉課長","answer":"したがいまして、現時点では、実際に運転手を対象に含めるとどのぐらいの増になるのかというところもありますので、そちらにつきましては引き続き検討してまいりたいというふうに思っております。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"それで、目的として、７月中旬以降に利用者・職員の感染例が報告されているということからＰＣＲ検査をやったと書いてあるのですけれども、高齢者、それから障害者施設での感染例の報告、どのぐらいの感染例があったのか。そして、そういうところでクラスターの発生はなかったのか。その点についてお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長","answer":"そのうち、クラスターということですので５人以上というところかと思いますが、２カ所で５人以上の感染例が報告をされてあります。そういったことを含めまして、今回、ＰＣＲ検査の実施につながる一つのきっかけになったです。今お尋ねの感染例についてのご報告ですが、障害者施設のほうは１例、１事業所でございました。クラスターの発生はございません。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"都が同じようにＰＣＲ検査の補正予算を組んでいると思うのですけれども、その都の補正予算が通れば、またもう一度こういう検査をやるという予定なのでしょうか。やはりこういう施設ですから、定期的にやるのが最も望ましいと思うのですけれども、定期的にやっていくご予定あるいはご計画はあるのでしょうか、お伺いいたします。","respondent":"宮尾高齢者福祉課長","answer":"定期的に実施をしていくかというお尋ねですが、まず今回一回やってみて、どのぐらい陽性の方が出られるのか。それから実施体制、実施方法はこれでいいのかというようなことを検証して、次に向けて検討していきたいというふうに考えております。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問・要望","question":"要望しておきます。それから、障害福祉サービスのほうですけれども、ＰＣＲ検査の実施で、内容の対象人数８００人となっていますところに、施設系サービスと在宅系サービス、それぞれ７００人、１００人と書いてあるのですが、この施設系サービス、在宅系サービスとはどういう分け方なのでしょうか。この資料の読み方がちょっとよく分からなかったので、すみません。","respondent":"松山障害者福祉課長","answer":"施設系サービスというのは、施設においてサービスを直接提供するという従事者を示しています。在宅系サービスというのは、ホームヘルプといったように居宅を訪問して、在宅サービスへの支援をするサービスのことを示しております。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"荏原医師会に休日診療で４８０万円という予算が組まれています。そのときに、１,５００万円から２,０００万円ぐらいかかるのだというふうに伺いました。それで品川区に対しても毎年要求しているというふうに伺いました。ところが、この補正予算では４８０万円しか組まれていない。何でこれだけしか組まれないのでしょうか。非常に不十分な予算だと思うのですけれども、その理由、根拠を伺いたいと思います。","respondent":"高山健康課長","answer":"これを、現在、患者数が減っているということで、完全なる補償というのはこの仕組みになじまないということで、あくまでも、例えばこの場合で申しますと、新型コロナウイルス感染症の影響によって、通常よりも特別な支出を強いられているとか、あるいは若干なりとも布陣。","id":"exchange-010"},{"speaker":"おくの委員","kind":"質問","question":"今のご説明ではちょっと納得できないのですが、実際に業務をやっていらっしゃる医師会の方が、これだけかかっているというお話なのに、要するにそれを出せないということは、ボランティアでやれといっているのに等しいような話になるのではないですか。違いますか。出すのが当たり前ではないですか。","respondent":"高山健康課長","answer":"区の委託料で全てを賄うという、元よりの仕組みではございませんので、先ほどの説明の繰り返しになりますけれども、特別な負担をこの間していただいているといった意味で、私どもとしましては報いるというような意味合いも込めまして、追加的に委託料を、といった趣旨のものです。","id":"exchange-011"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、私の素朴な理解ですと、この医師会の方々は、休日診療の業務を辞めてしまってもいいと、なくなってもいいというような、私だったら辞めてしまうな、という気もするのですが、そういうことなのでしょうか。","respondent":"高山健康課長","answer":"医師会サイドとしましては、やはりこれは地域貢献、地域医療に貢献する事業ということで、コロナ禍において、いろいろな会員の方には様々なご意見がある中でも、会としてやはり続けていく事業だという、強い使命感をお持ちですので。","id":"exchange-012"},{"speaker":"おくの委員","kind":"質問・要望","question":"それを要望しまして次に行きます。それから、この慰労金のほうですけれども、おおざっぱに医療従事者ということですが、外来、診察治療等に従事した方ですけれども、例えば１回こっきりちらっと診察したようなお医者さん、そういう方も含めるのでしょうか。それとも、継続的に入院した患者さんを診たような人だけを対象にしているのでしょうか。いかがでしょうか。その点、お伺いいたします。","respondent":"高山健康課長","answer":"１点目の金額面の算出根拠の考え方ですが、まず医療機関の支援に関しましては、これは新型コロナウイルス感染症に関わらずということで、医療機関が公表している入院日数が平均的に１０日前後だということ、これに１日１万円相当を掛けまして。","id":"exchange-013"},{"speaker":"おくの委員","kind":"質問","question":"１回こっきり診察したような方も含まれるのですか。","respondent":"高山健康課長","answer":"そういう意味では、これから病院サイドのほうといろいろお話を詰めていく中で、やはり予算にも限りがありますので、また、主に対象としていきたい方などの絞り込みをかけるなかで、例えば、今委員がご指摘になったような方も病院としてはねぎらいたいというようなことであれば。","id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"３つ目が、患者受入医療機関支援金なのですけれども、先ほどのやり取りを聞いていて、これは我々の会派としてはまさに大田区も１０万円、区内の７医療機関でやっていますので、この前の一般質問でも創設というのを要望していましたが、まさにそのとおり計上されたということで、歓迎したいのですけれども、その入院患者５４０名というところの積算根拠、要するに。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長、高山健康課長","answer":"それによりまして、例えば季節によってはこの場所で使える、この場所では使えないというところがあろうかと思いますので、聞き取りをする中で。２点目の、ダクト工事が可能かということにつきましては、指定管理者が既に工事業者から見積もりを取っておりまして。さらなる補正などが必要かどうかという点につきましては、入院患者数の今後の推移などを見ながら検討させていただきたいと考えております。","id":"exchange-015"},{"speaker":"あくつ委員","kind":"確認","question":"立ち入って申し訳ないのですが、どういうふうに考えるのかということが１点。そのときは、名称でいうと感染症診療協力医療機関というところでお話があったと思うのですけれども、この支援金と慰労金について、この３病院を想定しているというふうに考えていいのかどうか、これだけ確認をさせてください。","respondent":"宮尾高齢者福祉課長、高山健康課長","answer":"ですので、これを使うことによって、先ほどもご答弁させていただきましたが、部屋を固定することなく、その施設の実情に合わせて設置場所を設定できるというものを考えているところです。一応両支援の仕組みとも同じ医療機関、病院を対象としているということで考えております。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問","question":"新型コロナウイルス感染症のＰＣＲ検査を事業者にということで、先ほども説明があって、このお考えでいくのだろうということで、まずこの表の見方で、今回、補正予算額があって、新型コロナウイルス感染症対応地方創生臨時交付金を活用予定と書いてあるのだけれど、僕らがもらっている予算書にも、それぞれ２,５００万円と５００万円使うと書いてあって、今日の説明の活用予定というのは、活用しますよ。","respondent":"宮尾高齢者福祉課長","answer":"資料に新型コロナウイルス感染症対応地方創生臨時交付金を活用予定というふうに表記をさせていただいたところですけれども、こちらはあくまでもこの内容でいたしますという意味合いで、予定という言葉を入れさせていただきました。ただ、実際に活用いたします、です。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その上でちょっとお聞きしたいのですけれども、今、実際に利用者に同意を得て介護報酬を２段階上にして取っているというところがどれくらいあるのかということを、把握されていたらお聞かせください。そういった場合、この事業者が全て請求したということを前提にして組まれた予算なのかということの確認をさせていただきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"ただ、議会のほうでご承認をいただいたら、各事業所にしっかりと速やかに案内をさせていただいて、こういう制度を今回ご提案しますので、これを踏まえた上でご利用者に引き続き丁寧なご説明をしてくださいというように考えているところです。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"デイサービスが６６０人と、これはデイサービスを使っている方全てが対象と考えられているわけではないと。その中でこういう人、という対象の絞り方みたいなのは何かあるのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"ただ、ご本人にこういう制度のあるなしにかかわらず同意はしませんと言われれば、それはもう、ご本人の意思を尊重せざるを得ないというふうに考えておりますし、またこういう制度があるといっても、事業者の判断で、いや。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"３番目のＰＣＲ検査の実施についてですけど、これも私は事業者の方々から高齢者に接する中で大変不安だという声はずっと伺っていましたので、こういう形で区としてＰＣＲ検査をやっていただくということになったのは、第一歩として本当に評価をしたいと考えています。直接処遇の方だけということですけど、これも私は、もっと拡大をしてほしいなと思っています。取りあえずその点をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"資料に記載をさせていただいている1)から4)にそれぞれ配置をしたいというふうに考えております。ただ、基本的には１施設１台、施設の規模を考えまして、それぞれ施設のほうとやり取りをさせていただいて、１施設に１台を設置する予定です。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"提案","question":"ありがとうございました。ＰＣＲ検査については、これは第一報ということでよかったと考えていますけど、東京都のほうでも同じような形で提案がされていると思うのです。そういう点では東京都のほうの補正が通ったらさらに広げていただきたいと思いますし、定期的にやるという方向でもぜひご検討いただきたいと思います。","respondent":"高山健康課長","answer":"しかしながら、東京都のほうでこの支援の仕組みを表に出したのが大体７月の終わりぐらいということで、医療機関のほうでは、まさにその第一段階で対象者の選定をしている過程かと思いますので、そうした申請の状況なども伺う中で、対象の範囲につきましては。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それに対して、本来であれば、国が損失補填という形でやるべきだと私は思うのですけど、まだまだそういうことにはなっておりませんので、その辺のところは区としても、こういう形の慰労金や医療機関に対しての支援金という形で出されるということは、一歩評価ですけれども、今後ともぜひ、この支援については国に対しても言っていただきたいと思いますし、区としてもつかみながら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、その一方で、介護保険のほうで考えると単純に３,０００万円余の９倍で２億８,０００万円の介護給付が行われるということですので、介護保険特別会計という大きな枠で考えたときに、これをやるなという意味ではなくて、全体を見たときにどのような負担増で、それで見込みですね、介護保険特別会計の中で、その分介護給付が増えるわけですので。","respondent":"宮尾高齢者福祉課長","answer":"一方で、これも委員がおっしゃっていたように、利用控えが若干あるということで、前年と比べると、利用が若干下がっているという状況もあります。そこと相殺されてどのようになっていくかというところは、引き続きしっかり見守っていきたいと考えています。","id":"exchange-023"},{"speaker":"鈴木（博）委員長","kind":"質問","question":"ＰＣＲ検査のことですけど、一応唾液を使ってやるというお話なのですが、行政検査の場だと、唾液を使ってやる場合は、まず採る場合に手袋をすることと、採った後の感染予防に気をつけること、あと保管というのが非常に大事なので、さっきあくつ委員が言ったみたいに、結局唾液の場合、正確さというのが、きちんと保管できるかどうかなのですけど、その根拠というのはあるのですか、ということが１つ。","respondent":"鷹箸保健予防課長、宮尾高齢者福祉課長","answer":"陽性者が出ました場合には当然、そちらの医療機関から発生届が出てまいりますので、これまで同様、陽性者に対して、１人発生しましたらその方の濃厚接触者、それから発症前の１４日。実際に今回の検査をやらせていただいて、陽性者が出たときの対応ですけれども、例えば通所系施設ですと、複数のスタッフで出たときに、ケアマネジメントによって、例えばほかのサービス事業所に割り振る。","id":"exchange-024"}]},{"id":"topic-02","title":"続きまして、第５９号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例の一部を改正する条例","agenda":"続きまして、第５９号議案 品川区指定居宅介護支援等の事業の人員および運営の基準等に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"主任介護支援専門員ということで、いわゆる主任ケアマネということだと思いますが、この主任ケアマネになるための要件というか、どうやったらなれるかということで、初歩的なことですけれども、結構大変なことなのでしょうか。１つお伺いします。それと、置けなくて困っている事業所は何カ所あったのでしょうか。結局、この品川区で一体どういう問題があったのかと。そのあたりをお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"それに向けては今回の改正の趣旨を丁寧に説明して、置くことが原則だというところをしっかりと踏まえた上で、ではそこから先、現実的にどうしていったらいいかというところをしっかりと丁寧に相談に乗ってまいりたいというふうに考えております。","id":"exchange-025"},{"speaker":"おくの委員","kind":"質問","question":"５年以上の実務経験があって研修が必要だということで、そうすると、最初の法律の改正ですね、国の改正に若干無理があったということなのでしょうか。あるいは、その態勢を整えていくのに何かしんどかったというか遅れていたというか、品川区が特別に遅れていたのですか。それとも、法律が改正されているから全国的な問題だったのですか。法律に若干無理があったというような問題と捉えてよいのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"ただ、繰り返しになりますが、それによって何かサービスが滞ったり、相談業務に支障が出るとか、そういったことは一切ございませんので、そこにつきましては今後もしっかりと対応してまいりたいと考えています。","id":"exchange-026"},{"speaker":"おくの委員","kind":"意見","question":"もう１点だけ、すみません。今のお答えの中に含まれていたようにも思うのですけれど、主任ケアマネの有無によって、その業務の内容そのものに大きな違いが出てくるというわけでもないのですね。お願いします。","respondent":"宮尾高齢者福祉課長","answer":"ただ１点付け加えしますと、来年の３月末に向けて、品川区も引き続き、法の趣旨を踏まえて主任ケアマネジャーをしっかりと配置していただくように、ということで、今、３割未配置でありますけれども、これを限りなくゼロに近づけていく。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これが延期されなければ、居宅介護支援事業所を続けていくことができないというようなお話も事業所から伺っていましたので、よかったなと思っています。それを受けるためのキャパというのはしっかりと東京都で補償されているのかということと、この研修そのものが何時間くらいの研修になるのか、それをちょっと伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"都の研修時間が何時間というところは、すみません、今手元に詳しい資料がないのですが、例えばこの時間があまりにも膨大で、それがネックになっているというところまでの認識はしていないところですが、一方で、先ほどから申し上げているように。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"なので、この研修の年２回の枠がきちんとそういうことが受けられる枠なのかどうかというあたりも、区としても把握していただいて、全員が受けられるような枠がなければ、東京都に対して働きかけをぜひ行っていただきたいなと思います。それと、ちょっと記憶があやふやですけど、この研修そのものがたしか１週間とか、結構かかるような気がするのです。","respondent":"宮尾高齢者福祉課長","answer":"今回、その困難な事由というところになりますけれども、それはしっかりと今回の国の省令の制度改正の趣旨を踏まえて、適切に対応していきたいというふうに考えております。","id":"exchange-029"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"取りあえずこれで努力していただくけれども、それで確保ができなかったとしても、居宅介護支援事業所を続けられないということはないですよ、ということが保証されると考えていいのでしょうか。","respondent":"宮尾高齢者福祉課長","answer":"ただ、今回の厚生労働省令の改正の趣旨をしっかりと踏まえて、全事業所が主任ケアマネを配置できるように検討してまいりたいと思います。","id":"exchange-030"},{"speaker":"あくつ委員","kind":"確認","question":"今の鈴木副委員長の最後の質問にも関係するのですけど、文言の読み方で、この資料を見ると、現行と改正案があって、（１）と（２）と。（２）の上で（１）が認められると、こういう意味なのか、６年後に万が一確保できない場合でもこういうものを出せば許されるよ、という意味なのか、そこだけちょっと確認させてほしいのです。","respondent":"宮尾高齢者福祉課長","answer":"（２）、これはどういう場合かというと、例えば来年の４月１日で人事異動があって、管理者がＡさんからＢさんに替わられるというときは、原則として主任介護支援専門員でなければならない。","id":"exchange-031"},{"speaker":"あくつ委員","kind":"確認","question":"最後に確認ですけど、（２）の場合も、その計画書を出せば、いわゆる６年間、令和９年までそれは認められるよという意味なのかということが１つ。それと、これは今回の文言の中では読み取れなかったのですけど、どこかに書いてあるのですか。それとも別の何かで定めているのか。","respondent":"宮尾高齢者福祉課長","answer":"ただいま私が申し上げた説明の内容について、今回の新旧対照表以外に何かあるかというと、ないです。今回の新旧対照表が全てです。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"確認","question":"分かりました。網羅されている、説明はよく分かりました。救済措置ということで、この６年間延ばしたというのは、今やっている人が、介護支援専門員であれば５年間実務経験をして、６年後にはなっているだろうということで、６年延ばしたというように聞いていますので、それは特に問題ないのかなと思いますけど、ちょっと読み取れなかったので確認させていただきました。","respondent":"宮尾高齢者福祉課長","answer":"今、委員からお話しいただいたことを踏まえて、こちらの条例をお認めいただいた後、実際に各事業所のほうへの案内等、実務の段階に入っていきますけれども、そのときに、今いただいた趣旨を踏まえて。","id":"exchange-033"},{"speaker":"おくの委員","kind":"意見","question":"今のあくつ委員と鈴木副委員長のお話を聞きながら、新旧対照表などを見ていて思ったのですけど、この（２）の特例の話は、要するに令和９年以降もこの特例が通用するという理解でよろしいですね、第５条第２項にこの特例が定めてありますよね。","respondent":"宮尾高齢者福祉課長","answer":"今私が申し上げた（２）に関しましても、（１）と同様に令和９年３月３１日までの特例です。","id":"exchange-034"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、この新旧対照表の新の第５条第２項のただし書というのは、令和９年で廃止されるわけですか。","respondent":"宮尾高齢者福祉課長","answer":"令和９年３月３１日をもって実際にどういう条文になるのかというのは、また、そのときに備えてしっかりとやってまいりますが、先ほどの資料の改正案（１）、（２）、繰り返しになりますが、これは令和９年３月３１日までの措置だという認識でおります。","id":"exchange-035"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"啓発が大事だというところは、区としても認識をされているということですけれども、その啓発という点では、私は事業者に任せることなく、区としてもぜひやるべきではないかなというふうに思うのですけど、それが１点、いかがでしょうか。そこのところも含めて総合的に検討するというのが前回のご答弁だったと思うのですが、その点はいかがでしょうか。","respondent":"寺嶋福祉計画課長","answer":"それが今、ついていないという実態につきましては、助成制度の問題ではなく、正しい理解の普及啓発にあるというのが、業界団体等の報告にも書いておりますので、区としてはその部分について同様の認識だというふうに申し上げたところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それは３カ月とか人によっては半年とか、そういう形で微妙な調整をしながらやることで、聞こえをしっかりと確保することができるということで、その微妙な調整をしながら、早期に着用して、そして難聴を普通の生活にしていくという、そういう対策が必要だということがすごく強調されているわけですけど、そこのところ、早期に着用して。","respondent":"寺嶋福祉計画課長","answer":"加齢性難聴の方が補聴器を早期につけることがいいという、専門家、耳鼻科等の方の見解については、我々は医療機関ではないので否定はできませんし、そういう意見があるということも重々認識をしているということで、同様の認識だと申し上げたところです。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"前回は、そこのところが共通の認識にならなかったので、補聴器を早期につけて、そして加齢性難聴の方が難聴があっても補聴器によって通常の生活を継続させていくということが重要だ、必要だ、有効だ、そこのところは認識が一致したということで確認させていただいていいでしょうか。","respondent":"寺嶋福祉計画課長","answer":"先ほども申し上げたように、医療機器のことについて断定的なことを申し上げているわけではなく、補聴器に効果があるといった、耳鼻科等の見解については我々も否定するものではないということで、私の立場から言えることは、コミュニケーションをしっかり取ることが重要なので。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"耳鼻科の先生方がそういうふうに言われているということは否定しないということですけれども、その点は耳鼻科学会があえてそういうことを主張して、そして加齢性難聴者の方に対して補聴器を早期に着用して、生活の質を保っていくということをすごく強調されていますので、そういうふうに耳鼻科の先生が言っているということを認識している、それを否定しないというだけではなくて、それを受けて。","respondent":"寺嶋福祉計画課長","answer":"それで、どちらにもこの点は該当すると思いますので、例えば取上げる取上げないを含めてですけれども、今の段階ではまだ、そういった意味で組織として対応する意味では、庶務担当課である福祉計画課のほうで合わせてご答弁をさせていただいているところです。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"生活の質を変えてしまう重要な問題が難聴だということの認識を伺いたいのですけど、そして難聴になったことで、認知症のリスクとして最も高いのが難聴だということでも、２０１７年のアルツハイマー学会のところでそういうようなことで言われていますし、ＷＨＯでも早期に、４１デシベルぐらいになったところで既に補聴器をつけることがすごく大事なんだというようなことで強調されているわけではないですか。","respondent":"寺嶋福祉計画課長","answer":"認知症それから高齢者の生活全般で難聴だけではなく、例えば目が見えにくくなってきた、体が思ったほど動かなくなってきた、全てが重要であるので、難聴だけをあえて重要と捉えているわけではなく、全てが重要だというふうに認識をしています。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"お金の問題でつけないという人は、アンケートで少ないということなのですけど、でも、実際は本当に高いわけです。それはいかがでしょうか。だから補聴器を早期につけるということが、区としても必要だということを認められるのであれば、そういうところにぜひいっていただきたいと思うのですが、どうでしょう。","respondent":"寺嶋福祉計画課長","answer":"繰り返しになりますが、補聴器の有効性自体を全く否定はしておりません。ただ、実際に購入をしても使わないという方もそれなりにいらっしゃるという報告もある中で、補助制度というものについて、今の段階で考える時点ではないということを申し上げているところです。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"だから専門家をしっかりと、区によっては専門家を置いて、そしてその辺の調整も含めて啓発をしているという区もありますけれども、そういうところで、使わないからそれを全て業者が啓発すればいいのだという、そういう姿勢で、区としていいのかというふうに思うのですけど、区として早期につけることが必要だ、そして微妙な調整をすることで生活の質を保つことができるのだ、そこのところが。","respondent":"寺嶋福祉計画課長","answer":"専門の方を配置している自治体があるということについて、私、不勉強でまだそこまでは把握していないので、引き続き調べたいと思いますけれども、業者任せにしているわけではなく、専門性がありますので、専門の方にぜひそこはお願いしたいということを申し上げているものです。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回私は、前回より一歩進んだなと思います。それから、高齢者の皆さんに関わっている、難聴で本当に困っている、だけどそれがそのまま放置されている。先進国の中でも補聴器が最も少ない、そういうふうになっているわけですから、そういうところでは、ぜひ区としても取組んでいただきたいということを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"自民党に。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"委員同士で議論するというのも請願はいいのですよ。そういうことなので、ぜひ自民党が要望された思いですとか、やはり補聴器の補助をすべきだというようなお考えなのか、その辺のところをお聞かせいただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"渡辺委員","kind":"意見","question":"端的に言いますと、会派ごとで調査研究は常にどの政策分野もやっていると。そのうちの一つと考えています。先ほど、区のほうのご答弁にもあったように、それぞれの施策、これは補聴器が全てではなくて、それぞれの高齢者に関する課題、それぞれ今、調査研究で上げている、そのさなかという表現だったかと記憶しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"補聴器購入費の補助を要望したというようなニュースだったと思うのです。そういった意味では、補聴器はやはり区としてもしてほしいという、そういうのが自民党の考えなのかなというふうに思ったのですけど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"渡辺委員","kind":"質問・要望","question":"まさにそのとおり、私たちは普段、当たり前のように政策の要望をする。そして、区のほうの見解を聞きながら、長所も短所もある、そして課題もあると。課題があればまた調査研究を続けなければいけない、まさにそのさなかと考えています。課題もある。だから、今どうしよう、要望も、やり取りはどの政策についても同じです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"自民党もそういうようなことで要望されているということですね。公明党はこの補聴器補助制度についていかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"渡辺委員","kind":"質問・要望","question":"今、要望だけを切り取られると誤解を招くので、要望をする、そして課題も考え、踏まえて、それぞれ判断していくと。要望だけを切り取られると非常に困りますので、要望する、そして長所も短所もある、課題もある。それを踏まえて、その場、その場で政策の判断をしていく、それが私たちの姿勢です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。先ほどのご答弁にもありますように、補聴器は細かいメンテナンスが必要で、個別性も高いものだと思いますので、医療機関、専門機関でしっかりと受診していただくことを高齢者の方々に引き続き伝えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"渡部委員","kind":"質問・要望","question":"その結果、それが何か月かたったら話が変わるかもしれないわけですから、それを請願をやっているところで、委員会ですから、各委員に同意を求めるのは結構ですけれども、多分どこの会派もそうですけど、自分たちの会派としてそれはしっかり調査研究をやっていることでありますから、少なくともここで賛否の決を採るときに、あなたたちの会派はどうで、この人たちの会派はどうだからこういうことを。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"というのが議会だと思いますので、ほかの会派が賛成でしたよね、というのは関係ないことですから、共産党がどうなのかということだけしっかり言っていただければ、私たちは会派の代表で来ているのですから、そこはしっかり意見は述べさせていただこうと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問・要望","question":"繰り返すとまたあれになってしまうので、１つ挙げれば使用率が低いとか、あとは今ここに記載がある８区、９区という中でも、２万円から３万５,０００円ぐらい、現物支給というところもありますが、果たして、そういう公的助成をしたことによって、この請願の中にも書いてありますが、１５万円から３０万円という高額なものを買えるのかどうかというところ、それが本当にインセンティブになって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"おくの委員","kind":"確認","question":"本日、結論を出すで、採択でお願いします。今日の議論から、早期着用が必要だというところは確認されたと思います。それで、助成が必要ないということに根拠があるとは思いませんので、何らかの助成制度はやはりあったほうがよいと、あるべきだというふうに思いますので、採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今日、結論を出すということで、不採択でお願いします。先ほどの理事者の方のご説明も納得することができました。そういうところの理解をいただいたりする、そういった普及啓発活動をまずやっていただいて、様々な取組みをされているとお話ししていますが、先ほどちょっと議論があったように、不十分なところもあると思いますので、そのあたりをまずしっかりやっていただくということを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"}]},{"id":"topic-04","title":"令和２年陳情第３７号「荏原地域に障害者施設の整備を具体的に進めることを求める陳情」","agenda":"令和２年陳情第３７号「荏原地域に障害者施設の整備を具体的に進めることを求める陳情」","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今、小山台と、それからグループホームをやられているということで、１０件ほどということだと思うのですけれども、障害福祉計画の中にもこれからやっていくということで、この障害福祉計画に書いてあることは、今言われたことで今のところ尽きているという理解でよろしいのでしょうか。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"１点目は計画の実現に向けた方策についてのご質問かと思います。今、ご紹介させていただきました１０件というものの中にはグループホームに限らず、就労継続支援Ｂ型等の事業所も入ってあります。第６期のほうに盛り込むかどうかというご質問についてですけれども、現在計画策定委員において、まだ案の段階ではあるのですけれども、主要テーマと今後の取組みというところで、事業所整備についても触れているところです。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"ホームページで、「荏原地区福祉施設機能検討支援委託に係る簡易型プロポーザル実施要領」という資料を見つけたのですけれども、これは今の荏原地区のそういう増設計画などに関係のある資料なのでしょうか、お伺いいたします。","respondent":"松山障害者福祉課長","answer":"荏原地区福祉施設機能検討支援委託に係るプロポーザルを今年度予定しております。","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、荏原地区の施設の充実化ということには、あまり直結しない資料ということですか。","respondent":"松山障害者福祉課長","answer":"２つの施設とも老朽化により、やはり検討が必要だということは議会でも申し上げてきたものですので、こちらのほうと、荏原地区で民間事業者を誘致して積極的に促進するというのは、また別な方向からのアプローチということになります。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"荏原地区に関わって荏原四中の跡地があるのですが、ここも本当に適切な土地だと思うのですけれど、ここにそういう福祉施設、障害者施設をぜひ建ててほしいと思っているのですが、そういう計画はないのでしょうか。あるなしにかかわらず、障害者福祉課からも要望を出していただきたいと思うのですけれども、その点はいかがでしょうか。","respondent":"松山障害者福祉課長","answer":"荏原四中といった区全体に関わるものにつきましては、私どもの所管というよりは企画調整課のほうの取扱いになっておりますので、区全体の中で総合的に考えて判断をしていくものと認識しております。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問・要望","question":"障害者福祉課から要望を出すというようなことも、お考えになっていないということでしょうか。","respondent":"松山障害者福祉課長","answer":"障害者福祉課としましては、様々な手段を使いながら、活用しながら、当然、区の内部に要望を上げていくということは以前からしておりますし、今後もそのようにしていきたいと考えています。","id":"exchange-061"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今日のお話を伺っても、グループホームの独自助成を１００カ所に案内したり、区内にある事業所に対して電話をして、ぜひ誘致したいという積極的な働きかけをしていただいていたり、その決意をこういう形で取組んでいただいているのだと思うのです。そこは本当に評価をするところです。その２点をお願いします。","respondent":"松山障害者福祉課長","answer":"２点目の林試の森、旧小山台住宅のところですけれども、住民説明会のほうでは、児童発達支援センター、それと就労継続支援Ｂ型というところを、現段階での案という形でお示しさせていただいているところです。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところなしには、２３区の中でも少ないレベルになっているこういう施設サービスの状況を改善させることはできないのではないかと思うのですけれども、これから６期の計画に向けても関わってきますので、そこら辺のところ民間を誘致するというだけではなくて、区として建てていく方針が必要なのではないかと思うのですけれども、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"１点目の何を何カ所というご質問ですけれども、現時点では今後の建築確認、東京都への協議が必要だということなので、具体的にはまだお伝えできない段階です。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それからもう一つ、この陳情の中で、特別支援学校からの卒業生が毎年増えていくことを考えると、早急に整備しないとと書かれているのですけれども、これは特別支援学校とかから、例えば来年４月にはどのぐらい卒業生が出てきて、就労継続支援Ｂ型とか生活介護にしても、どれぐらい受入れる必要があるのか、その辺の人数もおおよそ分かったら教えていただきたいと思います。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"区のほうでは、当然ながら障害のある方皆様を安心させたいという気持ちは持っており、具体的な計画になりましたらきちんとお伝えしたいと考えていますが、今のところそれがお伝えできる段階ではございません。特別支援学校の卒業生の見込みですけれども、生活介護を利用される方は、七、八人程度だろうと見込んでおります。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"そうすると、総合支援施設のほうでそういう卒業生を受入れるために、一番初めの利用率を１００％にしないで５０％ぐらいに抑えて受入れているという部分がありますね。先ほど利用率３５％ということでしたが、その卒業生が路頭に迷うことなく、受入れることは可能だと考えていいのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"受入れ枠としてはありますので、問題ございません。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"これができなかった一番の理由、ネックになっているものは何があると考えられているのでしょうか。","respondent":"松山障害者福祉課長","answer":"区としてはできることを今精一杯やらせていただいておりますので、引き続き努力していきたいと考えています。","id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういう点では、やはり土地も、もう区が計画を立てたわけですから、この計画を実現させるために、道路と同じような形で、私は道路はやめるべきだという立場ですけれども、道路があれだけ土地を確保できているわけですから、それ以上に福祉を充実させるというのが自治体の責務なわけですから、そこのところは土地を確保して、ぜひ区として。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"西村委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。既にご説明がありましたように、荏原地域で具体的な整備計画が示され、一事業所ずつ電話をするなどご努力いただいていることが確認できましたので、本陳情に関しましては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"渡部委員","kind":"質問","question":"本日結論を出すで、不採択でお願いいたします。説明を伺っていまして、これから荏原のほうに障害者施設をというのは、恐らく私たち議員一同も願っているところでございまして、それに向けて着々と進んでいるですので、引き続きよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。先ほどから質疑、説明でもございましたように、この陳情で求められている後半の部分は着実に早急に推進するようにということで、これは進められているということも確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。まだ計画されただけで、具体的に成果が上がっているわけではありません。いよいよこれからだというときですので、これからどんどん後押しをする意味でもこの陳情を採択して、後押しをしていきたいと思います。採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-071"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"本日結論を出すということでお願いします。不採択です。区のほうも不足している現状は認識して、課題だと捉えて計画を立てているということです。第６期にもその旨盛り込んでいくという説明がありました。さらにスピード感を持って進めていってほしいということは要望いたしますが、この陳情に関しては、不採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-072"}]},{"id":"topic-05","title":"令和２年陳情第３８号「医療的ケアを必要とする障害者が週５日通える生活介護の整備を求める陳情」","agenda":"令和２年陳情第３８号「医療的ケアを必要とする障害者が週５日通える生活介護の整備を求める陳情」","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"今のご説明ですと、心身障害者福祉会館のほうが来年４月から５日体制で、ピッコロのほうはいつ頃からどういう体制になるのか、その予定を分かる限り教えていただきたいと思います。それからもう一つ、そもそもこういう医療的ケアの必要な方の需要、このように陳情が出てきていますけれども、品川区内で一体どのぐらいあるのかということをつかんでいらっしゃるのでしょうか。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"ピッコロの定員変更等の予定ですけれども、今現在東京都に相談しているところで、できましたら来年４月からという形で思ってはおります。医療的ケアのニーズにつきましてですが、これは現在計画策定委員会においてちょうど進めているところですが、昨年度基礎調査を実施いたしました。先ほどの予定の部分ですけれども、１点、人材確保のほかに環境整備といった工事をする必要があるものについては。","id":"exchange-073"},{"speaker":"おくの委員","kind":"質問・要望","question":"それを分かる限り、できるだけ具体的に教えていただきたいのです。それから、ニーズを把握しているということですけれども、具体的な数字としてどういうものなのでしょうか。そしてそのニーズに関連して、今年３月にアンケートを取られていて、集計の仕方がおかしいということで、これからクロス集計をやるのだというようなお話があったと思うのですが、そのクロス集計はもうやられたのでしょうか。","respondent":"築山障害者施策推進担当課長","answer":"ニーズに関してですけれども、その前に基礎調査のクロス集計につきましては実施しておりまして、集計したものにつきましては、第１回障害福祉計画策定委員会におきまして、委員の方に配付をさせていただきました。ホームページにも公開しています。","id":"exchange-074"},{"speaker":"おくの委員","kind":"質問・要望","question":"ニーズのほうで具体的な数字が分かっていたら教えていただきたいのですが、要するに需要です。何人ほどのどういうニーズがあるかということで教えていただきたいのと、それから総合支援施設は一体何人を何日受入れられるかというような、ピッコロや心身障害者福祉会館のような形である程度分かっているなら教えていただきたい。","respondent":"築山障害者施策推進担当課長","answer":"医療的ケアの課題ですが、こちらにつきましては、やはり受入れ施設等、なかなか充足している状態ではないというところがありますので、受入れができる施設の整備、体制作りというところが今後の課題になってくるだろうと認識しております。","id":"exchange-075"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"何点か確認させていただきたいと思います。定員を変更するとなったら何名ぐらいまで可能なのか、それを１点お聞かせください。それともう一つ、総合支援施設ですけれども、重度の方５名というのは、来年の４月から生活介護で重度の方５名を受入れるということでいいのでしょうか。それは来年４月からを目指してやっていくのか、その確認をお願いします。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"そのため、定員変更等については東京都の承諾を得てという形になりますので、まだ今の時点ではお答えすることができませんけれども、できるだけ有効に使うような形で、東京都と調整をしている段階です。総合支援施設についてですけれども、来年の４月からピッコロや心身障害者福祉会館と同様の形で指定を取って始めるというのは、まだ難しいかなと考えています。","id":"exchange-076"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それと、私はこの中でも、ピッコロにしても多分今度の心身障害者福祉会館にしても、人工呼吸器をつけられた方を受け入れられていないというのがすごく大きな問題ではないかと思うのです。そういうところで言えば、人工呼吸器の方も預けられる仕組みを作ってほしいというのが切実な思いで訴えられているのですけれども、そこら辺については今後どのように整備していくお考えなのかお聞かせください。","respondent":"松山障害者福祉課長、築山障害者施策推進担当課長","answer":"私から、人工呼吸器の方に対する受入れの見込みというのをお伝えいたします。人工呼吸器を装着している方で安定した状況にある方については、区内で言いますと、ほわわという事業所が受入れを行っていたということがあります。やはり職員の育成というところが大きなところでございました。事業者といたしましても人材育成をやっていただきながら、それぞれの施設で受け入れられる体制を整えていけるように図っていきたいと考えています。","id":"exchange-077"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"人工呼吸器の方の、ほわわは私もちょっとよく存じていないのですけれども、ここは人工呼吸器をつけた大人の方も生活介護という形で受入れていただくところなのでしょうか。人工呼吸器をつけて、本来そのように受入れるところがあれば通所したいという需要というのは、区としてどうつかんでいらっしゃるのかということもお聞かせいただきたいと思います。","respondent":"松山障害者福祉課長","answer":"２点目ですけれども、人工呼吸器の方を受入れてほしいといったお声は頂いております。ただし、その方の状態に非常に左右される場合があるということと、どちらかというとやはりかかりつけ医、あるいは事業所と提携を結んでいる医師の判断によるところが大きいと認識しております。","id":"exchange-078"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その方に合わせて、状況を見ながら、これだけ落ち着いているのであればここのところで受入れられるのではないかということも含めてご検討いただいて、自分の子どもの介護と、また親の介護と、ダブルケアで本当に倒れてしまうのではないかと心配なぐらい大変な状況にありますので、そこら辺のところは毎回早急にと要望させていただいているところなのですけれども、倒れる前に早急な対応を。","respondent":"松山障害者福祉課長","answer":"医療的ケア児者の支援関係機関連絡会ですけれども、昨年度準備会を開催いたしました。今年度、メンバーを少し広げて実施していく予定ですけれども、関係機関の方に医師、看護師等医療職が多いことから、コロナ禍の中で日程調整が非常に厳しいところではあります。","id":"exchange-079"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"協議会というのはそもそも平成３０年度中に作るようにというのが国の方向だったと思うのです。それで準備会をしてから、もう既に丸１年以上ではないが、準備会は今年の３月でしたか。そういうところでは、いつ頃やるかという見通しもまだ立っていないという状況でしょうか。ぜひこれは早く立ててやっていただきたいと思うのですが、いかがでしょうか。","respondent":"松山障害者福祉課長","answer":"関係機関連絡会については、今、日程調整中です。その中で、ただ単に施策を作ることが目的ではなく、まずは情報共有を行って関係機関との連携を密にすることが、区の中で果たす一番の役割と認識しております。","id":"exchange-080"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"関係機関連絡会は、皆様コロナ禍で本当に大変な状況にあるのは重々承知していますけれども、医療的ケア児者の皆様も本当に大変で切実な状況がありますので、ぜひ一日も早く開いていただくようにお願いしておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"西村委員","kind":"確認","question":"本日結論を出すで、不採択でお願いいたします。各施設ごとに整備に向けて前向きに取組んでいただいていることが確認できましたので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"渡部委員","kind":"確認","question":"本日結論を出すということで、不採択でお願いいたします。今までちょっと知り得なかったような話も今日のご説明の中で出てきて、ピッコロが週５回預かる方向に向けて動き出しているという確認と、心身障害者福祉会館ですとかちょっと不勉強だったのですが、そういうことであれば、陳情の内容にもそぐう形で区が動いているということですので、問題ないかなと思いまして、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"あくつ委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。早いところではもう来年からできますというところですので、そのことをぜひ品川区を代表するうちの会の代表の方から出ていますので、しっかりお伝えしていただければというところで、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"おくの委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。まだまだ整っていない状況ですので、これから整えていくという意味で、採択で頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ただ、最後にちょっとお話があった関係機関連絡会準備会のほうは、新型コロナウイルス感染症の関係があって難しいかもしれませんが、そういった施設を整えていっていただいているので、トータルでそういう連絡会のほうで情報共有をしたり、さらに次の段階にということとしては必要だと思いますので、そちらの連絡会準備会のほうを進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"},{"speaker":"おくの委員","kind":"質問","question":"今、ご説明があって、濃厚接触者以外でもやられているということですが、その濃厚接触者以外の判断基準というのがもう一つよく分からないです。濃厚接触者というのは、基本的にはマスクを外して１ｍ以内で１５分というような基準ですね。あるいはまた別の基準を持っておられて、その基準で判断されているということなのでしょうか。それをお伺いいたします。","respondent":"鷹箸保健予防課長","answer":"それ以外に、先ほどの福祉部の補正予算の質疑でもあったところですが、例えば福祉施設等で陽性者が１人見つかり、その濃厚接触、具体的に５分とか１５分とかということでなくても、もし感染したら重症化しやすいといったような判断が前提にある場合は。","id":"exchange-087"},{"speaker":"おくの委員","kind":"質問","question":"今のＱ＆Ａに準じていると理解しておいてよろしいのでしょうか。","respondent":"鷹箸保健予防課長","answer":"委員ご指摘のとおりです。","id":"exchange-088"},{"speaker":"おくの委員","kind":"質問","question":"それで、先の補正予算であったのですけれども、介護施設、それから障害者施設の方に、１回きりですけれども拡大されました。それまではやる考えはないということだったと思うのですけれども、これは区の考え方がある程度変わったということで理解してよろしいのでしょうか。今後、対象を拡大していくという考えはおありなのでしょうか、どうでしょうか。","respondent":"鷹箸保健予防課長","answer":"今回介護事業者に対してＰＣＲ検査を拡大させていただいたのは、お１人陽性だった場合に、周りの方へ与える影響が非常に大きいという、国の方針の変更にも基づいて、今回そのような形で、職員の方等に対してまず１回ですけれども、検査をする方針になったということです。","id":"exchange-089"},{"speaker":"おくの委員","kind":"質問","question":"そうすると、さっきの補正予算の考え方も、Ｑ＆Ａにあった基準の準用、その考え方、精神から来たものだというわけですか。","respondent":"鷹箸保健予防課長","answer":"はい、ご指摘のとおりです。","id":"exchange-090"},{"speaker":"おくの委員","kind":"質問","question":"」とか、感染拡大や重症化を防止する観点から、「一定の高齢者や基礎疾患を有する者について市区町村において本人の希望により検査を行う場合に、国が支援する仕組みを設ける」とあるのですけれども、これも国の基準に準じて具体化する場合があり得ると理解してよろしいのでしょうか。","respondent":"鷹箸保健予防課長","answer":"後ほどご説明いたしますが、全てのケースにおきまして、おひとりおひとり陽性者の情報に基づいてその周りの方の感染可能性について、詳しく聞き取りをしていますので、その中で必要と判断した場合には。","id":"exchange-091"},{"speaker":"おくの委員","kind":"質問","question":"後ほど説明があるかと思いますが、そうしますと、必ずしもこの陳情の趣旨を否定しなくてもいいのではないかと私などは理解したりします。それから、専用アプリのＣＯＣＯＡがありますね。その専用相談窓口は結局設置されているのでしょうか。〔「ＣＯＣＯＡはこの陳情に関係ないのではないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"おくの委員","kind":"質問","question":"ＰＣＲ検査の範囲の問題として質問しているのですが、その相談件数は今までにどのぐらいあるのでしょうか。検査を行った人の人数はどのぐらいなのか、伺っておきたいと思います。","respondent":"鷹箸保健予防課長、鈴木（博）委員長","answer":"ＣＯＣＯＡについては、稼働したのが７月からでございまして、そこから見ると結構あるのですけれども、ＣＯＣＯＡの通知があった方ほぼ全てを対象とする。この陳情は「いつでも、どこでも、ＰＣＲ検査」等々と書いてあるので。戻りまして、この陳情を否定することにはならないのではないかというお話がありましたけれども、患者１人の発生届がありますと。","id":"exchange-093"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"仕組みを教えていただきたいのですが、東京都と契約している医療機関が５０カ所あるということを先日の一般質問の中でご答弁いただいたのですけれども、この５０カ所で行うＰＣＲ検査というのは、ドクターが必要と認めてドクターがやるというのと、保健所のほうからお願いして、それを医療機関にやってもらうのと両方あると思うのですけれども。","respondent":"鷹箸保健予防課長","answer":"その従業員が別のお店にも行っていて、そこでも多くの陽性者が見つかったというようなことを想定しての、広く面的な検査という方針だと確認しておりますので、今後につきましては、基本は陽性者の方が見つかりましたら、詳しい聞き取りの中で。","id":"exchange-094"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この５０カ所でやられた検査数というのは、今ではまだ把握できない仕組みになっているということなのでしょうか。それから、どのようなところなのかということも教えていただきたいと思います。それから、クラスターは全てプレスリリースされているわけでもないのかなという思いをしているのですけれど、そこの考え方についてもお聞かせいただきたいと思います。","respondent":"鷹箸保健予防課長","answer":"３つ質問を頂きました。５０カ所の数ですが、このあたりは、すみません、実はすごく変更があったところなので後段の所管事務調査で、詳しくご説明する予定なのですけれども、よろしいでしょうか。","id":"exchange-095"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私はクラスターが高齢者施設で２カ所、あと東大井で１カ所ということで、それ以上はちょっと知り得ないので、そのほかにクラスターがあるのであれば何カ所かというところが聞きたかったので、お願いしたいと思います。そこで先日私のほうからも、グラフの下に数字の一覧表を出していただきたいということでお願いして、早速出すようにしていただいてありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"それが、実際は６５人だったということで、数字を出していただくことで正確になって、私は改めてよかったのではないかと思っているのですけれども、そのところで、この陳情では「感染者の保護施設として区の施設を用意してください」ということが書かれているのですけれども、実際は軽症の方は東京都でホテルを借上げて、そこで保護隔離するという状況になっていると思うのですけれども。","respondent":"鷹箸保健予防課長","answer":"東京都のほうで準備をしているホテルですけれども、感染者の方の数に応じて、初め１つから始まって、４つぐらいまでいって、６月にはほとんど感染者の方がいなくなって１つ、２つになったのですが、７月、８月、また感染者の方がすごく増えて。","id":"exchange-097"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これから秋冬になるとさらなる感染拡大が懸念されると思うのですが、保健所の職員の皆様も本当に大変な中、長期間にわたって普段の業務に加えてこれが出てきたということで、もう限界という状況の中、ずっと頑張られている状況だと思うのですけれども、これから区としては、国が出した方針にのっとってやるだけということでずっと言われていますけれども。","respondent":"鷹箸保健予防課長","answer":"感染症対策ですが、特に今回の新型コロナウイルス感染症に関しましては呼吸器感染症ですけれども、例えばあるどこか決められた区域、あるいは地域だけで対策を講じて感染者の拡大を抑えられるというものではございませんので、考え方といたしましては三密を避けるですとか。","id":"exchange-098"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"だからそういうところでは、この新型コロナウイルス感染症というのは無症状の感染者が自覚なしに感染を広げるというのが特徴なわけですから、検査を拡大していかなければ、保護隔離するということにはならないわけなので、ぜひ検査を拡大して、世田谷区のように、日本全国がそういう形の対策を取るというのが収束に向けて最も効果的なものではないかと思いますし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"西村委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。様々ご説明いただきました。感染拡大防止を最優先にして、現状できる最大限の判断の中で精いっぱい取組んでいただいていると思っています。現状、今後の取組みなどのご説明に一定の理解を示しましたので、本陳情に関しましては不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-100"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですから、そういう人がだからと言って「検査やって、検査やって」というのが正しいのかと言ったら、全くそのようなことは思わないし、先ほどの公表にしても、どこで誰がかかったなどという話、それはいじめを増長させるだけであって、それが必要なわけない。その中でどれだけ出ているよというのがもうあるわけだから、そこで注意喚起になっているので、何を求めているかがさっぱり分からない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-101"},{"speaker":"あくつ委員","kind":"質問","question":"本日結論を出すで、不採択でお願いします。次にもう一件も審査しますけれど、２件まとめて意見申し上げます。様々な考え方があると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-102"},{"speaker":"おくの委員","kind":"意見","question":"本日結論を出すで、採択でお願いします。やはり無症状の感染者がいるのが新型コロナウイルス感染症の特徴で、のどや唾液にいるウイルスを見つけ出すという意味では私はＰＣＲ検査がほぼ１００％の有効性があると思っていますので、有効な対策だと思います。そのＰＣＲ検査で感染拡大を抑えていくという立場に立つべきだと思います。それゆえに、採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-103"},{"speaker":"高橋（し）委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いします。先ほどの補正予算でもＰＣＲ検査の拡大を行っていくわけですので、そういった形で現状取り得ることが行われていると考えていますので、この陳情に関しては不採択ということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-104"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"当然区が休みのとき等はつながらないので、東京都の電話番号等をご案内したのですけれども、それで確認をしたいのですが、資料２のフローの中で、接触確認アプリのＣＯＣＯＡの通知が来て、品川区のほうの電話相談センター、保健所というところで、ＰＣＲ検査は基本的に受けられますよ、受けさせてくださいねということで国のほうから８月２９日に通知が来たということで。","respondent":"鷹箸保健予防課長","answer":"３点ご質問いただきました。１番目、ＣＯＣＯＡの検査について、電話相談が来たらどのようにご案内をするかですが、先ほどおくの委員のご質問に答えたところですが、８月２４日以降、ＣＯＣＯＡの連絡が来たのだけれどもということで９３１件のお問合せ、相談がありました。","id":"exchange-105"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２ページの一番下のところで、自宅療養者にも食料およびパルスオキシメーターの配送をしているということですけれども、自宅療養の方はそこそこいらっしゃると思うのですが、その方は家族がいても、単身でも、希望すれば全てその食料とかを配送していただけるという仕組みになっているのでしょうか。そのことを伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"先ほどご説明したところですが、例えばその日に発生届が出て、つい先日の事例ですと朝発生届が出て、この方について、まず医師が患者に「あなた陽性ですよ」と説明する前に保健所から電話をしてしまったら大変なことになるので、初めて届出が出てくる医療機関ですと。","id":"exchange-106"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"そうすると、陽性の方が自宅療養している場合、具合が悪くなって救急車を呼ぶと、陽性だということで、防護服だったりそういう対応をした救急隊が来てくださるという仕組みになっているのでしょうか。そこの確認だけお願いします。","respondent":"鷹箸保健予防課長","answer":"場合によるのですが、救急隊を要請したときに、呼んだ方が初めから陽性と言われているのだけれどもと言われて、救急隊の方が防護服を着て現場に行くこともありますが、そういう説明がなくて、現場に行ったら実は昨日陽性と言われたといった場合には。","id":"exchange-107"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/334734?Template=document&Id=3576#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":92220,"voices":305}},{"id":"r02-20200923-8","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"建設委員会","time":"午前１０時００分～午後 ４時１３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を113件抜き出しています。","topics":[{"id":"topic-01","title":"第６０号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","agenda":"第６０号議案、品川区地区計画等の区域内における建築物の制限に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"意見","question":"今、ご説明いただきましたこの東五反田二丁目第３地区の計画は、区立日野学園の真南に位置しており、高さ１５１ｍのマンションと１１５ｍのオフィスビル、この２棟の超高層再開発を行うものです。このビルができれば、午前１０時から午後３時まで校舎に日影ができることになります。区は、都市計画審議会の質疑では、校舎に日照が当たるのは１時間か２時間程度と答弁されていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"はい、分かりました。その学校施設整備方針には、良好な日照を確保する必要がある、それが重要だということで書かれております。１時間から２時間で良好な日照を確保できるというお考えなのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"区としましても、総合的な判断をしながら、よりよい防災に配慮した建物であり、またこの住環境を含めた計画ということで、法令の中でできる限りの配慮をしていただいて進めていると、そういう事業だと認識しています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"今、複合日影で敷地に日が当たるのが１時間か２時間ということで、それが子どもたちの教育環境として適切なのかということだと思うのです。子どもたちが８時から３時、４時くらいまで学校にいるとすれば、五、六時間、その場所で過ごすことになるわけです。その中で一、二時間しか日照がない。それで本当に足りていると区は考えているのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問","question":"分かりました。そうしたら、こうした日照が１時間か２時間しか学校に当たらないという建築計画が適切なのかということで考えているのか、伺いたいと思います。先ほど、２０ｍ以上確保できるようにということ、また、より間隔を空けるように指導していきたいということで説明されてきたと思うのですけれども、実際にその当時よりも間隔を空けることはできたのか、そこのところも伺いたいと思います。","respondent":"多並都市開発課長","answer":"間隔につきましても２０ｍ以上確保ということで、最終的にはこれから建築の手続きに入っていきますけれども、それまでには２０ｍ以上確保できるということで、組合のほうからは報告を受けているところです。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"法令の中で指導していくということですけれども、特に日野学園は区立の学校ですから、子どもの教育環境を整備していくというのがやはり区の責務でもありますし、きちんと日照を確保していくということで指導していくことが必要だと思います。単純に今までの最高の倍になってしまうというのは、都市計画上、不自然というか、根拠が分からないというところを伺いたいと思います。","respondent":"多並都市開発課長","answer":"この中で大崎地域につきましては、広域の活性化拠点ということで、大崎・五反田地区ということで高度化を図り、業務・商業機能と大崎周辺の居住機能と、適切な役割分担の中で連携を図りながら、計画的に進めていく地区ということに位置づけられているところです。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"私が伺ったのは、容積率がなぜ６５０％必要なのかということです。そこを伺ったのですけれども。これまで３００％であったのが一気に倍になってしまうと。このまま現在の３００％であれば、階数も減らせるわけです。日照の確保にもつながってくるということになると思うのですけれども、なぜ容積率６５０％にする必要があるのか、伺いたい。","respondent":"多並都市開発課長","answer":"容積率の規定についての考え方ですけれども、このまちづくりの事業を進めるにあたっては、特にこの市街地再開発事業を進めるにあたって、都市計画についても非常に密接に関わってくるところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"今おっしゃった条件をクリアすれば、６５０％に容積率が緩和されるということですかね。学校の環境よりも再開発を優先していくというこの区の姿勢を改めるべきだということで、意見として言っておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"確認をさせてください。そして、そのように区として指導していくということだったのですが、きちんと日照が確保できるのかというところを確認させていただきたいと思います。このＡ地区、Ｂ地区で、１１５ｍと１５１ｍと約４０ｍ違うではないですか。これは日照の問題を配慮してということなのか、それともまた別の理由があるのかといったことなどを教えていただきたいと思います。","respondent":"多並都市開発課長","answer":"高さの件ですけれども、これにつきましても、今まで進めてきた周囲の再開発事業がありまして、その事業のスカイラインも配慮しながら、また、先ほど容積の話をさせていただきましたが、そういう容積の中で必要な容積を確保するという観点から、１つは。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"日野学園の日照の問題は、やはりなるべく日が入るようにしてほしいと思うので、間隔を空けることによって日が入るのであれば、そのように指導を続けていただきたいと思います。地区計画によってこの１１５ｍと１５１ｍが設定されたということなのですけれども、それより低く条例では定められないものなのかというところを確認させていただきたいのです。いかがでしょうか。","respondent":"長尾建築課長","answer":"その趣旨からしますと、地区計画で定めた内容をそのまま条例の中に位置づけて、実際の計画する高さというのは、その地区計画と条例の中で定めた範囲内で行うというところになりますので、条例の中では、その高さをさらに低くするとかというような判断というのは行っておりません。","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"行っていないということは、できないわけではないということなのですか。それとも、もう絶対にできないものなのか、そこだけ少し確認させてほしいのですけれども。やはりなるべく低いほうがいいなと思っていまして、低くできるものならばしてほしいなと思って、その趣旨で聞いているのですけれども、絶対にできないものなのか、それともできるものなのか、そこの部分だけ確認させてください。","respondent":"長尾建築課長","answer":"実際、例えば高さについて、低く定めるということができるのかというと、手続き的には可能になるかもしれないのですけれども、基本的には地区計画という計画を都市計画決定する過程の中で、地域の声というのを聞きながらその計画を定めておりますので、それを。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問","question":"等価交換について質問したいのです。ただ、感情的な部分から言った場合に、皆さん、財産というものを差し出して開発やまちづくりに協力をしていくわけでありますが、そこのところで、企業理念、企業利益のために、等価交換により既にある自分の持ち分よりも減ってしまうケースばかりがここのところ見受けられます。小山あたりは坪５００万円。そこらあたり、行政としてどういうふうにお考えなのでしょうか。","respondent":"多並都市開発課長","answer":"これについては、この地区だけではなくて全体的に言えることで、確かに非常に難しいところであるので、この権利変換をこれから考えていく中、または今までやっている事業の中でも、やはりそこが。","id":"exchange-011"},{"speaker":"大沢委員","kind":"質問・要望","question":"あくまでも市街地の再開発については、主体は住民の方で、それに力を貸すのは企業であります。ところが、後のところが少し不協和音というか、できてしまった後、「こんなはずではなかった」というような声が多く聞こえますので、こんなはずではなかったような再開発は、いろいろな部分で、そういう声が聞こえてこないような介添え役としての区のメッセージを発信していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"基本的なところからお聞きします。１つは、壁面の位置の制限というのが出ています。これは何のメリットがあるのかなということなのです。この制限をかけることによって、どういう効果が得られるのか。それから、建物の高さの最高限度が規定されておりますけれども、これ、きっと前はなかったのですよね。１１５ｍ、１５１ｍという根拠はどこにあるのかというところを、まず教えてください。","respondent":"長尾建築課長、多並都市開発課長","answer":"そうしますと、道路とか公園のような空地部分が一定程度確保されることになりますので、そこが公益性のある空間ということになるところが効果かと考えております。その設定の根拠としましては、周囲の地区計画の今までの状況を踏まえながら、あとは地区の皆様と話し合いながら設定したというのが、この根拠です。","id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"これ、都市計画審議会のときにも言ったのですけれども、駅との連携というのは、やはりこの再開発をする上では必要なことなので、それは進めてほしいと。五反田駅、それから大崎駅、今でさえ満杯になっているのに、これからどうするのですか。五反田のほうにしてみれば、改札口を何か所か作ってほしいという要望がかねてからある状況ですよね。やはりここまで再開発が広がってくると、それも進めていかないと。","respondent":"多並都市開発課長","answer":"区としましても、やはり区は区民の皆様をお支えする立場として、いろいろなアドバイスをさせていただいたり、ご支援をさせていただきながら、その地域の特性に応じたよりよいまちになるように、一緒に考えていくことが一番重要なのではないかなと。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問・要望","question":"それを誘導できるのは、やはり区の役割の１つかなと思っています。例えば高層の建物ができるという状況下においての環境整備というものも含め、日照についての課題というのは前々からあって、いろいろな話し合いの中で、日野学園のほうも譲歩したという経緯もあるわけだから、それを踏まえての建築を考えていただきたいと思いますが、その辺の説明とかというのは何かされているのでしょうか。","respondent":"多並都市開発課長","answer":"その際、説明会も開きながらやりましたが、あとは学校であったり教育委員会ともよく協議しながら、この考え方については進めてきたところです。今の委員のご指摘の過去の経緯も含めて、これについては教育委員会にはよく伝えさせていただきたいと思います。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問・要望","question":"民民でも相当、日々そういう問題が起きて、民民であれば行政側は立入りできないので、そこはお互いの中でやっていくということになっているのですけれども、ただ、この日野学園のときのことを考えると、やはりそれはきっちりと説明をして、日野学園だってそういう譲歩をして何とか近所の方々と折り合いをつけてきたのだというのは、やはりきちんと知ってほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"１点だけ。今の話でどうしようかと思ったけれども、１点だけ考え方をお伺いしたいと思う。これ、再開発というのはこれからどういうふうにしていくのだといったら、５０年後を見据えようよ。地図を見れば。今、テナントをどうやって入れようかといえば、それなりの規模の大きいところであるならば、多分、上場企業でもメーカー系しか来ないだろうというくらいの話しかないわけではないですか。","respondent":"多並都市開発課長","answer":"かなり長期のレンジについての考え方の整理というのは、品川区まちづくりマスタープランを改定する中で、しっかり議論しながら、将来の大崎の方向性というのは進めていくところでもありますので、そういういろいろな機会を捉えながら、委員の今のご指摘も含めて。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこにいろいろな情報が入ってくるわけではないですか。それは場所にもよると思う。大崎とか、それは分かっている。では、品川駅はどうだったといったら、もともと指定されたところでもお台場があったり八重洲があったりしたけれども、渋谷もああいうふうに変わってきたけれども、では、品川でも手を挙げるところになったし、羽田もあれで本当によかったのかというのがあるわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"３点ほどになります。しっかり中に入っているのですよというところの確認をさせていただきたいと思います。それからもう一つ、Ａ地区の広場の取り扱いについては、公園ではないということはこれで読み取れると思うのですが、逆に、こういう広場を活用して、いわゆる建築物、工作物を作る場合の何か制限とか、その有無について確認をさせていただきたい。","respondent":"多並都市開発課長","answer":"広場につきましても、この中では、公共の中ではなくて、各敷地の中で広場の形にするようにということで、そういう位置づけの指定をしているところなのですけれども、またどこまでの施設が建つかについては、個別のご相談をいただきながら進めていくような内容で。","id":"exchange-019"},{"speaker":"若林委員","kind":"質問・要望","question":"これ以上が逆に建てられないと。そういうところの１,５００m2に対して、掛け算すればいいのですけれども、こういう場ですから、建築面積の最低限度が５００m2。ただ、「公益上必要な建築物はこの限りでない」というところも含めて、いわゆる都市公園法というのでしょうか、そういうところの説明をしっかり行っていただきたい。こういう趣旨で質問しましたので、もう１回お願いいたします。","respondent":"長尾建築課長","answer":"Ａ地区に設けられる広場につきましては、仮にここで建築物を建築する場合には、Ａ地区にかけられている建築制限を守った形で計画することにはなりますけれども、具体的な計画については、この地区計画の制限条例の中ではここまでしか定められておりませんので。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"この条例の高さの最高限度に関しては、やはり生活者ネットワークには、高さを求める声は聞こえてこないです。そして、なるべく低くという声が聞こえてきます。地域の声を聞いて、高さはなるべく低く、今も航空法で結構ぎりぎりの高さの設定となっているので、低くしてもらえるように求めたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"}]},{"id":"topic-02","title":"第５６号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５６号議案、令和２年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"家庭用生ごみ処理機の需要がとても増えているということで、それがなぜ増えたのか、この理由を伺いたいと思います。減便とか路線廃止ということの恐れもあると書いてありますけれども、この間そういったことがあったのかどうかも含めて、ご説明いただければと思います。","respondent":"工藤品川区清掃事務所長、鈴木都市計画課長","answer":"資源回収の業務委託の内容ですが、これまでも資源回収につきましては、いわゆる事業者に業務委託ということで、その回収をお願いしていたものですが、先ほどご説明したとおり、外出自粛等によりまして、回収量が増えているです。私からは、路線バスについてですが、区内には、東京都の都バスも含めますと３事業者が走っているわけですが、その１事業者に確認しましたところ、緊急事態宣言下の４月、５月においては、利用者、乗車の数ですが。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"防災費のほうで、今回、電源確保事業補助金ということで、新たに事業ができると思うのですけれども、それと併せて避難所生活環境改善経費ということで、今回備蓄を買い足すということで、この導入をした理由を伺いたいと思います。避難所のほうのトイレですとかパーテーションの数は、必要な数の備蓄になっているのか、そこのところも伺いたいと思います。","respondent":"中島防災課長、平原防災体制整備担当課長","answer":"品川区といたしましても同様の問題認識のもと、その制度を活用いたしまして、電源に関する資機材を購入する防災区民組織に対して、災害時に備えていただく自助・共助の強化の観点から、計上させていただいたところです。今回、併せまして簡易間仕切り、いわゆるパーテーションをご用意する形を考えておりますけれども、こちらにつきましては、主に風水害を考えているところですが、数といたしましては。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"避難所のほうは、パーテーションのところが風水害に対してということで、今後も台風の上陸などが懸念されるところですので、ぜひこのパーテーションをしっかりと備蓄していただきたいと思います。私は、このコロナの中で距離を確保するという意味でも必要だと思うのですけれども、そこのお考えを伺いたいと思います。","respondent":"平原防災体制整備担当課長","answer":"今回、避難所におきましては、症状のある方とない方を区分けするという考え方をまず大前提で置いておりますので、例えば症状のある方のところにこういったところを活用するとか、いろいろな考え方があるかと思いますけれども。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"症状のある方、ない方で分けるというところで検討していきたいという話もありましたけれども、症状がある方だけでなくて、症状がない方も、避難所でしっかりと距離を取ってもらうと。それから、毛布１枚で体育館に座り込んでいるという状況では、環境も悪過ぎますので、そういったプライベート空間を確保できるというふうに、ぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"田中委員","kind":"意見","question":"今、お話がありました避難所生活環境改善経費のところですけれども、今、そのパーテーションの利用のところで、避難生活が長くなったときを想定して、といったお話などがあったのですけれども、避難所での性暴力被害が残念ながら多発してしまっているので、それらを防止するためにも、このパーテーションであったり生活環境の改善はしていくべきだと考えています。","respondent":"平原防災体制整備担当課長","answer":"それ以外の「等」というところで資料上まとめさせていただきましたものにつきましてご説明しますと、まず１つ目には、顔認証付きの体温測定装置というものを考えしています。今、学校の玄関に、大型スーパーなどの入り口に置いているような温度計がついています。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問・要望","question":"ありがとうございました。そして、路線バス事業者に対する感染拡大防止対策費助成についてです。資料のほうで、対象が「区内に停留所がある路線バス事業者」ということで、さっきご説明の中でも、対象は３事業者だということだったのですけれども、区外につながる路線の場合の、関係区や県との調整というのは、この場合どうなるのかといったところをお知らせいただければと思うのですが。","respondent":"鈴木都市計画課長","answer":"これから補正予算をご審査いただいて可決いただいた暁には、実施の段階で、この要綱を作成し補助を行っていくわけですが、当然ながら、仮にほかの区と重複するような場合は、そこは重複して申請、あるいはお支払いすることがないように、要綱上もしっかり整理をして。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問","question":"ごめんなさい。少し分からなかったなというのと、あと、区だけではなく県にもまたがる路線がありますよね。そういった場合はどうなるのだろうということとかも、少しお知らせいただければ。もう１回聞いてもいいですか。","respondent":"鈴木都市計画課長","answer":"先ほど説明が少し不足しておりましたが、物によっては都内だけではなくて、神奈川県等に走るバスも当然あります。","id":"exchange-028"},{"speaker":"西本委員","kind":"確認","question":"もともとが。ほかの県でやっていなければ、東京都で申請をするという形になるのでしょうが、例えば神奈川県とかと照合するということですか。申請の時期も違うだろうし、自治体によっても支給の仕方が変わってくると思うのですけれども、それもすべて整合性が取れるように確認をとって支給をするということなのでしょうか。それを確認させてください。","respondent":"鈴木都市計画課長","answer":"今回の助成につきましては、基本的なベースとなるものが、令和２年度の国のほうの第２次補正予算、これ、歳入のほうでは新型コロナウイルス感染症対応地方創生臨時交付金というところで、この枠組みの中で区のほうも行うと。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"申請する側にしてみれば、非常に面倒くさい。ただ、周知していただかないと、二重払いというのはよくないことだと思うので、広く適用していただきたいと思いますから、これが結果的にどうなるのかというところは、報告をいただきたいと考えていますけれども。そうした場合、もう支払いも終わってしまっているもの、それは後で申請をするという形が可能なのかどうかというのはいかがですか。","respondent":"鈴木都市計画課長","answer":"先ほど区の枠組みの中で行うというご説明をさせていただきましたが、区の制度の中では遡り期間を定めまして、一定これ以降であれば、５月の二十何日だったかと思うのですけれども、それ以降行ったものについては対象とするというところで国のほうは打ち出していますので。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"この５月２０日ぐらいですかね、そこで区切るのではなくて、やはりコロナの対策という形で、早ければ早いほど前向きに考えているということであるし、貢献していることになると思うのです。ぜひそれは改善、話し合いの相談をする余地を。それと、２点ほどあります。もう一つは、防災関係ですけれども、電源の確保、これは品川区で前からやっていなかったでしょうか。やっていなかったですかね。","respondent":"工藤品川区清掃事務所長、中島防災課長、平原防災体制整備担当課長","answer":"今後のＰＲというところでは、積極的に私どものほうでも、すぐさま広報活動という部分を考えてございまして、ホームページで。私からは、電源の整備のこれまでの実施と、今回の補助金と避難所の電源確保との違いについて答えします。パーテーションの高さも、製品によっては１２０ｃｍから１８０ｃｍなどと様々なものがありますけれども、そういったところも。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"すみません、１点だけ。バスの件なのだけれども、私、よく分かっていなくて、少し教えてもらいたいのだけれども。１０分の１０。もともと２分の１は出ているのだから。ここは、今のお話をよく伺うと、品川区が言って、品川区を通っているところがいろいろあるからと言うのだけれども、この辺のところがよく分からなかった。国には、だから２分の１だと全部出ているのかとか、そこら辺を少し教えてください。","respondent":"鈴木都市計画課長","answer":"区内のバス事業者の中から、この２次補正の枠組みの中で、「何か区としてもご支援いただけないでしょうか」というお話も、要望としていただいているところがありまして、一方では区としても、今ご説明した、やはり地域の足を守っていかなければいけないというところから。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"質問","question":"基本的には、国が２分の１出します、東京都は出しません、区が４分の１出します、事業者が４分の１出す、という理解でいいのかな。品川区が単独でもやるというのはいいことなのだけれども、それこそ特別区長会とかで、「これくらいの話は面的に特別区でやろうぜ」というぐらいの、そのほうがよかったような気がするのだけれども、どうですか。","respondent":"鈴木都市計画課長","answer":"より広域的にといいますか、一体となって、より地域の足を確保するために特別区長会等への要望、あるいは特別区全体で進めていこうというお話ですが、この検討をするにあたっては、周辺区の状況について、先ほどご説明しましたように。","id":"exchange-033"},{"speaker":"石田（秀）委員","kind":"確認","question":"その中で品川区がそういう対応をしてくださったのは、非常によかったと思います。１つ確認なのですが、都バスは東京都が全部やるという理解でいいのでしょうか。それだけ最後、確認させてください。","respondent":"鈴木都市計画課長","answer":"都バスについては、東京都が自ら行うという理解でおります。","id":"exchange-034"},{"speaker":"若林委員","kind":"質問・要望","question":"コロナ禍で処理機の購入が増えてきて、この３００万円余の積算根拠を示していただくとともに、分かる範囲で、今まで購入していなかった方の中でどういう層の方が増えているのか、もし傾向が分かれば、併せてお知らせいただきたいと思います。本来は、都市計画課以外の所管からもそれぞれ資料が出るべきかなと思いますけれども、口頭でお聞きしたいと思います。","respondent":"工藤品川区清掃事務所長、中島防災課長、平原防災体制整備担当課長","answer":"その理由といたしましては、ごみというのが、１人当たり大体１日６００ｇくらい出ますので、家族が多いとその分多く出ているというところで。私からは、電源に関する補助金の内訳について説明をします。今回、防災区民組織に２分の１の補助金を行う制度です。続きまして、パーテーション、簡易間仕切りですけれども、こちらにつきましては、昨年の台風第１９号の際の品川区の最大避難者数が５８４名でありまして。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほどもありましたけれども、やはり資料ですね。路線バスのところでは出ておりましたけれども、ほかのごみのところですとか、防災費のところで、やはりこの補正予算の冊子になっている資料だけでは分からないところも多々ありますので、ぜひ今後、資料を付けていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"ほかの委員からもあったのですが、やはり資料をもっと充実させていただきたいと思います。賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"令和２年陳情第４３号、「品川区自転車ネットワーク計画を含む自転車活用推進計画」（仮称）を策定することを求める陳情","agenda":"令和２年陳情第４３号、「品川区自転車ネットワーク計画を含む自転車活用推進計画」（仮称）を策定することを求める陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この陳情は、東京公害患者と家族の会品川支部から出され、主に自動車からの排気ガスによる公害をなくすために自転車活用を進めてほしいということで、品川区にも自転車活用推進計画の策定を求めているものです。既に２３区でも、都内でも、多くの区市が策定をしています。この中で、品川区が自転車の活用をしていく意義をどう考えていらっしゃるのか、伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区としましては、この自転車の活用を今後区としてどう考えていくかというところは、昨年の本会議の中でもご答弁差し上げましたが、今後についてしっかり検討していきたいです。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"この陳情では、この間ずっと計画を策定していく方針だということで言ってきた中で、今まだできていないというところだと思うのですが、なぜできないのか、策定するという方針をもっているにもかかわらず策定されないのか、そこの理由を伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今現在２０２０年、今まさに目標年度になってありますので、東京都と国がその内容の大幅な改定の作業を今行ってあります。区としましては、この大幅な改定の両計画の中身を見て、しっかり踏まえながら検討を進めていきたいというところで、今考えているところです。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問","question":"これ、広域的なネットワークをつくっていく、他自治体とのつながりということもあるので、都の計画とかというのは、確かにその中身を勘案してつくっていくということは必要だと思います。そうすると、東京都と、あと国の計画もですけれども、その改定というのはいつまでにできて、それができたら品川区も早期に策定に取りかかるということでよいのか、伺います。","respondent":"鈴木都市計画課長","answer":"これは予算的な検討を今まさに行っていまして、この予算はこれから議会のほうでもご審議いただくことになりますが、所管としては来年度以降、その出された両計画をしっかり見据えながら、検討・策定を進めていきたいとは考えてあります。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"来年度以降つくっていく、着手していくということで理解をさせていただきました。改めてというか、自転車の利用が大気汚染の改善にどのように寄与していると区のほうで考えていらっしゃるか、そこを最後に伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"区内で自動車等をお使いの方が、自動車を使わずに、買い物、あるいは通勤等で自転車をお使いになるということは、やはり低炭素の観点からも環境に優しいというふうに、区としては受け止めているものです。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"低炭素の点で環境に優しいというお話でしたが、当然、車が走れば排気ガスからいろいろなものが出てくるということになりますので、この大気汚染の問題にも寄与していくと思います。そういったところで、やはり環境面を改善していくためにも、ぜひ自転車ネットワークを含めた自転車活用推進計画を迅速に策定していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"今、国と都が示している計画について区としてどのように受け止めているか、区としてどういう推進計画をつくっていくのか、どのような検討をしているのかというところを確認させていただきたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"田中委員","kind":"質問","question":"先ほどからあります、感染症の影響でこの自転車の利用というのも増えていますので、なおさら必要だと思います。そういったことが、今、品川区は本当に自転車も増えていますので、やはり方向性はきちんと位置づけるべきだと思いますし、この計画も、国、都の改定を待たずに進めていっていいのではないかなと思うのですけれども、その辺についてお伺いできればと思います。","respondent":"鈴木都市計画課長","answer":"自転車の利用促進をどの分野において区民に働きかけ、周知していくのか、区として考えていくかというところは、やはり様々な切り口、視点がありますので、それを一様にということではなくて、繰り返しになりますが、どこに力を入れてどういう形で取り組んでいくかというところは。","id":"exchange-044"},{"speaker":"田中委員","kind":"質問","question":"この計画は、区としてはつくっていく姿勢があるということは分かるので、よかったと思うのです。区としての促進に向けてここに重点を置くというのが、もしかしたら住民にとっては、その置く視点が少しずれているかもしれないので、そういったこととかを踏まえて、いろいろな方が集まって意見を言えるような場を設けてほしいと思います。もし答弁があれば、お願いします。","respondent":"鈴木都市計画課長","answer":"どういう形で策定検討を進めていくかというところは、これからというところはありますが、やはり、例えばアンケートですとか、検討会の立ち上げですとか、当然ながら、区民の方の自転車に対する考え方という意見、声は、しっかりと計画の中に反映できるように。","id":"exchange-045"},{"speaker":"西本委員","kind":"質問","question":"国と都の動きを見てというご答弁だったのですけれども、自治体にもよるというご答弁もあるわけですね。ある意味で品川区ももうかなり進んでいるのではないのですか。それをまとめていくというのは、作業的にはすぐにできるのではないのでしょうかと考えていますが、そのお考えですよね。その進め方、それから、もう既にやっているところはありませんかというところについて、教えてください。","respondent":"鈴木都市計画課長、川口交通安全担当課長","answer":"ご指摘のとおり自転車対策等々について、全く区が取り組んでいないということは当然ないわけでございまして、例えばでお話ししますと、シェアサイクルにつきましても既に実施しているところがございまして。参考ですけれども、東京都がこの条例を施行する前に、都内１,０００人にウェブアンケートを実施した際には、４６.６％が何らかの自転車の保険に加入しているという数字が出ておりますので、今後、区といたしましても。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問・要望","question":"もう既にいろいろ取組をされているというのは重々分かっているので、やはりそれを軸としてきっちりと位置づけて、区民の方々に周知して、計画的に行っていただきたい。ですので、陳情者の真意はよく分かりません。いろいろな考えがあってのことなのだろうと思いますが、純粋にこの陳情の内容から建設委員会にかけられたということの経緯から、判断したいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。結論としては不採択でお願いをします。だけれども、品川区という環境を考えるのであれば、先ほども少しお話があったけれども、自転車レーンであるとか、いろいろ個々の実態の中で計画をどういうふうに考えていくのだというのは、非常に個々にわたって様々な面があると思います。そういう状況ですので、この陳情については不採択ということであります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"大沢委員","kind":"質問","question":"本日、結論を出すで、不採択でお願いします。理由を言えば、今の石田秀男委員と重なりますけれども、国、都の上位の計画を見据えながら、より品川区に合ったルールをつくるために、それとともに、来年度に向けて予算立てをしているという、この件に関してはもう積極的に動き出しているところでありますので、採択をする必要はない。よって不採択ということで、今、お話しさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"若林委員","kind":"質問・要望","question":"私ども公明党としても、この自転車の利活用については、もう私が議員になる前の先輩から、恐らくずっと区議会の中で、これはもう東京都、国、全体で積極的に取り組んでまいりまして、その中で品川区については、いわゆる駐輪場の条例があって、平成３０年、令和になる前の第４回定例会で、会派としても改めてこの課題について質問させていただいて、それまでは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"のだて委員","kind":"質問・要望","question":"もちろん、この自転車活用を進めて放置自転車とかが増えたら困るので、駐輪場の増設とか、あと交通ルールの周知などもぜひやっていただきたいと思いますし、東京都や国の計画を注視しながらということですけれども、この計画策定にこだわらず、とらわれず、できるところは区としてぜひ進めていただきたいと思います。ということで、採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"田中委員","kind":"質問・要望","question":"これはとても残念だと思うので、品川区としても今、計画を検討しているというのであれば、やはりこの陳情にあるように、なるべくというか、早めに進めていただきたい、実行性をもっていただきたいと思います。その際には、先ほども申し上げましたが、いろいろな市民が関わって、いろいろな意見を盛り込んだ計画になるといいなということを、要望したいと思います。採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。採択でお願いします。それが、国、都とももう作業が始まっているという段階ですから、恐らくは品川区も早々に始まっていかなければいけないことだろう。なぜ逃げ回るのか、私はよく分かりません。スピード感をもって、まちづくりという観点でも、健康、様々な観点でも、これは非常に大切な位置づけだと思いますので、採択ということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"のだて委員","kind":"質問・要望","question":"この陳情は、対象地域の住民から提出されまして、住民の意思が確認されないまま、推進側が一方的に進めるこの再開発事業をやめてほしい、そのためにまちづくり勉強会の中止を求めているものです。一方的に説明をして、質問や疑問にも答えてくれないということで陳情にも書かれております。なぜこの住民に知らせずにまちづくり勉強会が発足されたのか。勉強会発足の経緯を伺います。","respondent":"多並都市開発課長","answer":"今までの勉強会を見させていただいても、まちづくりの再開発前提というよりは、単独の建て替えであったり、共同の建て替えであったり、いろいろなまちづくりの手法ありますよということで、そういうのを１回目から２回目と順を追って。","id":"exchange-054"},{"speaker":"のだて委員","kind":"質問","question":"こうした進め方含め、以前にもこの地域ではそういった再開発の動きがありました。そうした中で、質問に答えられないというのはなぜなのか。そこがやはり地権者の方が、住民の方が質問しているところで、誠実に答えていくということがまずまちづくりを考えていくという意味では必要だと思いますけれども、区のお考えを伺いたいと思います。","respondent":"多並都市開発課長","answer":"ただ、区としては、そうはいっても、幅広く勉強していただきながら、皆さんが今後どうまちを、将来を進めていくかというところで、一緒に考えていくというのが重要なところですので、質疑云々というよりは。","id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"多くの方に、近隣住民の方にも影響がありますので、そういったところで合意をしていくことが必要ですけれども、その中で質問にまともに答えてもらえないというところで、答えられない理由があるのかなと思ってしまうわけです。双方の意見を聞いて、話し合いの場を作るというのが、少なくとも区のやるべきことなのではないかなと思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"再開発というところの大きな意味と小さな意味があるのですけれども、市街地再開発事業としての事業手法を活用していくということですと、かなり限定した事業となってきますが、やはりその地区を再開発、いわゆる新しくまちを再生したり。","id":"exchange-056"},{"speaker":"のだて委員","kind":"質問・要望","question":"区としても支援していくということなのですが、今心配する会の方々が話し合いをしようと求めても、返事もないという中で、話し合っていく土壌ができていないわけです。そこを区が取り持って話し合いをしていくということが必要なのではないかというふうに思うのですけれども、区としてどのように関わっていこうと考えているのか、伺いたいと思います。","respondent":"多並都市開発課長","answer":"そこの会の中の皆さんの考え方には、同じ思いだったり、その会の主催の趣旨があるかと思いますので、そういうところでお話し合いいただきながら、いろいろなご意見を踏まえてというところもあるので、お集まりの方々のお話をよくお聞きしながら。","id":"exchange-057"},{"speaker":"のだて委員","kind":"質問","question":"すみません。意図が伝わっていなかったみたいです。心配する会の皆さんで話し合いができないということではなくて、心配する会の方々がまちづくり勉強会に話し合いをしよう、住民たちで話し合おうということで呼びかけても応じてもらえないということなのです。私は間を取り持って話し合いができるようにしていくということが必要だと思うのですけれども、そこのお考えを伺いたいと思います。","respondent":"多並都市開発課長","answer":"繰り返しのご答弁になってしまうのですけれども、その会ごとの話し合いの熟度の段階であったり、進んでいる状況などを踏まえながら、最終的には皆さんが一緒にお話し合いいただくことが重要かと思いますので、各会だったり皆さんのご意見をお伺いしながら。","id":"exchange-058"},{"speaker":"のだて委員","kind":"質問","question":"つまりどういうことかがよく分からないのですけれども、区としては見守っていくということなのですか。今熟度の問題などもおっしゃっていましたけれども、この話し合いがもたれなければ、このまま決裂したままになってしまうので、区がここでまちづくりを進めていこうと思えば、話し合いを取り持っていく必要があるのではないかというふうに思うのですけれども、改めて伺いたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問","question":"分かったような分からないような感じなのですが、まちづくりを進めていくということであれば、住民の合意が重要ですから、それは話し合いをしっかりとしていけるように区としても支援をしていくべきなのではないかと、私は思います。そういった中で、このまちづくり勉強会というのは、都市計画手続きの一部ではないのかというふうに思ってしまうわけですが、いかがでしょうか。","respondent":"多並都市開発課長","answer":"したがいまして、市街地再開発事業に直結するというわけではないというふうに区としては認識しております。","id":"exchange-060"},{"speaker":"のだて委員","kind":"意見","question":"住民、特に心配する会の方々は再開発が進められていると心配をしておりますので、そういったことがないように、先ほども話し合いをするべきだということを言いましたけれども、話し合いをしていくべきではないかと思います。こうしたことはやめるべきだと思いますし、住民が追い出されるということは、こうした再開発は人権侵害ではないかと私も思いますけれども、いかがでしょう。","respondent":"多並都市開発課長","answer":"区としては、いろいろな事業をやるにしても、必ず法令遵守の形で進められるよう、地元の方との話し合いの中でも必ず事業に移行する際は、そこの点はよく注意しながら指導・助言というのはそういう意味でもさせていただきたいと思っているところです。","id":"exchange-061"},{"speaker":"のだて委員","kind":"質問","question":"正当な権利を侵してはならないということで、ここに住み続けてきた方々が生活を奪われるというのは大きな侵害だと思うのです。ですので、それが起きないよう指導していくということで、改めてお考えを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"田中委員","kind":"質問","question":"陳情の中の項目２にある「再開発事業は」から始まり、「疑問・質問等に、事業者（東急）は全く回答していない」の部分なのですけれども、もし区が把握していればで結構なのですが、この回答というのは、先ほどご答弁があったとおり勉強会での質疑でのことを指しているのか。そういったことを、もし区が把握をしていればお知らせください。","respondent":"多並都市開発課長","answer":"区のほうで把握していることでお話ししますと、勉強会の中で質疑をされて、受け答えがあるのですけれども、その中で繰り返しになりましたり、「再開発前提で進めているのではないか」というような質問があったときには。","id":"exchange-063"},{"speaker":"田中委員","kind":"意見","question":"この陳情項目の中の１から４に関してはとても分かるのですけれども、５の部分がとても気になってしまっています。「行政の立場から指導」、「二度と再開しないよう」にとなってしまうと、ほかの市民活動への影響も出てきてしまうため、この陳情では採択というのは、生活者ネットワークとしてはできないのですけれども、陳情者の怒りなどはとても分かるので、ぜひ区として調整をしていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ地域の方がご理解して、まず自分たちのまちをどうしていくかということの議論をしていただきたいなというふうに思っております。スタートが。３０年前ですか、いろいろ議論がなされていて、立ち消えになった。結局今になってまた吹き返してきた。なので、質問というのはないのですけれども、意見として言わせていただきたいなと思っているのは、再開発をするときには、スタートというのがいかに大切か。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由を述べます。それで、その中で、再開発を心配する会の方々も２回ほど開催をされてきたということでありまして、これはまさに今、民民の話で勉強会をしているという状況でありまして、ほかの再開発を考えるところでも勉強会を始めて１０年くらいそのままでやっているというところだってあるわけで、今そういうふうにして、地域の中でどういう形で話をしていくか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"若林委員","kind":"意見","question":"本日結論を出す、でお願いします。自主的にこのまちづくり勉強会を立ち上げられている方に対して、自主的にいわゆる心配をする方々から、行政を介してこういう勉強をやめなさいというところは、今の民民というところも含めて、私どもとしては採択しかねるということで、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"のだて委員","kind":"質問・要望","question":"まちづくりは住民の合意で進められるべきものでして、一方的に再開発を進める勉強会を行うというのはやめるべきだと思います。特に今回東急が実質主催をする形になっていまして、そうではなくて、住民による話し合いをしていきたいという思いで勉強会の中止を求めているものだと考えますので、結論を出すということで、採択を主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"田中委員","kind":"質問・要望","question":"先ほども申し述べましたけれども、項目の１から４の趣旨についてはよく分かります。この市民主体となるまちづくりとなるように品川区としては変えていかなければならないだろうというのをとても感じていますので、そうしていってほしいなというのは強く要望したいのと、また、この項目２にあるこの請願者の方が回答がされていないというところについても……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"},{"speaker":"西本委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。ですので、共通した思いの中で、ではどうするのだという話し合いが、まさに今されようとしている中で、今勉強会をやめていただきたいというのは逆行しているなと非常に残念に思っております。前向きに、そしていいまちづくりにつながるように住民たちが、ハードルは高いでしょうけれども、様々試行錯誤しながらやっていただきたいというふうに願っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-070"}]},{"id":"topic-04","title":"の(2)広町地区におけるまちづくりの検討状況","agenda":"の(2)広町地区におけるまちづくりの検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"報告について伺いたいと思います。来年度の都市計画手続き開始を目指して検討を進めるということですけれども、来年度のいつ頃なのか。都市計画手続きというのは何を指しているのか、伺います。","respondent":"多並都市開発課長","answer":"来年度の都市計画手続きの予定ですが、時期自体は未定です。ただ、来年度中の都市計画ということで、東京都ともよく協議しながら、時期等もこれから決まりましたら、お知らせしたいと思っているところです。都市計画の内容ですが、まずは地区計画を定めたいと考えています。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問","question":"都市計画手続きの地区計画をやっていきたいということで、その中には土地の再編のことですとか、あと、新たに道路を造ることになりますから、道路の配置とかそういう計画を載せてということが含まれるのか、伺います。","respondent":"多並都市開発課長","answer":"いわゆる整理後の姿をもって地区計画というのを定め、合わせて、要するに整合性を取りながら行っていくというのが今の考え。その中では道路であったり、各敷地がこのような形で示されるということで出てくるという予定です。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"歩行者ネットワークの形成とありますが、図の中にも青い点線で歩行者ネットワークということで書いてありますが、これは、大井町駅に既にあるペデストリアンデッキのような人工地盤を造っていくということなのか、どういうイメージなのかというところを伺いたいのと、あとは、交通結節機能の強化、これはつまり今回示された交通広場のことを指しているのでしょうかということ。もう少し具体的に伺えれば。","respondent":"多並都市開発課長","answer":"それ以外についても、これから様々な施設計画等を立てる際には、新庁舎の機能検討の中でもいろいろな委員の方からご意見をいただいたところもありますけれども、庁舎の中でやるべきことなのか、またはこのまちづくりの中で進めていくべきものなのかというのは。","id":"exchange-073"},{"speaker":"のだて委員","kind":"質問","question":"逃げ込む場所ということで防災の拠点というか、防災計画の中でも重要な位置を占めてくると思うのですけれども、ＪＲと何か土地を売らないということとか協定をやっていくというお考えなのか、そこを伺いたいと思います。先ほど、鉄道だけではなくほかのところもということでありましたけれども、妥当性というのですか、必要性がよく分からなかったのですが、どういうことなのか。すみません。","respondent":"多並都市開発課長","answer":"この広場につきましては、今の大井町駅の東・西で駅前広場があるところなのですけれども、北側に新しく開発が進むところを考えますと、今後の交通の結節機能の連携を図ることを考えると、広場を結節機能の中心として。","id":"exchange-074"},{"speaker":"のだて委員","kind":"質問","question":"今交通広場のところは、ＪＲの敷地の中でやっていくと。だけれども、立体的な区の管理をできないかと。立体的な管理というのはよく分からなかったのですが。そうすると、この交通広場もそうですし、新しく道路ができるので、どこが整備することになるのか。区が整備すれば区が管理していくということになるのでしょうか。そこの点を伺いたいと思います。","respondent":"多並都市開発課長","answer":"これも土地区画整理事業の中で造っていくことになるのですけれども、先ほども言いました換地という処分の中に、そういう形で整理できないかということで、そういうことを基本に今検討を進めているということで、それでここに出させていただいたところであります。","id":"exchange-075"},{"speaker":"のだて委員","kind":"質問","question":"事業として道路を造って、最終的には区が管理をしていくということでしたけれども、新たに道路を造って、道路づけをよくして、ＪＲの開発を進めるために道路整備を行うということになってしまうのではないかなというふうに思うのですけれども、いかがでしょうか。","respondent":"多並都市開発課長","answer":"土地区画整理事業は、今の土地の再編をして、より整理をしていくという事業の手法ですので、そちらを活用して、土地を再編していくというまず基本的な考え方です。","id":"exchange-076"},{"speaker":"のだて委員","kind":"質問","question":"陳情について伺いたいと思います。これは完全に戸越公園駅周辺のまちづくりの問題をパブリックコメントをやったという中で言いますと、今回の大井町駅周辺地域のまちづくり方針もパブリックコメントをやっていくべきなのではないかなというふうに思うのですが、なぜやらなかったのかというところと、戸越公園のまちづくりビジョンとの考え方の違い、今回との違いというのは何か、伺いたいです。","respondent":"多並都市開発課長","answer":"それで、区としましては、(2)でお話ししたところが、まちづくりに関しては、品川区まちづくりマスタープランというのが大本の各分野、まちづくりの分野における基本方針という形で示させていただいておりまして、これに基づいて。","id":"exchange-077"},{"speaker":"のだて委員","kind":"質問","question":"ですから、まちづくりの問題でも基本方針でも、この間パブリックコメントをやってきているわけですよね。多くの意見を反映させていくということが必要だと思いますので、パブリックコメントを実施していくということが必要なのではないかと思うのですが、そうすると、今までの考え方とは変わったということなのか、伺いたい。","respondent":"多並都市開発課長","answer":"考え方自体は先ほどもご説明しましたけれども、今までと同じ形で行っているという認識です。先ほどご説明しましたが、まちづくりの進め方ということで地域等主体でやっていくという考えがあるので、先ほどもお話しさせていただいたところです。","id":"exchange-078"},{"speaker":"のだて委員","kind":"質問","question":"いろいろな都市計画の手続きの中で聞いていきたいということですけれども、どんどん固まっていけば変えづらくなってきますので、より早めに意見を聞いていくということが必要だと思います。今回コロナ禍のもとで、広く区政に参加してもらうという意味でも実施すべきだというふうに考えておりますけれども、コロナ禍のもとということについてお考えを伺います。","respondent":"多並都市開発課長","answer":"これ以外についても、説明会後に資料を公開させていただいて、電話の問合せ等にも丁寧に説明させていただこうと思っていますので、今までもそうでしたけれども、説明会に来られた方のご意見だけではなくて、それ以降もいただいたご意見を踏まえながら。","id":"exchange-079"},{"speaker":"のだて委員","kind":"質問","question":"最後に伺いたいのですけれども、説明会終了後に資料を公開して意見を聞くということでしたので、それは取りまとめて、ご意見がありましたということで公開されるということでよいのか、伺いたい。","respondent":"多並都市開発課長","answer":"それ以外については、いただいて、計画を進める際に参考にするというのが基本的な考えですので、あとはタイミングをもってできる部分があれば、可能な限りは対応し、今回コロナウイルス感染症拡大の観点もありますから。","id":"exchange-080"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ広く意見を聞くという意味でも、パブリックコメントを実施していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-081"},{"speaker":"田中委員","kind":"確認","question":"陳情についてお話を伺えればと思います。そういった中で、パブリックコメントはすごく重要だと思うのですけれども、それでも区の姿勢というのは変わらないのかというところを確認したいと思います。","respondent":"多並都市開発課長","answer":"ただ、説明会の開き方についてというお話かと思いますけれども、今回は会場を感染に配慮した形でするとともに、あとは説明会の資料。","id":"exchange-082"},{"speaker":"田中委員","kind":"確認","question":"要綱を確認したときに、第３条、「区民意見公募手続の対象となる計画等の策定は、次に掲げるものとする」の(1)で、「区の総合的な施策に関する計画等の策定および重要な改定」とあるのですが、この大井町駅周辺地域まちづくり方針に関しては、広町地区におけるまちづくりの検討状況についての資料の図で示されているように、庁舎のことは必ず絡んでくる話ではないでしょうか。","respondent":"多並都市開発課長","answer":"具体的な内容につきましては、一つひとつの事象によって細かいやり方が違ったりしますが、標準的なフォーマットのやり方というのがありますから、また機会を捉えながら、ご説明しながら進めていきたいと思っているところです。","id":"exchange-083"},{"speaker":"田中委員","kind":"質問・要望","question":"そこに関して、大井町には区庁舎、行政機能もあるので、ぜひ声を聞いてほしいといったことをこの陳情は求めているわけで、行政の方たちにとっての手順が区民に伝わっていないので、分かりやすく手順というのを公表してほしいというのが１点。私、傍聴していたのですけれども、たくさん意見が出ていた中で、機能検討の中では、まちづくり方針に示されている……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-084"},{"speaker":"田中委員","kind":"質問","question":"候補地というのは確定しているのかどうかという話で、「確定はしています」というご答弁だったのですが、何が言いたいかというと、区の中で大体もうイメージとして、こういったものをここの位置にとか、歩行者ネットワークの形成はデッキを用意しているとか、そういうイメージといいますか、大体こういう案を出しているのであれば、それを示してほしいという委員からのご意見が機能検討委員会ではありました。","respondent":"多並都市開発課長","answer":"第１回目のときからついています。それを前提に機能検討委員会のときにも説明させていただいて、ただ、今お話があったように、もう少し具体的な資料をいただけないかというご意見も第２回のときにはあったかと思います。","id":"exchange-085"},{"speaker":"田中委員","kind":"意見","question":"すみません。言葉足らずで。機能検討委員会の１回目のときに、大体の候補地というのが出ていたというお話だったのですが、２回目のときには、そこがもう確定なのかどうかというやり取りがあったと思うのです。なので、今もＪＲとのやり取りもあるので示せないというお話があったのですけれども、でも、今こうやってまちづくりとして示されているのであれば、ある程度出してほしいのですが。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"この陳情、だんだんいろいろな委員会の話が出てきて、分からなくなってしまって、答弁する方も、聞く方も、私、一生懸命聞いていたのですが、何を言っているのか分からなくなってしまった。僕らも一生懸命聞いているのだから、もう少し分かりやすい言葉で、もう少し分かりやすい説明をしていただきたいと思うのです。その中で、陳情に戻ります。区から資料が出されているのは、これは何でしたか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-087"},{"speaker":"大沢委員","kind":"意見","question":"広町地区と出されています。その中で、あくまでも、今、話になっている陳情の主体となっているところというのは、この大井町駅周辺の一開発地域にしか過ぎないわけですよね。そうなると、ほかの再開発の場所と同じなので、パブリックコメントは実施する必要性は私はないと思うのですが、そこのところをどういうふうにお考えになりますか。","respondent":"多並都市開発課長","answer":"今の委員のご指摘のところが我々の趣旨でありまして、この各地域のまちづくりの情報ということですので、区としてはパブリックコメントの対象にはならないということで判断しているものです。","id":"exchange-088"},{"speaker":"石田（秀）委員","kind":"質問","question":"本日、結論を出す。不採択でお願いをします。理由としては、先ほど大沢委員が質問し、行政が答弁したとおりで、私もそのとおりで結構だと考えていますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"若林委員","kind":"質問・要望","question":"（陳情の）最終段落の、「まちづくりをテーマとするものですが、本地域には」「区役所が含まれています」というところで、私の理解というか全体的に、まちづくりはまちづくりなのだけれども、主に区役所、特に今検討が進められている機能検討、こちらのほうにパブリックコメントを実施される際にはぜひお寄せいただきたいなという感想をもっていますので、まちづくり方針についてのこの陳情については。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-090"},{"speaker":"のだて委員","kind":"意見","question":"先ほど来、１つのところを指してということですが、区役所もあるし、広町地区の問題もありますし、大井町の広範囲の方針だと私は思っております。やはりパブリックコメントを実施していく、多くの意見を反映させていくということが必要だと私も考えます。ぜひ住民参加を広げていくためにも実施すべきと考えますので、本日結論を出すということで、採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-091"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張します。素案の中の１１ページで、「区庁舎再編と連携し区の中心核としてふさわしい複合拠点を形成する」など、庁舎のことにも触れており、この大井町全体のまちづくり方針に関してのことなので、区民としてはパブリックコメントを実施したいという思いはとてもよく分かります。ですので、ぜひ実施をしてほしいという要望も併せてしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"本日、結論を出すで、不採択でお願いします。この大井町駅周辺地域まちづくりということなので、この文面からすると、大井町駅周辺なのだろうなと。今回の陳情に関しましては、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"}]},{"id":"topic-05","title":"の(1)コミュニティバス導入に向けた検討状況","agenda":"の(1)コミュニティバス導入に向けた検討状況","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"陳情について伺いたいと思います。この陳情は、小山台地域住民の方から出されたもので、この小山台地域からも利用しやすいコミュニティバスにしてほしいというものです。この陳情代表者の方からお話も伺いました。行く場合は、武蔵小山駅まで徒歩１０分かかって、電車に乗って大岡山駅で乗り換えて下神明駅。誰が参加できるのか。形式というのですか、そこを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"ワークショップの実施方法等についてですが、これまで、昨年度検討を進めてまいりました候補ルート案３案について、より具体的なご意見をいただくということでワークショップを実施したいと考えています。","id":"exchange-094"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうすることで幅広い意見が出されるというふうに思うのですけれども、公募区民の導入について検討をしていただきたいと思うのですが、いかがでしょうか。荏原文化センターのほうも通ってほしいということでありましたので、ぜひ検討していただきたいと思うのですけれども、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"ただ、区民の声につきましては、これまでも昨年度アンケートを区内３,０００世帯無作為抽出で行ってありますし、昨年度、検討会を３回行いましたが、その都度、それぞれの地域センター管内を回って、地域に対しても説明をさせていただき、ご意見もいただいてまいりました。","id":"exchange-095"},{"speaker":"のだて委員","kind":"質問・要望","question":"けれども、ここでも声を紹介させていただきましたので、ぜひ検討の中に入れていただきたいと思います。前提として、（陳情の主旨の）(1)、(2)について、区のお考えをお聞きしたいと思うのですが、どちらも便利なコミュニティバスにしてほしいということで述べられているということだと思うのですけれども、区のお考えを伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"そうしたことをしっかり整理する上でも、高齢の方がいる地域、あるいは、子育て世帯の方が多い地域、高低差、あるいはバス停から遠い、近い等々１１項目で、そこは定量的な指標をもって客観的にしっかりと検討をこれまでも進めてまいりました。","id":"exchange-096"},{"speaker":"のだて委員","kind":"質問・要望","question":"客観的に進めていきたいということですけれども、ぜひ区民の意見を聞いて、いろいろ反映できるように進めていっていただきたいと思います。は報告について伺いたいと思うのですけれども、１回目の地域公共交通会議で、バス協会の方だったと思うのですが、コミュニティバスを導入するときにシルバーパスを使えないという話をされていたのですけれども、本当に使えないのかというところで伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"基本的には、１００円の料金等のコミュニティバスについてはシルバーパスは使えないというところは事前に伺っていますし、区としても認識していますが、基本的にはというところもありますので、そこはこれからまた個別に具体的な検討を進める中で。","id":"exchange-097"},{"speaker":"のだて委員","kind":"質問・要望","question":"品川区としても利用できるような形で考えていっていただきたいというふうに思います。そこのところを伺いたいのと、近くを大井ルートが通るわけなのですが、この中で南大井のところを通っていくというほうに考えますと、旧東海道のところを通っていただきたいという声も寄せられまして、そうすることで南大井地域も通ることができると思うのですけれども、お考えを伺いたいと。","respondent":"鈴木都市計画課長","answer":"南大井のルートにつきましては、基本的には先ほどご説明した１１の指標をもって、効果的な地域を選出し、それから、当然ながら地域センター管内ごとで３地域選出していますが、すべてその地域センター管内の中で収束するわけではございませんので。","id":"exchange-098"},{"speaker":"のだて委員","kind":"質問・要望","question":"いろいろ回ると遠回りになったりもしますけれども、それでもバスに乗って着くということになれば、お年寄りの方も便利に、多少遠回りでも利用するということになると思いますので、利用されるルートにしていくという点でも、ぜひ検討していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"田中委員","kind":"確認","question":"資料３の今後のスケジュールについて確認をしたいのですけれども。９月下旬から１１月下旬にかけて、１３地域でのワークショップを行うということだったのですけれども、いつ開催されるのかということと、また、その周知方法について確認させてください。","respondent":"鈴木都市計画課長","answer":"周知につきましては、先ほどもご説明しましたが、広報しながら公募を広くかけるということではなくて、実施の説明については、１３地域を回って、こういうことを行っていきたいということをご説明し、また各町会宛てに推薦の依頼文。","id":"exchange-100"},{"speaker":"田中委員","kind":"質問・要望","question":"１０月２３日から１１月１３日でワークショップが開催されるということで、そのスケジュールについて、各地域でいつ行われるのかといったことを、後で一覧として資料提供していただきたいと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"そもそもワークショップを行っていること自体を知らないのではないかということについては、昨年度のコミュニティバスの検討会の実施状況は、検討会で使われている資料も直ちに公表してまいりましたし、議事録についても公表しておりますので。","id":"exchange-101"},{"speaker":"西本委員","kind":"意見","question":"もらえるのであればもらいたいのですけれども、そういうレベルです。報告いただけるのかなと思いますので。きっとそこに自由に参加できるわけではないのですよね。推薦があって行くわけですよね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"},{"speaker":"田中委員","kind":"質問・要望","question":"この陳情に関しては、そういった意味で趣旨採択を主張したいと思うのですけれども、やはり地域ごとの事情が分かるような意見交換ができる場が必要だということを再度求めたいと思います。ワークショップについて、傍聴は可能でしょうか。いろいろな地域での意見というのが聞けると思うので、ぜひ傍聴もさせていただきたいと思うのですが、いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"区民の意見の聞き方、手法についてですが、委員ご提案の、一堂に、１３地域の方、区内全域ということになりますでしょうか、集まっていただいて、それぞれの地域の課題、お困り事、要望について、そこではない地域の方々に聞いていただいて、他者を理解するですが。","id":"exchange-103"},{"speaker":"田中委員","kind":"質問","question":"ですので、地域ごとに分けるのではなくて、それぞれの状況が分かるようなワークショップを開催してほしかったのです。傍聴も駄目だということだったのですけれども、どういった様々な意見が各地域であるのかというのが、地域の中でしか分からないというのはとてももったいないことだと思うので、ぜひ傍聴は可能にできるようにお願いしたいと思います。いかがでしょうか。","respondent":"鈴木都市計画課長","answer":"だからといって、地域で行われているところがそこだけで終わってどこにも公表されないということは全くございませんで、当然ながら、当委員会、あるいはホームページ等でも、あるいは検討の会議体でも。","id":"exchange-104"},{"speaker":"西本委員","kind":"確認","question":"確認をさせてください。質問を聞いていると訳が分からなくなってきまして。今、候補が３ルートあるのですよね。１ルートにするのですか。すみません。今さら聞くのですけれども、１ルートに決めるのですか。そこをまず。","respondent":"鈴木都市計画課長","answer":"今回のワークショップについては、そのプロポーザルに進むにあたって、３ルート案について、さらにブラッシュアップしていくという意味でご意見をいただきたいというのと、先ほどご説明した運行間隔ですとか運行時間帯ですとか、そうしたところを提示する上で。","id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"分かりました。せっかく今まで積み上げて、いろいろ議論して、３つのルート案ができて、今、事業者選定をしようとやっていく中で、それでも涙を飲んでいるところはたくさんあるわけではないですか。でも変えないのでしょう。であれば、それを認めてもらうという意味でのワークショップだったら分かるのですけれども、意見を求めるなんて、私は非常に混乱するもとではないのかなと思うのですが、いかがですか。","respondent":"鈴木都市計画課長","answer":"それが反映できるかどうかというのは当然検討が必要であると思いますが、より地域に精通した方々がご意見として「それはそうだね」というところであれば、これはこの３ルート案を大筋で変えるということはないのですが、多少そこを寄って、また本筋のルートに戻っていくとか。","id":"exchange-106"},{"speaker":"西本委員","kind":"質問・要望","question":"ベースがその３ルートだということであれば、それは分かりました。ただ、「これもやってくれるのではないの」、「あれもいいのではないの」と出てきてしまうと、ベースがどこにあったのか分からなくなってしまう部分があると思うのです。せっかくここまでいろいろ検討されてやってきているので、それが崩されないような状況で、しっかりと進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"本日結論を出していただきたいと思います。結論は不採択。だけれども、もうこの３案が出てきた。これで私はいいと思っているわけです。だけれども、３案が出てきた中で、先ほどおっしゃったようなこととか、西大井も警察がいいと言えば通れる道路も出てくるわけではないですか。それで、しっかり説明をして、今のとおりで推し進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-108"},{"speaker":"大沢委員","kind":"意見","question":"本日結論を出していただいて、不採択であります。理由は、簡単に述べますが、様々なところから研究、あるいは検証をなさった資料が出てきて、なおかつこれからも住民意見を聴取すべくワークショップを開いていく。何でもかんでも住民意見だからと受け入れてしまうと混乱を生じ、ポピュリズム的になると思いますので、お気持ちは十分に分かりますけれども、この陳情に関しては受け入れることができない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-109"},{"speaker":"のだて委員","kind":"質問・要望","question":"便利なコミュニティバスを求めるという陳情でありますし、それは利用されるというものにもなりますので、住民の声を反映して、便利なコミュニティバスにしていくということが必要だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-110"},{"speaker":"田中委員","kind":"質問・要望","question":"本日結論を出すで、趣旨採択を主張します。調査について様々ご意見がありましたが、例えばこの基本方針（素案）の２８ページの携帯電話の位置情報であったりとかも、例えば上大崎とか小山台では外に歩きに行けない方たちの調査が反映されていないというところもありますし、地域ごとの話し合いではなくて、各地域の方々皆が各地域について理解できる場を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-111"},{"speaker":"西本委員","kind":"質問・要望","question":"それと、検証のほうもしっかりするというふうになっておりますので、区でこのコミュニティバスを走らせる意義というものを、どういうふうな解釈をもってやっていくのか、評価をしていくのかということも当然同時にやられると思いますけれども、区民の生活のためにかけがえのないものになるのか、そうではないのかということの現実をしっかり見ていただきたいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"のだて委員","kind":"意見","question":"共産党としては採択をしたいと思いますけれども、採決は１回しかできないということで、区民の声を受け止めるということを多くの議員で示していくということも重要だと思いますので、趣旨採択に変更したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-113"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/503098?Template=document&Id=4300#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":88871,"voices":312}},{"id":"r02-20200923-9","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"文教委員会","time":"午前１０時００分～午後 ４時５５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を143件抜き出しています。","topics":[{"id":"topic-01","title":"第５８号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第５８号議案、品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"成年後見人等の関連の欠格事由が変更になったという、その理由をお伺いしたいのと、ここにある家庭的保育事業等ということと、あと居宅訪問型保育事業は、品川区においては、具体的に何の事業を指すのか伺いたいと思います。事業実績をそれぞれ簡単に教えてください。","respondent":"若生保育支援課長","answer":"それから２点目のご質問ですけれども、家庭的保育事業、それから居宅訪問型保育事業の具体的な内容、当区における実施状況等ですけれども、まず家庭的保育事業につきましては、いわゆる「保育ママ制度」と以前から呼ばれていたものが、子ども・子育て支援法の改正によって。","id":"exchange-001"}]},{"id":"topic-02","title":"第６１号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第６１号議案、品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回は、(1)の公務災害補償の限度額の引上げの改正ということですけれども、この限度額を引き上げることになった改正の理由についてお伺いしたいと思います。","respondent":"篠田学務課長","answer":"今回、大元となった文部科学省の所管する政令、こちらの改正の理由としているのは、労働者災害補償保険法の施行規則が改正されまして、その水準と合わせて、こちらのほうも見直しをしたと聞いているところです。","id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"今回改正されるこの介護補償と災害の発生日の法定利率も含めて、毎年、このような条例改正はあるのですけれども、学校歯科医の公務災害補償ですが、直近というか、ここ１０年、２０年で分かる範囲で結構ですけれども、このようなものを使われたケースがあるのか、分かれば教えてください。","respondent":"篠田学務課長","answer":"それ以降、品川区では、１件も公務災害補償に関しては発生していないという状況です。","id":"exchange-003"}]},{"id":"topic-03","title":"第５６議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第５６議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"教育委員会所管のほうについてお伺いしたいのですが、その中で、修学旅行におけるキャンセル料等の保護者負担軽減ですけれども、私たちとしましても、地域の保護者からご相談もいただきまして、要望させていただいておりました。割と自由に、裁量権がかなり広いのか、それとも国がある程度メニューを示して、そこから選んでもらうような枠組みなのか、そういうことについてお伺いします。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目の修学旅行の実施状況についてですが、現在、１５校中７校が中止となっています。今後の予定を、新型コロナウイルスの感染状況を鑑みて、学校のほうで検討していくところです。先ほど申し上げたほか、国からは、例えばサーモグラフィーの購入経費ですとか、サーキュレーター等の購入費、あるいは学習保障として。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"７校が修学旅行を中止ということで、これから極力実施できるよう努力するということだと思いますし、そうしていただきたいのですけれども、それでも既に２校が新たに中止ということで、これからもどうなるかということはあると思うのですが、新たに２校中止が出ているということがありますし、もし今後そういった中止または延期して実施ということにならざるを得ない場合は。","respondent":"有馬庶務課長","answer":"ただ、予算計上する上では、実績が出ている分をということでしたけれども、今言ったような考え方でいけば、今後発生した場合については何らかの対応をしていくと、我々も考えているということですので、同じようにキャンセルが今後発生した場合については。","id":"exchange-005"},{"speaker":"安藤委員","kind":"確認","question":"保育園のほうですけれども、こちらも伺いたいと思います。入園事務業務委託の拡大ということですけれども、現在の委託職員の増員だと事前に伺いましたが、何人を増やすのかを確認したいと思います。保育課では、いつから入園事務業務を委託していたのか、どのような業務を委託していたのか、伺いたいと思います。先ほど、窓口の相談などもやりましたという話ですけれども、それらを伺いたいと思います。","respondent":"立木保育課長","answer":"そこから順次、業務が拡大してまいりまして、今現在お願いしているものは、データ入力および確認業務、印刷封入業務、窓口電話対応業務、延長夜間還付手続事務、在園継続事務、そのほか随時必要と思われる業務をお願いしているところです。","id":"exchange-006"},{"speaker":"安藤委員","kind":"提案","question":"これが２点目です。リスクと言うのであったら、やはりＰＣＲ検査を実施することが安心と応援になるのではないかと思いまして、今回、他部署で、介護や障害者福祉サービス事業者にはＰＣＲ検査を行う予算が提案されているわけですけれども、安全・安心のため、保育士へのＰＣＲ検査も行うべきだと思いますし、その実施を求めたいと思いますが、保育部門の考えはいかがなのか伺いたいと思います。３点目です。","respondent":"立木保育課長","answer":"それからＰＣＲ検査に関しましては、区全体の方向性もありますので、今のところ、保育現場に対してのＰＣＲ検査の予定はございませんが、今後、情勢に合わせて考えてまいりたいと考えています。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からも、それぞれ伺っていきたいと思います。説明順に従って、保育所の感染拡大対策物品購入ですけれども、これは物の形で渡すのでしょうか。それから保育士への支援なのですけれども、これは６月の一般質問でも要望いたしまして、もちろん、ほかの会派からのご要望もあったと思いますけれども、実際にこのような形で支給できることになって、非常にありがたいと思います。","respondent":"若生保育支援課長、立木保育課長","answer":"一定程度そこで必要なものは買っていただけるだろうということは見越していますけれども、今後、コロナ禍が継続していく状況も予想されるところで。窓口に関してですけれども、増員に関しましては、実は、１名増員したことによって、明確な例えば削減効果が見込めるかどうかは。相談支援の件についてのご質問ですが、こちらは一般のメンタル相談窓口、広くほかの方も使うところにというよりは、これは品川区として設置をして。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"システムも初めてだと思うので、最初からスムーズにいくかどうかも分からないことですので、そういった面でも、人を手厚めにしておいていただければというのと、本来であれば、これは年度途中だから仕方ないのですけれども、保育課の職員自体を増やす方向で、特に新型コロナウイルス感染症ですし、子どもたちの入園希望者もまだ増えていますので。","respondent":"若生保育支援課長、立木保育課長","answer":"そういったところで、少しでも保育士の方のふだんの不安ですとかストレスの緩和になればということで、プライバシーが守られる形で。職員のことに関しましても、必要な人員に関しては、きちんと要求していくということで、きちっと向き合う形で対応してまいりたいと考えています。これも体制は業務委託になりますので、請け負うところの体制にもよりますけれども、少なくともこの枠の中で、いつ相談連絡を受けても対応できる体制で。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望とはいえ、見通しを教えていただければと思います。ご努力はすばらしいと思うのですが、なかなか残念なことで、修学旅行ではないけれども、何か代替になるような、ちょっとしたイベントですとか機会を設けるという学校もあれば、教えていただきたいと思います。これは渡しきりということでよろしいでしょうか。それとも、何か清算して、使わなかったら返すみたいな感じになるのでしょうか。","respondent":"矢部教育総合支援センター長、篠田学務課長、若生保育支援課長","answer":"修学旅行につきましては、まだこれから実施予定の学校もありますので、中止になった学校につきましては。したがいまして、全額使いきってしまえばそれで問題はないのですが、残った場合は、基本的には学校を通して令達している予算ですので、最終的には。当然、そういった対応にも、コロナではないからといってお断わりすることはないような形で、仕様のほう等も考えていきたいと思ってまいります。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"入園相談窓口案内システムの導入についてですけれども、これは東京都の補助金が含まれていて、それを活用しているものですが、このシステムは、このようなものを使ったほうがいいとか、東京都側から何らかの指針があったのか。そうではなかったにせよ、これは具体的にどのようなシステムなのか。民間とか他の自治体で実際に使われているものなのか、具体的にどのようなシステムになるのかを教えてください。","respondent":"立木保育課長","answer":"以前より窓口の混雑、それから待機場所が少ないところがございましたので、そういったことの改善というところで、いろいろと他区等を調査、それから区内にも戸籍住民課でシステムを持ってありますので、そういったところをいろいろと調査・検討した結果、まずは、今。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問","question":"具体的にどのようなシステムにするのか、どのような会社を選定するのかはこれからということでよろしいのでしょうか。","respondent":"立木保育課長","answer":"今、特に随意契約でいくということではなく、必要な機能もこちらで絞り込みまして、それに合致するものを導入するという形で検討しているところです。","id":"exchange-012"},{"speaker":"筒井委員","kind":"確認","question":"続きまして、メンタルヘルス相談窓口についてですけれども、まず、これの対象は、先ほど来、他の委員からもご質問が出ていますけれども、これは別に公立保育園の保育士も相談を受けてもいいということなのでしょうかということの確認が１点。以上２点をお願いします。","respondent":"吉田保育施設調整担当課長、若生保育支援課長、立木保育課長","answer":"メンタルヘルスの関係につきましては、区立民営保育園が４園ありますけれども、指定管理もしくは委託にしているところが対象になっている次第です。具体的な数字という調査はかけていないところではありますが、１つの例として、全国の社会福祉協議会が実施した保育士等へのアンケート調査がございまして。メンタルヘルスの部分で、区立、公務員の部分に関しましては、区全体で職員の健康管理部門のほうで仕組みを持っておりまして。","id":"exchange-013"},{"speaker":"たけうち委員","kind":"確認","question":"保育士の支援です。これは、この間の一般質問でも、会派の議員から質問させていただいていて確認ですが、この２万５,０００円なりがその保育士の手元に直接行っているということの報告を受けるということでいいのですか。","respondent":"立木保育課長、若生保育支援課長","answer":"引き続きやらせていただく予定です。こういった趣旨で、感染リスクを負いながら業務を頑張っていただいている保育士の一助に少しでもなればという趣旨につきましては、きちんと伝わるように事業者等に説明していきたいと考えております。","id":"exchange-014"},{"speaker":"たけうち委員","kind":"質問・要望","question":"石けんがだめで、ハンドソープがいいという明確な医学的なものはないと伺っているので、致し方ない部分もあるのですが、お声の中に、前もどなたかの委員が言われたかもしれないけれども、学校の保護者の中にも、やはり気にする方が、特に網に石けんを入れて、少しちびてくると汚れが目立ったりして、ハンドソープという中で、いろいろと私も調べたら、学校によっては、ほかのところですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"せお委員","kind":"質問・要望","question":"２点ほど伺います。窓口混雑緩和策についてですけれども、入園事務の業務委託ということで先ほどからもお話がありましたが、業務委託を拡大するときに、入園に関しての情報が一元化をされていて、それが共有できているのかをお聞かせいただきたいのが１点です。保育士等への支援、応援給付金ですけれども、書いていないので確認ですが、すまいるスクールの職員は入らないのかを教えてください。","respondent":"立木保育課長、廣田子ども育成課長","answer":"窓口で受付やご案内をさせていただいたことに関しましては、きちっと入園相談担当職員と課内で共有されて、一律に同じ対応ができる形を取らせていただいております。現時点ではその範囲内で対応していただくというところで、今後の状況によっては、また検討しますけれども、委託料の範囲内で対応していただくと考えています。","id":"exchange-016"},{"speaker":"せお委員","kind":"質問・要望","question":"すまいるスクールのことは理解いたしました。業務委託のほうですけれども、以前に、対応する職員によってお話しする内容が違うということもよく聞かれるのですが、通常よりも見学などもなかなかできづらく、相談も電話相談だったりとか窓口に来られる方も多いと思いますので、いま一度、情報を統一していただいて、同じように案内できるように確認をお願いいたします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"横山委員","kind":"質問・要望","question":"何点か確認させてください。窓口混雑緩和策についてですけれども、先ほどの議論の中でもありましたが、窓口発券機は、戸籍住民課等で導入している整理券のようなイメージでよろしいのでしょうか。入園相談窓口案内システムですけれども、ウェブ予約ができるようになるのはすごくいいと私は思っておりまして、こちらはいつ頃にスタートできる見込みなのでしょうか。","respondent":"立木保育課長","answer":"スタートに関しましては、可及的速やかにということで、今、考えておりまして、１２月の一番混雑する時期前にとにかくスタートしないと意味がございませんので、そういった形で、今、準備を進めているところです。","id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"何点かお伺いします。最初に、保育所等の感染防止対策物品購入で、先ほど、あべ委員からも少しありましたけれども、状況を聞きながら配付されるということで、これは消耗品は、ある意味、余っても使えるのかなと思うのですが、空気清浄機等というところで、空気清浄機が入っているところに何個も送ってもしようがないのかなとも思っていますので、これはぜひ希望を確認をしていただきたいのが１点。","respondent":"立木保育課長、吉田保育施設調整担当課長、若生保育支援課長","answer":"ウェブ案内、予約ができるようになりますとか、待ち時間、例えばメールでお知らせすることができますという新しい仕組みに関しましては。消耗品や空気清浄機につきましては、現在、導入を予定しているものは、新型コロナウイルス感染症対策として、ウイルスの軽減に役立つものについて。メンタルヘルスの相談支援事業の来年度以降につきましては、これは歳入が見込めるかどうかというところは未確定というか。","id":"exchange-020"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"最後に周知の件でもう一点だけ。今のお話でホームページをという話がありまして、なかなかホームページだけだと難しいかとも思いますので、来ていただいた後でも結構ですので、相談が終わった後や、あとは相談案内のパンフレット等に記載していただいて、今後はウェブでのシステムをこれから導入していきますという案内をしていただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほどの答弁の中で気になったのですが、保育士の相談ですけれども、相談対象に公立は入れないということですが、公立で働けば、派遣の方は職員の相談システムではなかなか厳しいかと思うのですけれども、そこは対象になるのか、あるいはどのようにお考えなのか教えていただきたいのと、それから相談の内容で、コロナ禍での保育の在り方のようなものは、臨床心理士というより。","respondent":"立木保育課長、若生保育支援課長、篠田学務課長","answer":"公立保育園の派遣の職員の方は、今回、メンタルヘルスの区の仕組みの中では、今のところは入っておりませんので。相談内容の中でベテラン保育士等というところですけれども、こちらについては、心理的な負担というところで言えば。こちらに関しましては、今回の補正予算自体が、国の補正予算の補助金に基づいて組んでいるものですので。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"保育園の入園事務で重要な窓口対応相談を委託し、拡大するというのは問題があるので、やはりこれは正規の職員で対応すべきだという意見は言わせていただきたいと思います。その上で、公・私立を問わない支給ですとか、それにこの場を借りて言いたいのは、感染リスクのさらに最前線で働いているのは医療従事者なので、そういったところにも支給を求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"あべ委員","kind":"質問・要望","question":"いろいろと要望を出させていただきましたので、そういったこともご検討いただきながら、本件には賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-04","title":"す。 予定表では(1)令和２年度請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)令和２年度請願第１２号","agenda":"す。 予定表では(1)令和２年度請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(2)令和２年度請願第１２号","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、保育のほうは加点があるということで、平成２９年に国の通知があったということですが、今、保育園の方に加点をしている理由を教えていただきたいのと、現時点で区は、こういった特別な配慮が必要だと考える職種の方々をどのように考えているのかを伺いたいと思います。","respondent":"立木保育課長","answer":"それから支援が必要だと思われる方も、今回、緊急事態宣言等の中でもお預かりをさせていただいた、社会機能を維持するためのご職業に就かれている保護者の方等ですけれども、区の姿勢としては何かしらの支援が必要ということは、当然、考えておりますが、一方。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"そうですね。かなりいろいろと、社会を維持するのに必要な職種というのは、本当に広いと思いますし、支援が必要だというのは、私も同感です。保育のほうでは、実際に働いている全ての方が対象ですという話があったのですけれども、そもそも国の通知の紹介もありましたが、中身にも関わると思うのですけれども、保育士の方を加点するということになった理由を聞きたかったので、もう一度お願いします。","respondent":"立木保育課長","answer":"当時、待機児童が多い中では、まず働く人を確保した上で、待機児童を受け入れて、待機児童を減らしていくという意図の中で、保育園で働く保育士の職場復帰を後押しするという形で、加点を検討しなさいという通知が来たです。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"保育従事者に調整指数プラス１とされたのは、平成２９年の国の通知によってだというご説明でしたけれども、今回の請願で議題とされている医療従事者に対しては、調整指数加点について、国は今、現時点でどういった動向なのでしょうか。何か区として把握されていることがあったら、教えてください。","respondent":"立木保育課長","answer":"今のところ、職業に対しての加点というのは、ご説明に挙げた保育士等だけでございまして、厚生労働省に確認を取ったところ、ほかの職業に対して何かしら通知を出すということは、今のところないと聞いております。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"そのようなことですけれども、ただ、区としては、医療従事者に対して何らかの保護というか、そうした優遇策をしてあげたいということでしたが、その１つが、保育園入園時の調整指数加点、こういったことも区としては一方策として受け入れられるということでよろしいのでしょうか。","respondent":"立木保育課長","answer":"幾つか方法がある中で、どれがベターなのかというところは、いろいろなデータ等も参考にしながら検討する必要があると考えているところです。","id":"exchange-028"},{"speaker":"あべ委員","kind":"質問・要望","question":"保育士に対する加点がある現状からいっても、また、新型コロナウイルス感染症以前からも医療関係者の方々には加点が必要ではないかという議論は、一定あったかと思います。その辺の線引きは、技術的に可能でしょうか。ある程度線引きができるのであれば、ぜひ前向きに考えていただきたいですけれども、いかがでしょうか。","respondent":"立木保育課長","answer":"若しくは、「緊急事態宣言で対象になった職種」というくくり方もできようかと思います。このどこら辺に線引きをするかというところは、現時点でどの程度というところまでは検討が進んでおりませんで、今後ということになるかと思います。","id":"exchange-029"},{"speaker":"たけうち委員","kind":"質問・要望","question":"会派で紹介議員になったので、これについて特に異議を唱えるのではないのですが、もし分かれば、各自治体によって既に医療従事者にこのような形で対応している例も、２３区でも少しあるかと思うので、その辺の情報があれば教えていただきたいのと、あと、今、品川区ではないと思うのですけれども、一方で医療従事者のお子さんに対して、保育園での「来ないでくれ」というような。","respondent":"立木保育課長","answer":"それから保育園における、例えば優先入園、何らかの優先をつけた場合、優遇措置をした場合の園での対応、それから、その他のご批判等についてですが、一定程度の例えば対象から漏れた方からのご意見は、当然、想定はされるところですが。","id":"exchange-030"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。あえて医療従事者なので、身近なところで新型コロナウイルス感染症の対応をされているがゆえの逆の排除されてしまうような、そこに加えてこの加点ともしなったときに、さらなる何か、そのような人も中にはいらっしゃるので、そこはぜひしっかりと考えていただきたいと要望しておきます。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"横山委員","kind":"質問・要望","question":"対象者の範囲が広くなりますと、政策の効果が出にくくなることを私は懸念しておりまして、職種、施設、所得制限を設定したりですとか、他の自治体の保育士の事例ですと、そういったものですとか、区内や市内の勤務の方というようなやり方もあるように思いますが、私は、ある程度範囲をしっかりと絞って効果を出していただきたいと考えているのですけれども、そのあたりの現在のお考えはいかがでしょうか。","respondent":"立木保育課長","answer":"加点と加点以外、加点、優先入園以外の方法ですが、なかなか難しいところでありますので、すみません、今はすぐ思いつくところはございません。","id":"exchange-032"},{"speaker":"横山委員","kind":"質問・要望","question":"いろいろと確認させていただきました。特に医療従事者の方もそうですけれども、それ以外の区民の方に対して、なるべく早いタイミングで確実に情報が届くような方策を採用していただきたいと要望したいと思います。","respondent":"立木保育課長","answer":"いろいろと内容が変わることに関しても、事前に制度上変わることがありますというような表記に関しましては、何か不都合がないかどうかは、確認した上で対応してまいりたいと思います。","id":"exchange-033"},{"speaker":"横山委員","kind":"質問・要望","question":"なかなかこういった新型コロナウイルス感染症の対策の一部という形で、緊急的にこういった請願が出されて、また、スピーディーに対応しなければならないということで、通常時であれば、しっかりとした準備期間ですとかスケジュールを取ることができるかと思うのですけれども、なかなか事務的にも大変な部分が出てくるかと思うのですが、周知をできるだけ多くの必要な方に届く形で検討していただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"芹澤副委員長","kind":"意見","question":"本日、結論を出すで、採択でお願いします。内容としても、会派で様々やり取りをしましたけれども、エッセンシャルワーカーと呼ばれる大きな職種の中でも、医療従事者が先端に立っていると考えていますので、ぜひ後押しをしていきたいという思いでの紹介議員にもなっております。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"せお委員","kind":"意見","question":"本日、結論を出すでお願いします。結論としては採択でお願いいたします。医療従事者は、本当に大変な状態にありますので、保育をとても必要としていると思います。先ほどから議論がありますが、医療従事者という範囲だったりですとか、その対象となる範囲を、とても時間がないとは思うのですが、そこの議論もぜひ慎重にしていただいて、こちらをお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本日、結論を出すで、採択でお願いします。何とか来年の４月に間に合うように、大変ですけれども、よろしくお願いいたします。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択なのですが、一言、述べさせていただきたいのですけれども、先ほども出ましたが、加点というのは、必要な保育園整備完了に向けた過程の中での暫定的な措置であるべきだというふうな考えがあります。今こそ保育をはじめ、ケアの手厚い区政にも転換していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。先ほど来からお話にも出ているように、医療従事者の範囲や、その定義の明確化と、また、これが新型コロナウイルス感染症収束までの期間限定のものなのか、また、ほかの職業の方の公平性、国や都の動向などもしっかりと注視していただくといったことを考慮していっていただいて、そうしたことも検討していっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということで、採択でお願いしたいと思います。途中から減らすのは大変難しいことですので、少なくとも初めは職種限定的な考え方で、医療にダイレクトに関わっていらっしゃる職種を中心に検討していただき、かつ、その方々については、できるだけ早くこの制度が実現できるように頑張っていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"横山委員","kind":"意見","question":"結論を出すで、採択でお願いします。早急かつ慎重な対応をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]},{"id":"topic-05","title":"令和２年請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年陳情第４１号、品川区立学校図書館設備充実に関する陳情","agenda":"令和２年請願第１１号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年陳情第４１号、品川区立学校図書館設備充実に関する陳情","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"それで、やはり情報化が進んでいく中で、実は私、今回の陳情が出るまで学校図書館でインターネットが通じないなどと考えもしなかったものですから、ちょっとびっくりいたしました。その中で、既存の学校内でも、ある程度、自由に使える端末が出てくるのではないかと思います。品川区としては、今なぜつながっていない状態にあえてしているのか、今後の考え方について教えてください。","respondent":"横山品川図書館長、篠田学務課長","answer":"今現在、現状としては、説明申し上げましたように、個人情報を抱えているシステムとの併存が難しく、区役所の中でも個人情報とインターネットの接続はできるだけ分離するということで、実は学校図書館のシステムリプレースの際にも。現状、図書館で、図書館のシステム上つながっていないというのは、今、品川図書館長から説明があったとおりですけれども、現状は、もう既に無線ＬＡＮの構築は全ての学校で完了しています。","id":"exchange-042"},{"speaker":"あべ委員","kind":"質問・要望","question":"司書の立場で先生たちの教材探しなどをサポートしたり、お伝えしたりということも、せっかく来ていただいているわけですから、したほうがいいに決まっているわけです。そのレファレンス機能を十分に果たすためには、やはり学校に来ている間も自由に情報にアクセスできる立場にいたほうが、学校の学びにとって私は有利だと思いますけれども、あえて使わないのはむしろもったいなくないでしょうか。","respondent":"矢部教育総合支援センター長","answer":"今の委員のお話を受けてですけれども、ＧＩＧＡスクールになりますと、１人１台お子さんにタブレットがわたります。現在、学務課長からも説明があったとおり、各学校に４０台のタブレットパソコンが置いてありますので、今、それを活用して学習しています。","id":"exchange-043"},{"speaker":"あべ委員","kind":"質問・要望","question":"これはむしろ学校の校長先生の裁量の部分も結構あるかとは思うのですけれども、その校長先生の意識によって、あるいは学校の先生方の考えによって、司書がインターネットに接続できたりできなかったりという状態自体がもったいないなというふうに思っております。そうした方向で、ぜひ考えていただきたいなと。それをすることのデメリットは特にないと思うのですが、いかがでしょうか。","respondent":"横山品川図書館長","answer":"それが全体に及んだ際に、改めて学校図書館の配備も考えられると思います。","id":"exchange-044"},{"speaker":"たけうち委員","kind":"意見","question":"この陳情書の中で、下から２段目の上から２行目の辺り、「これまでの調べ学習では、ＰＣ室と図書館が離れているところが多く、インターネットで調べる児童生徒と本で調べる児童生徒が別の教室で調べるため、教員にとっても、図書館スタッフにとってもサポートしにくい学校が多くありました」となっているのですけれども、その辺の状況は、実態としてはどのような感じで教育委員会は捉えていますか。","respondent":"横山品川図書館長","answer":"現状は確かに離れているので物理的な制約は今まではあったと思いますが、まさにＧＩＧＡスクールで生徒が１人１台持っているという形になれば、学校図書館のスタッフも教諭の方も、そちらをサポートする形で調べ学習を進められるので。","id":"exchange-045"},{"speaker":"たけうち委員","kind":"質問","question":"分かりました。そのような中で、各図書館スタッフが使えるような形という、これは子どもたちに対してというふうに受け止めた部分と、最後のほうでは、図書館スタッフとあるので、そういった面では、ＧＩＧＡスクール構想でいいますと、子どもたちには１台、それを重々活用しながらと。先ほどあったとおり、図書館スタッフの方も使えるようなものが既にあると、こういうことでよろしいのでしょうか。","respondent":"篠田学務課長","answer":"現状は、今、委員ご指摘のとおり、要は、機械自体はいろいろな形で工夫をすれば学校の中にもあるということですので、そこはＧＩＧＡスクールの導入に合わせて、その使い道についてもいろいろと検討して工夫をしながらやっていけるのかというふうに思っているところです。","id":"exchange-046"},{"speaker":"筒井委員","kind":"確認","question":"具体的に司書がタブレットを持つことで、ＰＣ端末を持つことで、どのように子どもたちに対して教育をしていくのか、そうした具体的な活用方法が、これも急ですから見えない中、いろいろと現時点ですぐというわけには、品川区としても難しいかと考えていますけれども、今後、ＧＩＧＡスクールということが定着していって、やっぱり教員以外にも司書、図書館スタッフにも１人１台持つというようなことを。","respondent":"篠田学務課長","answer":"ただ、これから先、情報化が様々な形で進んでいく中で、例えば国などがそういった考え方を示されるかどうかといったこともあろうかとは思うのですけれども、その辺は十分見据えながら、ただ、最低限必要な部分にはきちんと手当てをしていくということで。","id":"exchange-047"},{"speaker":"筒井委員","kind":"質問・要望","question":"ぜひ検討していっていただきたいのですけれども、国の動向ということもおっしゃられたのですが、やっぱりＧＩＧＡスクール構想という中、なぜか図書館のスタッフにタブレットがないというのもちょっと違和感を覚えますので、国はその点をどうお考えなのか、あまりお気付きになっていない点なのかちょっと分からないのですけれども、そうした動向をしっかりと見ていただいて、また、今現在。","respondent":"篠田学務課長","answer":"文部科学省の基本的な考え方としては、今回のＧＩＧＡスクールに関しては、子どもたちが、１人１台、きちんと使いこなせるような環境をつくりましょうと言っている中で、言ってみれば、教員に関する部分は、区としてその辺は配慮するといったところです。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問","question":"陳情のほうに新学習指導要領が引用されています。四角の部分です。学校図書館は、子どもの情報活用能力の育成にとって重要で、計画的に活用することで、主体的・対話的で深い学びの実現に向けた授業改善に生かすとありますけれども、区の学校教育要領では、この辺のところといいますか、学校図書館と情報活用能力の関係ですとか、どのような位置付けになっているのか、改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"インターネットの情報は、その中の情報は正しいのかどうかも含めて、そういったものも含めた情報活用能力、広く育成が必要であるということは教育要領でも示しているところではあります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問・要望","question":"もう少し聞きたいのですけれども、４０台あるというのは、今まで先行してやっていたところもあって、今度、１人１台来ると、品川区全体として４０台余るから、それをいろいろなものに活用できるということなのか、もう少し聞かせていただきたいのと、それと、ＧＩＧＡスクールの１人１台ということなのですけれども、教員と児童・生徒には配るということなのですが。","respondent":"篠田学務課長","answer":"特に今回は、ＧＩＧＡスクールにおきましてはｉＰａｄを入れるという形で機種の選定を進めているところであるのですけれども、４０台についてはＷｉｎｄｏｗｓの機械ということになっていまして、この先。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"暫定的な対応はもちろん必要かもしれませんが、その中でも校長の判断とか、場所によってはそうならないとか、それですと、やっぱり私はまずいと思うので、しっかりと区として図書館スタッフが日常的に使える端末を保障していくというような考え方を示すということが大事だと思いますし、必要であれば、財政措置も講じて整備するということは必要だと思いますけれども、いかがでしょうか。","respondent":"篠田学務課長","answer":"先ほど申し上げたとおり、リースがまだ残っている機械が引き続きあったりとかということもありますので、そういったものの活用等は改めて学校の中でどういったことが必要なのかというのは、それぞれ学校の事情もありますから、考えながら進めていけるのかと考えているところです。","id":"exchange-051"},{"speaker":"安藤委員","kind":"意見","question":"最後に意見ですけれども、学校教育、教育の環境整備というのは、やっぱり区の役割といいますか、教育行政の大事な役割だと思いますので、ぜひしっかりと整備していただくようにお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"ＧＩＧＡスクール構想の考え方がそれぞれあるのかと思うのですが、先ほど、図書館が閉鎖されているというような発言があったと思うのですけれども、私は逆に、校内無線ＬＡＮがつながっているのであれば、全世界につながって開かれているということだと思っていまして、端末に関しても、図書館に置いてある今の端末を、なかなかインターネットが使えないというようなお話からの議論だったと思うのですが。","respondent":"篠田学務課長","answer":"基本的にはこの補助金はいろいろと難しい制約がございまして、例えば契約にしても、これまで文部科学省が様々な形でＩＣＴ化を推進してきているということもございまして、今回、必要な台数の３分の２だけを補助しますという仕組みになっています。","id":"exchange-053"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"もう１点確認で、今の外から持ってきたパソコンの接続に関してですけれども、これは設定というのは、パスワード等を教えてもらってという話ではなくて、複雑な設定があるということなのですか。例えば、事前に持っていきたいので、当日、インターネット接続をさせていただきたいというようなお話があっても、なかなか使うことはできないのでしょうか。","respondent":"篠田学務課長","answer":"したがいまして、１台１台、いわゆる家庭で使うようなＷｉ－Ｆｉを簡単に接続できるというような形にはなっていないところがありますので、もしどうしてもおつなぎになるということであれば、事前に私どもの学務課に校務情報管理対策担当がおりますので。","id":"exchange-054"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。理由としましては、先ほどいろいろな議論がありましたけれども、まずは持っている端末を使っていただいて、今後の可能性についてはこれからも議論されるのだろうと思っていますが、まずは今の時点では使えるものを使っていただきたいという意味での不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"せお委員","kind":"意見","question":"先ほどから議論やお話がありますが、１人１台、これからはタブレットを児童・生徒にお渡しするということであったり、これから急ピッチでＧＩＧＡスクール構想に向けて動いていく中で、整備だったり、タブレットの活用方法、授業内容とかもそうですけれども、本当に整備していかなければならないことがまずたくさんありますので、そこのところが整理できてから検討していただくのもよろしいかと思いますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"たけうち委員","kind":"質問・要望","question":"それを活用していく調べ学習についても、どういう形でこれから新しい流れの中でやっていくのか、また、その中で学校図書館スタッフがパソコンを使った場合に、どういうメリットが出てきて、どういうことをやっていけるのか等、もうちょっと整理をしっかりとしていただく中で今後構築していくというお話もありましたので、その上で果たして専用のものが必要かどうかも含めて検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"安藤委員","kind":"意見","question":"ですので、採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問・要望","question":"ただし、急なＧＩＧＡスクールの話が出てきまして、当然、端末配備の優先順位もありますし、予算の制約や図書館スタッフの具体的な活用方法がまだよく分からないという点もありますけれども、今後、そうした課題が解消されたときには、やはりせっかくの熱心な図書館スタッフのお力を活かしていく、また図書館スタッフのお話を伺って、スタッフの具体的な活用方法をしっかりと詰めていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すで、採択でお願いしたいと思います。スタッフはちょっと大変になるかもしれないのですけれども、そこは力を合わせて学校のために頑張って動いていただければというふうに、その環境が、繰り返しますが、現状の持っているもので十分進めていくことは可能だと思いますので、できる学校から進めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"横山委員","kind":"質問・要望","question":"その次の段階として、将来的に、現在残っている端末ですとか、どういったふうに使っていけるのか、また、司書だけではなくて、学校や子どもたちを取り巻く方々にとって、どういった使い方、共有なのか、またセキュリティの観点ですとか、フォルダー共有ですとか、クラウドを使うですとか、そういった様々な細々したことも発生してくるかと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-06","title":"令和２年陳情第４５号、２０人学級で学べるよう教職員の数と予算を増やし教育環境整備を求める陳情","agenda":"令和２年陳情第４５号、２０人学級で学べるよう教職員の数と予算を増やし教育環境整備を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"陳情本文のところに、分散登校時の子どもや教員の声が具体的に紹介されていますけれども、前回も聞きましたが、改めて、品川でも実際に少人数学級を体験することになった分散登校時に、子どもや教員からどういう声が挙がっていたのか、どのような声を聞いたのかということと、その受け止めです。聞いた声のご紹介などがあれば伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"今のご指摘ですけれども、６月の初めはやはり２か月お休みしていましたので、子どもたちは緊張した面持ちで教室に入っております。３密を避けるというところから、静かなスタートでございました。約半数ですので、そういうような状況です。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、一般質問で私も同様のことを求めて質問しましたが、新たに必要な教室数と教員数を伺ったのですが、単純に倍必要ですみたいな答弁だったのですけれども、改めてどういう意味だったのか伺いたいのですが、４０人を２０人にしたら単純に２倍ですというふうにしか聞こえなかったのですけれども、品川区としては、現在の４０人学級制度に基づく学級編制を２０人程度の学級するという上で。","respondent":"矢部教育総合支援センター長、篠田学務課長","answer":"１点目につきましては、子どもたちと非常に似ていることだと思います。教員は感染防止のために様々な工夫等をしますので緊張感があったこと。そうしたところ、やはり５００以上の学級数が増えるのは間違いないというところは出ています。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"そこら辺は後ほどぜひ聞きたいと思います。そういう声はないのですかと聞いているので、くどいですけれども、もう一度お答えいただきたい。そして、一般質問のあれですけれども、再々質問で伺ったところ、答弁では少人数学級に対しては終始慎重というか、全く前向きな答弁がないのですが、かわりに少人数編制、加配を要望しているというようなご答弁があったと思うのです。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"１点目の件についてです。先ほど、学務課長からも話がありましたとおり、ご指摘のとおり、少人数も大人数も教員の苦労は少しはあります。今、教育総合支援センター長からもありましたように、少人数指導による効果というのは、私どもも重要に考えておりますので、そのため、このコロナ禍の分散登校時ということも含めまして、従来からできるように、引き続き。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"そう言う方もいます。私も問題だと思っています。それは違うと思うのですが、そこは認めますでしょうか。","respondent":"工藤指導課長","answer":"委員ご指摘の点ですけれども、そういう意味では、少人数指導、また習熟度別指導、それが個に応じて適切な指導を行う場面で必要なところで行っているところがありますし、また、学級において複数の指導者が入る、いわゆるチームティーチング、ＴＴの形で行いますので。","id":"exchange-065"},{"speaker":"安藤委員","kind":"提案","question":"少人数学級を導入すべきだというのは、私ももちろん提案しましたけれども、この陳情にあるように、今、コロナの経験もしまして、いろいろな角度から、何よりも子どもの現状がそういうことを求めているというふうな状況だと思いますので、詳しくは繰り返しません。代わりということで答弁しているわけではないということでよろしいのですか。全く別な話でしているということなのですか。","respondent":"篠田学務課長","answer":"ひるがえって考えますと、２０人学級にするということは、２０人で学級編制をするということですから、２１人になった瞬間に、１０人のクラスと１１人のクラスをつくらなければいけないということになりますから、これはさすがにいかがかというところがありますので。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問・要望","question":"陳情者の方は、恐らく、分からないですけれども、２０人学級というのを厳密な学級編制の意味で言っているのかというのが正直分かりません。恐らくですけれども、２０人ぐらいの学級にしてほしいというふうな、普通大体そう思いますよね。ということで、私は、これは今、本当に求められている内容だと思いますので、ぜひこれは区の意思として、議会の意思としても採択していきたいという思いがあります。","respondent":"齋藤教育次長","answer":"したがいまして、私どもは、物理的に東京を含めて首都圏では、２０人での学級編制は難しい以上は、加配あるいは区の予算で講師、指導助手を加えて、４０人を２人の大人の教員の目で見る、私どもは実績、ノウハウを持っておりますので。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"それはそうだと思います。いろいろと想定される課題を挙げていただいたと私は思うのですけれども、そういったことを踏まえてでもなお、欧米などに比べても本当に何十年も遅れている学級規模の問題、これはやっぱり今だからこそ、ここを変えていくことに挑戦すべきだと思うし、それを品川区としても全国の流れ、思い等に共鳴して進めていく先頭に立っていただきたいというふうに私は思っております。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問・要望","question":"今の議論、日本の学級編制は上限主義をとっているので、４０人を超えると分割して、もし２０人ならそれを分割しなければいけない。でも、やっぱり国に対しては、現場の声として学級編制をもう少し緩やかにしてほしいというような声は、ぜひ上げてほしいと思うのです。そういったことは区としてはされていますでしょうか。","respondent":"篠田学務課長","answer":"ただ、学級編制として少人数学級を求めているものではなくて、少人数学習の環境を整えたいという思いでこれまでも要請していますので、基本的な考え方は同じような形で今後も対応していくと考えているところです。","id":"exchange-069"},{"speaker":"あべ委員","kind":"質問・要望","question":"長期的なものになりますし、国の意向や都の意向も勘案しながらということかもしれませんけれども、やっぱり今の世の中、４０人というのは、なかなか子どもたち、低学年は３５人とかありますけれども、もう少し少ない編制の中で子どもたちが安心してその集団の中にいられるようなことも、区として現場の声として考えていただきたいし、実現にたとえ時間がかかるとしても。","respondent":"齋藤教育次長","answer":"本会議でご答弁したとおり、国、都の基準が基本ですので、まずはこれに従った教育活動を実施してまいります。","id":"exchange-070"},{"speaker":"筒井委員","kind":"質問","question":"２０人学級、少人数学級のメリットとしましては、きめ細やかな指導が可能だということと、現在、コロナウイルスの感染拡大に伴って、その防止と消毒などの対応がしやすいということもあると思うのですけれども、逆に、大人数学級のメリットというのは、何回かお話が出たかもしれないですが、改めて大人数学級のメリットはあるのでしょうか。","respondent":"矢部教育総合支援センター長","answer":"隣同士で人数の少ないところというよりは、全体でやることで士気が上がったり、時にはライバル意識を高めて力が入ったりという相乗効果もあるかと考えております。","id":"exchange-071"},{"speaker":"筒井委員","kind":"質問","question":"そうしたメリットもあるということも見ていかなくてはいけないのかと思っていますけれども、少人数学級にしたときの、先ほどからプレハブということも出ましたが、実際、では、品川区が２０人学級を実現したとしましたら、設備はどのぐらい増やさなければいけないのかとか、教員数がどのくらい増やさなければいけないのかということは、大体お分かりになっているのでしょうか。","respondent":"篠田学務課長","answer":"先ほど、私のほうで５００と申し上げたのは、５００以上かかるというのは、今の子どもの数を素直に分けるとそうなるということですので、ただ、この先、当然子どもたちが毎年増えていったりしていますから、増えれば当然、学級編制というのは先ほど申し上げたとおり。","id":"exchange-072"},{"speaker":"筒井委員","kind":"質問","question":"ただ、報道とかでは、知事会などの３会長などの文部科学大臣との面談で、文部科学大臣が少人数学級に対して前向きな姿勢を見せているというようなこともありますし、また、今、コロナウイルスの感染拡大で、地方に転出していくという人とか、あと、そもそも人口自体が減少していくということもあるのですけれども、そうした将来の変動とか、また文部科学省が少人数学級を進めようと言ったときに対しては。","respondent":"篠田学務課長、工藤指導課長","answer":"ただ、いずれにしましても、現状、法律で１年生は３５人、それ以外は４０人という形で規定がされていますから、それが変わるとなれば、当然その法に従って対応していくことは間違いないということだけは申し上げられると思います。そういった意味で、少人数編制を進めるべきだという議論があるというふうに認識していますので、その中で私どもは東京都の加配等も含めて、区の講師等も含めてきめ細かく対応しているというところが私どもで進めているところです。","id":"exchange-073"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。引き続き、区においては４０人学級、国と都の基準に従って教育現場をつくっていただきたいというのと、あと、コロナのお話もありましたけれども、今、休校、そして分散登校を経て、今の状態でもしっかりと感染の拡大を抑えられているという認識もありますので、こちらも引き続き適切に臨んでいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"本日結論を出すでお願いします。不採択でお願いします。２０人学級のメリットは理解できます。ですが、先ほどから答弁がありますように、課題は多過ぎて現実的ではないと思いますので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"かつてないようなストレスと不安も抱えながら頑張って、今、登校しているわけですけれども、やはりそういった現状が学級規模のさらなる縮小を強く求めておりますので、柔軟で手厚い教育を実現させていく必要があると思います。採択を求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"筒井委員","kind":"意見","question":"本日結論を出すで、不採択といたします。その理由は、面積、設備、教員数などの物理的な制約、また、将来的に方向性としては少人数学級の方向に行く可能性はあるでしょうけれども、具体的に２０人という数字は現実的に言って困難だということからです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-077"},{"speaker":"あべ委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いします。ただ、これを区が単独ですぐにできるものではないということ、もしそれをやろうとすると、逆に学校教育の根幹からかなり崩れてしまうというか、マイナスの影響が大きいということで、具体的に踏み出す状況にはないということで、申し訳ないですけれども、これは不採択ということで考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-078"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。学級編制は法の規定と国や都の基準にのっとり対応をしていただいて、教える教科、単元、内容と、お一人お一人のお子さんの学習状況によって、少人数指導や習熟度別学習や、またチームティーチングなどを適切に実施していただきたいというふうに考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]},{"id":"topic-07","title":"令和２年陳情第４８－２号、子どもが健やかに育つための陳情（陳情項目１、２）","agenda":"令和２年陳情第４８－２号、子どもが健やかに育つための陳情（陳情項目１、２）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ質疑の前に陳情者のご意見は聞きたいと、その上で、そういったことも含めて質疑に活かせると思いますので、そのようにしていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"あべ委員","kind":"意見","question":"意見陳述をしたいという趣旨は、それを聞いた上で審議してほしいということだと思いますので、常識的に考えて、意見陳述は議論の前にしていただければいいなと、それでないと、なかなか逆に、意見陳述の機会を設けている意図が不明確になってしまうことと、全国の自治体議会を見ておりまして、やはり意見陳述は前にする議会が多いのではないか、ごめんなさい、数字は持っていないのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"たけうち委員","kind":"質問","question":"区議会、私も長いことお世話になっていますけれども、なかなか意見陳述を受けたケースも少ないわけですが、いい悪いは別にして、内容によって、事前にお聞きするものと、そうではないものという形で言えば、非常に分かりやすい内容になっているかと思いますので、質疑を終わった後で必要かどうか諮っていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"あべ委員","kind":"質問","question":"陳情１のほうですけれども、コロナということもありますし、いろいろと心配事を相談するときに、何かを１回渡したからこれで十分ということではなくて、受け取ったときにはあまり関心がなかったけれども、その後、悩みが出てくるとか、相談したい気持ちになるというのはあると思うので、いろいろな、チャイルドラインに限らずでいいと思うのですが、様々な相談先について。","respondent":"矢部教育総合支援センター長、黛生活安全担当課長","answer":"相談窓口の周知につきましては、委員おっしゃったとおり、相談窓口については約１０か所程度、１枚にまとまった東京都からの案内があります。そこに本区のＨＥＡＲＴＳも含めた相談機関を載せて、複数回、学校に周知しています。今、委員からご指摘をいただきました点ですが、まだいろいろと検討しなければいけないところはあるとは思うのですけれども、１つの考えとして、例えばですが、今、委員からアドバイスをいただきましたように。","id":"exchange-083"},{"speaker":"たけうち委員","kind":"提案","question":"それから２点目のほうです、今、あべ委員からもいい提案があったと思うのですが、我々としても、このチャイルドラインのやられているすばらしい取組みについては理解しているのですけれども、やっぱりそういうふうにやっていらっしゃる区内の団体の方もいっぱいいらっしゃるので、その中でどこも品川区としてバックアップしてもらいたいと思う中で。","respondent":"矢部教育総合支援センター長、黛生活安全担当課長","answer":"少しご心配の旨かと思いますが、学校は、到着しましたら、それを配らないということはないので、確実に配布していると認識しております。ただいま委員からご意見をいただきましたとおり、まさにそういう子どものための大変有意義な活動をされている団体も多数あるところでございまして。しながわチャイルドラインとは、ご担当者が教育長のほうにもご挨拶にみえたということで、そういう連携。","id":"exchange-084"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。今、報道等で、コロナの影響で、子どもたちというよりは、全体的にようやく十何年かけて減ってきた自殺者が、７月、８月と増える傾向にあるという中で、これからまたコロナによるいろいろな影響で、親御さんがお仕事を失業してしまったとか、また商売があれしたとか、いろいろなことでいろいろな家庭内のごたごたが出てくる中で、自殺者の増加がちょっと懸念されているのです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-085"},{"speaker":"横山委員","kind":"確認","question":"２点お伺いしたいと思います。ＮＴＴ東日本による２０１７年１２月の公衆電話に関する調査では、公衆電話を知らない、使ったことがない子どもは合わせて８４.３％いるというようなデータがありまして、ちょっとこの辺りを確認、もし分かれば教えてください。","respondent":"有馬庶務課長","answer":"公衆電話の使い方などというところは、市民科で教えているかどうか分かりません。基本的には家庭でというところになるかと考えています。","id":"exchange-086"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、まもるっちに、今、登録として、ＨＥＡＲＴＳはもともと入っている。ＨＥＡＲＴＳが入っている理由は、やはり教育総合支援センターという区の公的機関だからという理由でよろしいでしょうか。","respondent":"黛生活安全担当課長","answer":"委員ご指摘のとおりです。","id":"exchange-087"},{"speaker":"筒井委員","kind":"質問","question":"はい、分かりました。ＫＤＤＩと保護者の方の何を登録するのかというのは任意だということなのですけれども、傾向として、保護者の方は大体どのような番号を登録されているのでしょうか。分かる範囲で。","respondent":"黛生活安全担当課長","answer":"大変申し訳ございません。契約に関するところにつきましては、当担当で認知はございません。","id":"exchange-088"},{"speaker":"安藤委員","kind":"提案","question":"ご説明、質疑も聞きまして、ＨＥＡＲＴＳは登録しているということで、令和５年に新システムに移行すると。令和３年度からいろいろと検討を始めるということなので、非常にタイミング的には、すごくいいタイミングでの具体的な提案なのかというふうに思います。ぜひ検討していただきたいと思います。ですから、やはり区も支援を強めていただきたいと思います。これは意見です。先ほどの質問だけお願いします。","respondent":"矢部教育総合支援センター長","answer":"委員お話のように、大変ありがたい取組みだと思って感謝しているところですが、本区では、重複しますが、市民科の５年生から７年生でカード自体も取り上げて指導しておりますので、支援を強めるという委員のお言葉に当たるかというふうに考えております。","id":"exchange-089"},{"speaker":"安藤委員","kind":"意見","question":"ぜひこうした区民の方の思いを議会として拝聴する場は貴重ですし、この陳情審査においても非常に有益だと思いますので、意見陳述をぜひお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-090"},{"speaker":"あべ委員","kind":"質問","question":"私も意見陳述を伺いたいと思います。今の質疑の中で、品川区あるいは区教委としても、一定の連携をしつつ、カードも配布したりということを聞きました。そういった状況であって、なおかつこの陳情が出てきているということは、その背景は何なのかということも含めて、ぜひ今、聞きたくてうずうずしているのですけれども、ぜひ意見陳述をお願いできればと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-091"},{"speaker":"筒井委員","kind":"意見","question":"私も陳情者の方の直接的なお考えを聞いてみて判断していきたいと考えておりますので、意見陳述に賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"理解できた方が多いということですばらしいと思いました。私はこれだけ区教委がやっている中で、それであったら、この陳情はあえて出てこなかったかと思うのですけれども、理解できた方にぜひ教えていただきたいのですが、では、なぜこの陳情が出てきたということなのでしょうか。そこは理解できた方は、しっかりとご理解ができたからもういいとおっしゃっているわけですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-093"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、あべ委員の質問が、仮に答えが分からなくても、ここに出てきている要望は分かりますので、特にそれを分かる必要はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-094"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すでお願いします。趣旨採択でお願いします。２番に関しても、さらに電話をかけやすい環境を作ってほしいということだと思いますので、それは区としても様々模索をしていただきたいという思いで趣旨採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-095"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すでお願いします。趣旨採択でお願いします。項目２のフリーダイヤルのほうも、オプションということもありますが、こちらの新しいまもるっちができるということで、そちらのほうでも検討して、今現在のまもるっちではちょっと課題がありますので、新しいまもるっちのほうでも検討していただきたいという思いもありまして、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-096"},{"speaker":"たけうち委員","kind":"質問・要望","question":"理由としては、お二人と似ていますが、項目１については今もやっていらっしゃるけれども、直接的に学校では配っていますということですが、そこももう一歩、区教委も意識を向けていただきたいという思いと、それから2)については、今すぐにはできないけれども、先ほど、課長からあったとおり、今回新しくまもるっちを変えていく中での検討の１つに加えていただくというお話もいただきましたので、この２つ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択を主張したいのですけれども、やっぱり大切な相談機関だということで、区のご説明が答弁の中でありましたが、支援を強めていく必要があると思いますし、こういうときだからこそです。採択をして、議会としてもそういった検討を後押ししていくほうがいいかと思いますので、そういった趣旨で採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-098"},{"speaker":"筒井委員","kind":"質問・要望","question":"やはり既に区の答弁としては、小中学校に広く配布・周知されているということですけれども、もう一歩、陳情者の方の実感できるぐらいに積極的な周知を行っていただきたいということと、また、ＫＤＤＩと保護者の契約は任意であり、また、チャイルドラインはあくまでも民間だということと、ほかの団体もいらっしゃるので、どの程度優遇するかということ、課題はありますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-099"},{"speaker":"あべ委員","kind":"質問・要望","question":"電話も令和５年度からということで、そこには期待したいところですけれども、では、それまでの２年間の子どもたちはかけられないのかということで、電話に日常的にアクセスできないお子さんもいらっしゃるでしょうから、これも例えばですけれども、例えば児童センターからこういうものをかけられるとか、何か公共のものを使って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-100"},{"speaker":"横山委員","kind":"意見","question":"結論を出すで、趣旨採択でお願いします。選択肢が多過ぎますと、子どもたちがどこに相談してよいか混乱してしまう可能性もありますが、相談先は１つではなく複数あって、その中から本人がより話しやすい相手や相談先を選択してアクセスできる環境は必要だというふうに考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"安藤委員","kind":"意見","question":"一応会派で相談して態度を決めていますので、採択すべき内容だと思っているのですが、やっぱり全会一致で趣旨採択ということで結論を出していくというのは大きな力になりますので、趣旨採択に変えします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-102"}]},{"id":"topic-08","title":"令和２年請願第１１号、大学生に返還免除規定を持つ奨学金制度の創設を求める請願","agenda":"令和２年請願第１１号、大学生に返還免除規定を持つ奨学金制度の創設を求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"こちらの請願を出されている方にお話を伺ったのですけれども、あと、街頭で署名も集められていたのです。高過ぎる学費の実態は、やっぱりみんなが共通して悩んでいるなと。だから私は理由にならないと思うのですけれども、もう一度、なぜ区がこうした区民の学生に対して支援をしないのか、給付型の奨学金を行わないのか、もう一度お聞かせいただきたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"先ほども申し上げましたように、国や東京都が、また様々な事業者が奨学金制度を設けておりますので、区といたしましては、大学までの奨学金制度を創設する考えはございません。","id":"exchange-103"},{"speaker":"安藤委員","kind":"質問・要望","question":"区は、高校生をやっていますけれども、大学生に対する支援をする考えはない、支援する必要がないというふうに思っているのか、お聞かせいただきたいと思います。それと、区はやらないと言うのですけれども、東京の中で２３区ほかでも自治体で、こうした施策は実はいっぱいやられています。どのように把握しているのか伺いたいというのが２点です。","respondent":"三ッ橋子育て応援課長","answer":"品川区では、高校生の返還免除制度を始めたばかりです。したがいまして、大学生まで拡大する新創設はございません。他区の状況ですけれども、港区や大田区などが実施しているものと捉えております。","id":"exchange-104"},{"speaker":"安藤委員","kind":"提案","question":"大学生や専門学生についても、今、アルバイト収入がなくなって生活困窮しているということがあるので、それを受けて、やはり１５万円の給付型奨学金を支給するという補正予算を第３回定例会に提案しているということです。港区も同じく第３回定例会に、国の給付型奨学金制度を基準に、区独自の上乗せを来年度から実施する条例を提案しているということで聞きました。なぜできないのか伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"品川区では、高校生までの返還免除制度を新設して、今、対応しています。こちらの検証なども含めて、今現在のところ、大学生までの奨学金を創設する考えはございません。","id":"exchange-105"},{"speaker":"安藤委員","kind":"質問・要望","question":"再チャレンジということを言っていた人もいましたけれども、どこが再チャレンジなのかと。実際に品川区にもこうした実態はあるのだということで、当事者が手を差し伸べる行政をと声を上げたわけではないですか。そうしたところであれば、区としてこういう区民の声に応えるべきではないかと思います。品川区としては、こういう区内の大学生に対して手を差し伸べないのでしょうか。伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"令和２年４月から文科省が法律関係を含めて様々な制度を対応しています。したがいまして、国が授業料の減免や奨学金拡大を行っている段階です。区といたしましては、区民を守るという立場は変わりませんが、今後も国や都の動向を注視してまいります。","id":"exchange-106"},{"speaker":"安藤委員","kind":"質問","question":"人によりますけれども。その中で一人ひとりの方にとっては、しかもコロナの問題もあって、一刻を争う事態なのです。ですから、私が伺ったのは、こうした目の前で実際に困っている方、何とかしてほしいという方に対して、区は手を差し伸べないのでしょうか。区としてやらないのでしょうかということを伺いましたので、もう一度、大学生は支援をしないのでしょうか。伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"大学生を対象といたしました制度につきましては、国で授業料減免や奨学金拡大を行う法律が制定されましたので、東京都や大学をはじめ様々な事業者が奨学金制度を設けております。したがいまして、区といたしましては、大学生までの奨学金を創設する考えはございません。","id":"exchange-107"},{"speaker":"あべ委員","kind":"質問","question":"今の答弁の中で、国の制度を見ていきたいということがあったのですけれども、国の奨学金制度、３８０万円が上限になっていて、２７０万円から少しずつ給付額が減るという条件になっています。品川区では、品川区の大学生２割を対象としようとすると、一体幾らの世帯年収になってくるのかというのは、どのように試算をされているでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"品川区の大学生２割の世帯年収ですけれども、区といたしましては把握ができません。","id":"exchange-108"},{"speaker":"あべ委員","kind":"提案","question":"そうしたことはすごく参考になるのではないかと思うのですけれども、先ほどのご答弁の中で、考えていないというご答弁と、それから高校の免除制度が始まったばかりなので、まだだというものと、ちょっとニュアンスが違う２つのご答弁があったと思うのですが、今、品川区としては、高校の制度を見てから検討するということなのか、それとも単に検討していないだけなのか、どちらですか。","respondent":"三ッ橋子育て応援課長","answer":"しかしながら、国や都が、実際には国で授業料減免や奨学金拡大を行う法律等が制定されておりますので、まずは今の段階では、東京都や大学をはじめ、様々な事業者で奨学金制度が創設されている状況を鑑みて、今後の国や都の状況を注視してまいります。","id":"exchange-109"},{"speaker":"あべ委員","kind":"質問","question":"何年か経たないと分からないという性質のものではないと思いますので、検証するというのであれば、数字が出そろった今、検証を始められたらいいのではないかなというふうに思いますが、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"検証につきましては、しかるべきときに検証してまいります。","id":"exchange-110"},{"speaker":"あべ委員","kind":"質問・要望","question":"すみません、言葉が通じない。しかるべき条件が出そろっているから、それは今ではないですかという話をしておりますが。生活にかかる費用が変わってきますので、一律の数字で設計をすると、その対象は東京の場合は対象にならない世帯が増えてくることが当然に想定されますので、ぜひそこを勘案した上で奨学金制度をもう一度正面から考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"柏原子ども未来部長","answer":"ただ、こういったお話が出ている、国のほうの動きも出ているというところを考えたときには、その制度に対する近隣の区の動きもありますので、今、これをどう見ていくかというところの段階だと思っていますので、これが政策として、ではどこでやるのだという判断は。","id":"exchange-111"},{"speaker":"あべ委員","kind":"質問・要望","question":"ですので、これがすぐにできるとは実はあまり思っていないのですけれども、しかし、少なくともかなり性格の違う高校生の制度を見た上で大学生について考えるというのは、私はちょっと順番としてはどうかなと。そうした面では、ぜひ前向きな検討を、しかも高校の条件とは違った視点でぜひ検討していただきたいと、これは最後に要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"安藤委員","kind":"質問","question":"今回、コロナ感染の影響でということもやっぱり含まれていると思うのですけれども、そういったこともあって、他区などでもいろいろと動きもあると思うのです。品川区としては、大学生、区内の学生、専門学生などについて、こういうアルバイト収入がなくなったとか、あるいは退学せざるを得ないですとか、そういう学生の今の困窮実態はつかんでいらっしゃるのか伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"特に今の段階では、学生の困窮状態については把握しておりません。","id":"exchange-113"},{"speaker":"安藤委員","kind":"質問・要望","question":"しかも、そこに３桁を超える方々の署名も添えられているというようなところをまず認めていただいた上で、制度設計する上でも学生が困っているのだという実態は、少なくともまずつかんでいただくことは絶対に必要だと思うので、それをつかんでいませんということで終わらせるというのは、あまりにも自治体としてはどうか、所管としてはどうなのかというふうに思いますので。","respondent":"柏原子ども未来部長","answer":"ただ、限られた条件の中でやっていかなくてはいけないという情勢の中で、コロナ禍だから、では大学生のこのことに対してすぐ打ち出しができるかというと、いろいろなところの政策との兼ね合いの中で、例えば区民の方に給付を始めました応援給付金。","id":"exchange-114"},{"speaker":"芹澤副委員長","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。経済的にもなかなか大変だったので、いろいろと模索をしながらやってきました。これからも自民党として国政の中でも制度改革というのも非常に進めていますので、そこにぜひ期待をしていただいて、より多くの学生を救っていただきたいというふうに思っていますので、まずはやはり国の動向を引き続き見ていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"せお委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いします。国の動きもありますし、先ほどもありましたように、コロナ禍ですので、やっぱり区も限られた財政というところで、やはり優先順位は必要だと考えています。ただ、区の大学生に関する実態の調査であったりとか、そういったところはやっていただきたいという要望はありますが、こちらに関しては不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"意見","question":"本日結論を出すで、不採択でお願いします。公明党は、党として国のほうで給付型の実現を含め、またこれから拡充を含め動いていくということをしっかりとお約束を私がするのもあれですけれども、する中で、私も親の立場でつい最近まで２人同時に大学に通わせて、非常に大変だ、なぜこのように高いのだろうと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-117"},{"speaker":"安藤委員","kind":"質問・要望","question":"本日結論を出すで、採択を主張したいのですが、根本的には、先ほどもいいましたけれども、お金のあるなしで未来がある若者が学べないというような社会でいいのかというのが、どのステージでも問われていると思います。区としてできることを早急にやっていただきたいというふうに思いますので、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。港区、大田区もそうしたことを受けてか給付金制度を進めようとしておりますし、予算の制約も考えなくてはいけないとは思いますけれども、やはりここはコロナの収束するまで緊急的かつ期間限定でもいいので、ぜひこうした給付金、奨学金制度の創設に前向きな検討をしていただきたいという理由で、採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-119"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すということで、採択と考えております。なおかつ、先ほども伺っていますと、国もこれからさらに充実させていくということですので、補う形で設計していれば、国が充実すれば、その分だけ自治体の負担も減ってくるであろうということも考えられますので、そうすると、つなぎとしての効果も発揮できるだろうというふうに考えます。それも併せて実態把握に努めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-120"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。は区の新制度について、成果、課題などの検証や分析を実施していただきたいというふうに考えています。今後の高等教育の修学支援の状況については、引き続き、国の新制度ですとか、国の動向などを注視していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-121"}]},{"id":"topic-09","title":"令和２年陳情第４７号、離婚等のこども養育支援にかかる陳情","agenda":"令和２年陳情第４７号、離婚等のこども養育支援にかかる陳情","exchanges":[{"speaker":"あべ委員","kind":"質問","question":"その件数のうち、何％が解決したのでしょうか。それは答えられますか。","respondent":"三ッ橋子育て応援課長","answer":"相談につきましては、きちんと対応して、面会交流や養育費の問題など、様々、公益社団法人に紹介しておりますので、基本的には１００％と考えております。","id":"exchange-122"},{"speaker":"あべ委員","kind":"質問","question":"１００％解決が図られているというご答弁でよろしいのですか。","respondent":"三ッ橋子育て応援課長","answer":"解決と申しますのは、それぞれの方の答えというものも非常に難しい問題があります。ひとり親家庭になって様々な問題を抱えている方、そして面会交流がしたいと思ってなかなかできない方、様々な問題があるのは承知しております。","id":"exchange-123"},{"speaker":"あべ委員","kind":"質問","question":"それはフィードバックを受けているのですか。つまり、区としては、面会交流についてご相談された方が、その後どうなっているのか、ちゃんと満足いける状態なのか、それとも課題があるのかということを区として把握されているのでしょうか。それなしに、さっきおっしゃっていた子どもたちの最善の利益というのは普通にできないのではないかと思いますけれども、いかがでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"しかしながら、私が問題解決は図られているというふうに申し上げましたのは、区といたしましては、相談を受けて、ご紹介をして、そこの次の段階で何らかの対応をしているということはできますので、その意味で図られていると申し上げました。","id":"exchange-124"},{"speaker":"あべ委員","kind":"質問","question":"とすると、課長がおっしゃられる問題解決が図られているというのは、相談を受けて次の機関に紹介したら、それでもう一件落着という意味なのでしょうか。そのようにしか今のお話は聞こえないのですけれども、それでは区民の方々が本当に困っているのか、次にもう１回相談が来ないと、紹介した後のことは追えていないということでよろしいのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"様々な案件がありますので、面会交流は、お父さん、お母さんの問題、そしてそれに伴うお子さんの問題、様々なことがありますので、区としては、もちろん問題は解決が図られていると把握はしておりますけれども、しかしながら、委員がおっしゃるように、様々な問題がある。","id":"exchange-125"},{"speaker":"あべ委員","kind":"質問","question":"すみません、質問が重なっているのではなくて、答弁がその場所から動いていないだけだと思うので何度も聞かせていただきます。問題解決が図られているという最初のご答弁だったわけです。でも、区としては、もう全て問題解決しているという認識なのですか。もう１回聞きます。","respondent":"三ッ橋子育て応援課長","answer":"したがいまして、もちろん区としても面会交流の支援はしていきたいと考えておりますけれども、この案件につきましては、本当に難しい問題で、国や都の動向を注視しています。","id":"exchange-126"},{"speaker":"あべ委員","kind":"質問","question":"１００％は目指しているけれども、解決は１００％ではないというところまでは区として認識はされているということ、これはいいですか。それが１点。それから国や都が動かないと、品川区としてはこの問題に動かないという意味でよろしいのですか。つまり、品川区としてはこの問題には直接的には関わらないということでいいのでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"何にしろ、子どものことをきちんと大事に考えていかなければならないと考えています。１点補足ですけれども、相談を受け付けて、その後、支援につなげていく、ご紹介していく、その後、またもちろんアフターケアもしておりますので、ご相談に応じて対応はしております。","id":"exchange-127"},{"speaker":"あべ委員","kind":"質問・要望","question":"先行事例がある以上、自治体としていろいろと悩みながらどこまでできる、どこまでできると考えている自治体がある以上、品川区としても、いや、それは都に投げましたとか、あるいは国が動くのを見ていますというだけではなくて、ぜひこの問題を区としてできることを考えていただきたいと思うのですけれども、その姿勢自体はあるのですか、ないのですか。","respondent":"三ッ橋子育て応援課長","answer":"先ほど申し上げましたように、実際に法律等も動いていく可能性が高いと考えています。その中で区として何ができるのか、それは考えていかなければいけない問題だと考えています。","id":"exchange-128"},{"speaker":"あべ委員","kind":"質問","question":"考えていかなければいけないというのは、今はまだ考えていないけれども、これから考えるということですか。今は何を考えていますか。","respondent":"三ッ橋子育て応援課長","answer":"先ほど答弁いたしましたように、区といたしましては、引き続き、国や都の動向は注視していきます。そしてまた、法律の状況もいろいろと把握していきながら、区として何ができるのか、できないのか、どの部分に対応していくのかなどを含めて考えていくことが大事だと考えています。","id":"exchange-129"},{"speaker":"あべ委員","kind":"質問","question":"部長、今のご答弁でいいのですか。いろいろと面会交流あるいは子どもの養育については、たくさんの課題があることまでは、多分区としても認識されていると思いますが、品川区としては、今は何もしないという状況なのでしょうか。","respondent":"柏原子ども未来部長","answer":"国等々の動きがある中で、区がそこの中でどういう役割を持たなくてはいけないのか、それはケースごとによって、入り方であったりとか、それから、その部分だけの課題だけではなくて、別の部分にも課題があったりということが幅広いというところもありますので。","id":"exchange-130"},{"speaker":"筒井委員","kind":"質問","question":"実際、東京都とセンターに振られているということなのですけれども、ということは、実際にご相談があったということだと思うのですが、今までのそうした件数や、それが多いのか少ないのか、区としてはどのような実感を得ているのかをお聞きしたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"件数については控えさせていただきたいと思いますが、全て、もちろん状況に応じて面会交流などもご紹介しております。","id":"exchange-131"},{"speaker":"筒井委員","kind":"質問","question":"実際、この事業をやるかやらないかに当たっては、需要があるのかというのは把握しておかなければいけないと思っているのですけれども、それほど頻度的に多いものなのかということを、具体的な件数というよりは、相談は本当に多いのかというか、感触というか、その辺りはどうなのですか。","respondent":"三ッ橋子育て応援課長","answer":"様々な相談がありますので、特に面会交流をしたいとか、今回の陳情に関係するような相談については、多い少ないというのもなかなか難しい答えになるのですけれども、もちろん面会交流をしたいというご相談はあります。","id":"exchange-132"},{"speaker":"筒井委員","kind":"質問","question":"小平市とか武蔵野市とかは、実際に東京都の取組みとかを自身のホームページで上げているので、そうした周知とか広報の改善をしてほしいのですけれども、その点、いかがお考えでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"様々な状況を勘案しながら、ご相談したい方が探せないというのは、さすがによくないとは思います。ただし、この案件は非常に慎重に進めなければ、単純な事務的な作業とかとは全く違いますので、その部分に関しては慎重に検討させていただきたいと考えています。","id":"exchange-133"},{"speaker":"たけうち委員","kind":"質問","question":"これはまず周知でしょう。それから、さっき件数云々とおっしゃっていたけれども、事務事業概要の５６ページに、家庭福祉とあって、ここで家庭相談で、ここを見ると、養育の相談で何件、何件と件数が出ているではないですか。なおかつ今、区でもやっているわけではないですか。ここはそういう視点でお答えしてもらわないと、我々もせっかくこれを審査しているのだからと思うのだけれども、どうでしょうか。","respondent":"柏原子ども未来部長","answer":"件数等々についても、そういった視点のところで慎重なところでの答弁が行き違いのようになっていますけれども、お話しできる内容については、きちんと審議といいますか、議論ができる内容での答弁をさせていただきたいと思います。申し訳ございませんでした。","id":"exchange-134"},{"speaker":"安藤委員","kind":"質問","question":"陳情にも紹介されていますけれども、子どもの権利条約の第９条というところです。「児童がその父母の意思に反してその父母から分離されないことを確保する」というような、子どもが両親、片方ではなくて両親と交流するという権利について書いているわけですけれども、ここについて品川区としては、どう認識されているのか伺いたいというふうに思います。２点伺います。","respondent":"三ッ橋子育て応援課長","answer":"面会交流につきましては、先ほど申し上げましたように、子どもたちにとって最善の方法をとるのが一番いいと思っているところです。明石市や港区に対しては、やはり先進的な事例だと捉えておりますので、それらはいろいろと勉強させていただきたいと考えています。","id":"exchange-135"},{"speaker":"せお委員","kind":"質問","question":"１点だけお伺いしたいのですが、養育費に関してですけれども、東京都が今年度の予算で養育費確保支援事業という「ひとり親家庭の養育費の安定した取得に向け、民間保証会社と連携し、養育費の立替保証を実施する区市町村を支援する」とあるのですけれども、こちらの事業については何か検討されていることはありますでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"今年度から東京都が始めた事業と捉えておりまして、区といたしましても、様々検討、勉強してまいりたいと考えています。","id":"exchange-136"},{"speaker":"筒井委員","kind":"確認","question":"確認ですけれども、２３区では、実際に面会交流支援をやられているのは、港区だけという理解でよろしいでしょうか。","respondent":"三ッ橋子育て応援課長","answer":"私はそう捉えております。","id":"exchange-137"},{"speaker":"芹澤副委員長","kind":"意見","question":"継続でお願いいたします。会派からも養育費等を行政のほうに働きかけてきましたけれども、国と都の動きが今非常に活発になってきていると。ただ、国と都がやればいいだけの話ではなくて、今話し合ったように、区の関わりも前提になってきているのかと思いますので、引き続きこちらは議論していければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-138"},{"speaker":"せお委員","kind":"質問・要望","question":"こちらは継続でお願いいたします。ご家庭それぞれの事情とかも第三者が理解するのはすごく難しい部分もありますし、あと、国の法改正でしたりとか、先ほど質問いたしました都の事業に関しても、こちらも動きがあるということで、そちらを注視していくべきだと私も思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-139"},{"speaker":"安藤委員","kind":"質問・要望","question":"面会交流支援というのは、そういったところに重要な支援だと思いますので、ぜひ品川区でも先進事例だという話もありましたけれども、検討・研究を進めて実施できるところから実施していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-140"},{"speaker":"筒井委員","kind":"質問・要望","question":"国・東京都の動きもこれからあるかもしれませんし、また、離婚という事由の性質上、基礎自治体でやっていくべきものなのか、それとも東京都という広域である程度やっていくべきものなのかということは、しっかりと今後も深めていかなくてはいけないのかと考えています。ただ、案内とか周知の点、現行の東京都の制度がありますので、そこはしっかりとご相談者にお伝えをしていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-141"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いしたいと思います。とはいえ、今のお話を伺っていると、どうも継続のほうが多そうな感じで非常に懸念をしているのですけれども、もしこの結論が長くなるということがあっても、その時間をむだにせずに、ぜひ、特に所管課のほうで、この問題について、もう一度しっかりと把握をして、深く法制度、それから、これまでの品川区での議論も頭に入れていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-142"},{"speaker":"横山委員","kind":"質問・要望","question":"継続でお願いします。その間、現在もＦＰＩＣ、家庭問題情報センターのパンフレットを課の前のところに置いていただいているというのも、私、この間、確認もしてきたのですけれども、今やっていただいている周知ですとか、または都やＦＰＩＣの専門家に適切につないでいただくなど、相談者と一緒に考えて、よりよい解決に向けた情報提供を必要な方にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/329346?Template=document&Id=5012#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":94510,"voices":377}},{"id":"r02-20200923-5","meetingId":"r02-cm09","date":"2020年9月23日","dateIso":"2020-09-23","committee":"総務委員会","time":"午前１０時００分～午後 ０時００分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","topics":[{"id":"topic-01","title":"第６２号議案 第二戸越幹線整備工事（北品川立坑）請負契約の変更","agenda":"第６２号議案 第二戸越幹線整備工事（北品川立坑）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"資料の２ページ目の変更理由ですけれども、その他のところで、新型コロナウイルス感染拡大防止に向けたとあります。工事の一時中止というのは、どのような趣旨なのか。いわゆる感染者がいる、それとも、感染予防なのか。いずれにしても、工事の一時中止によるというのは、どのような事情なのか、そこだけご説明いただきたいと思います。","respondent":"松本河川下水道課長","answer":"その他の新型コロナウイルス感染拡大防止に伴う一時中止ですが、これは、請負者から感染予防ということで、緊急事態宣言の間、４月２７日から５月８日にかけて、平日の６日間、中止したものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"提案","question":"関連して、今回、金額が大きいので議案として提案されたのだと思います。この新型コロナウイルス感染症の対応は、どの工事でも共通してくることだと思うのです。金額の大小で議案になるかどうかは別にして、ほかの公共工事もこのような対応というか、追加の費用を支出しているという認識でよろしいのでしょうか。","respondent":"東野経理課長","answer":"新型コロナウイルス感染症に対する工事請負契約の変更なのですけれども、現在、感染症対策のみで金額の変更をしている案件はございません。工事の一時中止等に伴いまして、工期の延長等の契約変更の措置は何件かしています。","id":"exchange-002"},{"speaker":"須貝委員","kind":"質問","question":"今の質問についてお聞かせ願いたいのですが、今回、感染拡大防止に向けて、一時、工事が中断したということです。現場維持経費等と記載されているのですが、この費用は、おおむねどれぐらいの額になっているのですか。その分をお客様に請求しているという話を聞いたことがないし、新聞でもそういった記事を読んだことがないのですが、なぜこのようなことがあるのですか。それについてお聞かせください。","respondent":"松本河川下水道課長","answer":"この経費の計算につきましては、今回、この工事が東京都下水道局の請負事業になりますので、下水道局の変更ガイドラインに計算方法があり、それに則って計算し、４０万円を算出しています。","id":"exchange-003"},{"speaker":"須貝委員","kind":"意見","question":"下水道局は公共の機関です。要は、公共機関はこのように上乗せする。それで、他方、民間ではしない。額は少ないですが、やはりこのようなことを行うならば、私は日本全国にわたって、建設業者および現場の業者にこのようなことをきちんとアピールしていくべきではないかと思います。意見だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今、(5)のその他のところは約４０万円ということで、約８億円の契約について、約２億円の増額ということですので、つまりは(1)から(4)が大きいということです。ごめんなさい。私、こういうことが全く分からないので、ざっくりで結構です。費用がどれにどれくらい、また一番多くかかるのはどれだったのかということを教えてください。","respondent":"松本河川下水道課長","answer":"変更金額についてです。内訳につきましては、(1)の立坑工が、約９,０００万円の変更となっています。続きまして、(2)の付帯工が、約７０万円の変更です。(3)の仮設工が、約６,７００万円の変更です。(4)の共通仮設費が、約１,７００万円の変更です。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問","question":"すみません。一遍に聞けばよかったのですけれども、これらの変更が必要になった理由も、簡単で結構ですので、教えていただけますか。","respondent":"松本河川下水道課長","answer":"設計段階では、平成２８年度のボーリング調査の地下水から処分量を算定しておりましたが、請負者決定後、ボーリング調査を実施したところ、設計段階より地下水が高かったことから、土砂と泥土の処分量を変更したものです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"つまり、土砂と泥土では、処分の金額が変わってくるという理解でよろしいでしょうかというのが１点です。最初のところと、あとは要望ですけれども、もし何か一言あれば、伺いたいと思います。","respondent":"松本河川下水道課長","answer":"今、委員のご質問のとおり、土砂と泥土の処分先によって金額が変わるものです。理由の掲載につきましては、今後、検討していきたいと考えています。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"意見","question":"変更理由の４番目、共通仮設費は、近隣構造物の計測管理の追加等ということで、先ほど、課長から１,７００万円の変更という話しがありました。これは、掘削をするに当たって、近隣の構造物に恐らく影響が出たから、改めて計測管理をやると思うのです。具体的に、どのような計測管理をやるのか、施工するのかどうか。その１点だけお願いいたします。","respondent":"松本河川下水道課長","answer":"ＪＲにつきましては、高架にターゲットという測量のポイントを設置いたしまして、その変位を見てあります。首都高につきましては、傾斜計というものを設置しまして、地盤が変位するか、しないかということを測ってあります。","id":"exchange-008"}]},{"id":"topic-02","title":"令和２年請願第９号 固定資産税及び都市計画税の軽減措置の継続","agenda":"令和２年請願第９号 固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"３項目にわたって、来年度以降も継続することという願意ですけれども、小規模事業者の経営が苦しくなっているので、必要な措置だと考えています。１点だけ伺いたいのですけれども、品川区としては、この３項目について、東京都にどのように要望しているのか。そのスタンスだけご説明いただきたいと思います。","respondent":"伊東税務課長","answer":"区のほうにも、軽減措置ということで、要望等が上がっているところです。スタンス的には、我々も区民の暮らしのためにそのような軽減措置を継続したほうがいいなと思っているところですが、具体的にどの場面、どのような形で都にということでは、今のところ考えておりません。","id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"こうやって毎年、軽減措置について議論するわけですが、もう３０年続いているわけです。３０年以上続いているならば、そうすべきだと思うのですが、実際、区長会、副区長会では、都にどのような要望をしているのか。都ではできないのか、やってくれないのか、その辺について、少しご見解をお聞かせください。たしか毎年、区長会、副区長会でも要望していると思うのですが、その辺は、どうなのでしょう。","respondent":"桑村副区長","answer":"そのことも含めて、制度的なものについての都と区の感覚の違いがありますので、これがいい制度だからといって、区長会も副区長会もどんどん進めるべきだとはなかなかならないのではないかなと思っています。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問・要望","question":"毎年これを見ていて、都内に高層マンション、タワーマンションがたくさん建って、固定資産税が膨大にと言ったら変ですけれども、地方と比べたら圧倒的に地価も上がって、固定資産税も増えているのです。ですが、それに対して区民に還元されているのか、２３区にきちんと還元できているのか。ぜひ今後も区長会、副区長会で、また、財政課、企画調整課のほうで、都にしっかり進言していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"湯澤委員","kind":"質問","question":"１点お聞きしたいのですけれども、この軽減措置の３つの項目について、品川区においては、軽減措置創設以来、適用を受けている件数や金額の増減の推移が、どうなっているか教えていただけますでしょうか。","respondent":"伊東税務課長","answer":"影響額というところで、今回、令和元年度の数字は資料にお示ししていますけれども、昨年度と比較してみますと、影響額は、小規模住宅用地に対する軽減措置に関しては、件数的には６万件というところですが、８,０００万円ほど増加しています。軽減を受けているということです。","id":"exchange-012"},{"speaker":"湯澤委員","kind":"意見","question":"増加したり、少し減少しているところもあるかもしれませんけれども、特に今年は新型コロナウイルス感染症の影響で、区民や区内事業者でダメージを受けているところはかなりあるかと思います。そういった方々のためにも、この軽減措置は、ぜひ今年もしていくべきではないかなと思っている次第です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"１点だけ確認させていただきたいのですが、２番目の小規模非住宅用地に対する減免措置。この減免を受ける場合には、年内に申請が必要とあります。この対象者には、品川区、東京都のどちらが、この減免措置について案内されているのでしょうか。","respondent":"伊東税務課長","answer":"新規の方は、年内に申請が求められているです。それで、直接的には行っていないかもしれませんけれども、様々な媒体、主税局で発行しておりますガイドブックや、先ほど言ったホームページのような方法で周知が図られていると認識しております。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"意見","question":"対象の方は、そのようなところを意識されているので、情報は知っているかと思います。やはり、知らなかったということがないようにする必要があると思いましたので、該当の方にしっかりと周知できるように、すでに周知されているということであれば、安心しました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"}]},{"id":"topic-03","title":"令和２年陳情第４８号 子どもが健やかに育つための陳情（陳情項目３）","agenda":"令和２年陳情第４８号 子どもが健やかに育つための陳情（陳情項目３）","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"参加はたくさんしてほしいけれども、定員は何分の１とせざるを得ない。だから、そういう視点からも、現状は分かりましたけれども、今後のことを考えると、このようなことは全然考えられないものなのでしょうか。新型コロナウイルス感染症が終息しても、必ず次を想定しておくというのは、もう世界の流れではないかなと思うのですが、その点についてお考えがあったら伺いたいと思います。","respondent":"島袋人権啓発課長","answer":"それと、新型コロナウイルス感染症対策としての緊急の課題ですが、できるところからやってみて、またお声を聞きながら、進めていけるところは進めてまいりたいと考えております。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"確かに、一気に進むかどうかは、私もオンライン会議をやるときや、オンライン講習会をやるときには、検討しなければいけないことがたくさんあるのです。それは分かるのですけれども、方向性としては、やはりオンラインのほうを考えていくべきではないかと思うのです。今、方向性の検討の項目の中に、例えばそのようなことも検討される余地はあると理解してよろしいでしょうか。","respondent":"島袋人権啓発課長","answer":"今後、講習会等々を開催していく予定で、今進めているところです。その中では、リモートでの参加はないのですけれども、アンケート等で区民の方たちの意見等も取れるかと思いますので、そちらを注視してまいりたいと考えているところです。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"アンケートもすごくいい必要な手法だと思いますし、オンラインなどは余り得意ではなくて、紙で書きたいという方がいらっしゃるのも確かですし、先ほどの繰り返しになりますけれども、生活者ネットワークとしては、本当は会って顔を合わせてやるべきだという考えなのです。だけど、やはりいろいろな人の参加を募る。繰り返しになってしまいますので、これは要望にとどめたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭の説明は、きゅりあん４階の特別講習室にＷｉ－Ｆｉがあって、その利用料金が５割減額になるので、そちらを利用していただきたいということでした。私も区民集会場を様々利用しますが、１時間で１回切れますが、どこもＷｉ－Ｆｉがつながります。今、大井町駅前にも整備しているわけですから、そのような方向で、ぜひとも考え直していただきたいと思うのですけれども、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"そちらの検討もせざるを得ないかなということもありますし、確かに公共施設におけるＷｉ－Ｆｉの環境整備はとても必要だと思います。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"この議論をすると、無料であったものが有料化になってしまうような感じがして、それはよくないと思うのです。これは進めるべきではないと申し上げたいと思います。いずれにしても、ほかの区が有料の中、品川区は男女共同参画の事業を進めるに当たって、会議室を無料で提供しているというのは、とてもよいことだと思います。ぜひとも有料にするのはやめていただきたいのですけれども、いかがでしょうか。","respondent":"榎本総務部長","answer":"今、男女共同参画センターには会議室が１つしかないのです。その中で、区の事業としていろいろな講座をやる。その使っていない部分を団体が使うという形になっていまして、その調整をしているところです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に、登録団体が減っているというお話がありましたけれども、それは男女共同参画センターの事業をより拡大していって、区民に身近な存在になれば、また増えてくるのかなと思います。改めて、やはりＷｉ－Ｆｉ整備は当然進めていくべきだと思いますので、検討していただきたいのと、今まで空いているところを無料で貸していたのを有料化することなく、今までどおりでお願いしたいと申し上げたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"今、お話をいろいろ聞いていたのですが、確かに将来的にはこういう環境になっていくということは世界の流れだと思います。ただ、お話を聞いていて、様々な貸出環境がある中で、こちらはどうするのだ、有料化、無料化と、様々なこともあります。そこは重々加味してやっていただきたいと思います。意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"現状の確認をします。先ほど、登録団体も減ってきているということでありましたが、現状、どれくらいの登録団体があって、その団体の方からのＷｉ－Ｆｉのご要望の声や、どれくらいお部屋が活用されているのか。コロナ禍でありますので、かなり激減していると思うのですけれども、交流室、資料コーナー等がどれだけ活用されているのかという現状をお聞かせいただきたいと思います。","respondent":"島袋人権啓発課長","answer":"交流室、資料コーナーは出入りがありますので、何人というお示しはできないのですけれども、出入り口のところには、記入していただくように記載名簿を出しています。このところは、若干減っているような傾向が見られるようです。","id":"exchange-023"},{"speaker":"新妻副委員長","kind":"質問・要望","question":"４９団体のうち、約半数は実体があるというか、活動されているということが確認されました。今、課長のご説明では、現状は難しいというお話もありましたけれども、きゅりあんの改修等に合わせて、また、フリーＷｉ－Ｆｉの設置なのか、何か別の形なのか、ネット環境が整備されるということにおいては、時代の流れでありますので、ぜひそこはご検討を頂きたいなと思いますが、再度、いかがでしょうか。","respondent":"島袋人権啓発課長","answer":"その間、やはりＷｉ－Ｆｉ環境を整備していくことも、その中の検討課題の１つとして考えていくことが重要かと思いますし、合わせて、男女共同参画センターの様々な貸会議室の在り方等も検討していく必要があるのではないかと考えているところです。","id":"exchange-024"},{"speaker":"新妻副委員長","kind":"質問","question":"結論を出すです。不採択です。先ほど質問もさせていただきました。今後、課題をしっかり検討いただき、きゅりあんの改修の時期に合わせてご検討していただくということで、今回の陳情に関しては不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"中塚委員","kind":"意見","question":"結論を出すということと、採択でお願いします。やはり陳情要旨にもあるとおり、男女共同参画センターにＷｉ－Ｆｉを設置すべきだと私も思いますので、採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"結論を出すということと、不採択でお願いいたします。やはり、今お話を聞いていて、貸出は区民に対して平等に行う。やはりそれが原理原則だと思いますので、そういうものが様々整った上で、区はこれからも改善云々があるのでしょうから、そのときにまたＷｉ－Ｆｉ設置等を考えていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すということで、採択でお願いいたします。いろいろ課題があることは私も承知しております。大規模改修のときには、きっとフリーＷｉ－Ｆｉという形になっていくのだろうなと思います。いろいろな条件整備が必要なことは理解いたします。ただ、条件整備は、区や議会が考えるべきことです。採択でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"そのためにあるべきなのに、例えば、国や都の意向で自治体の方向性が決まってしまう仕組みだといつも感じるのです。あのようなものは本当に最たるものだなと思うのだけれども、やはりそういう流れの中で、区としては自立して地方自治を考えていくという姿勢が必要なのではないのかなと、大雑把な質問になってしまいましたけれども、その辺のところを品川区はどのように考えているのか、伺いたいと思います。","respondent":"品川財政課長","answer":"例えば、木造密集の関係や木密不燃化１０年プロジェクトなどがありましたけれども、それについても、大枠は独自で決めて動いているというところはあったのですが、やはり、どのようにしようかという細かい内容は、各区、各自治体などにヒアリングをし。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"使える補助金や制度をこちらが主体的に使うことはとてもいいことだと思うのです。ただ、特に財政調整の仕組みを見ても、都区協議会で合意した上での条例改正とはいえ、まだまだ２３区独自施策、特に児童相談所すら議論に時間がかかっていると思うので、主体的に東京都との交渉に当たっていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"須貝委員","kind":"質問","question":"国・都補助金の概要です。もし聞き漏れていたら申し訳ないのですが、再度になりますが、少し質問させてください。補助金申請事務の流れなのですが、大体何月頃、このようなことがあって、ヒアリングを何回ぐらい行うのか。そして、国や都に出向くと思うのですが、どの部署に行くのですか。各所管ごとに行くのか。その辺も教えてください。","respondent":"品川財政課長","answer":"基本的には、大体１月から２月、４月ぐらいまでのもあるのですけれども、その辺で交付決定がされて、その後、何回かヒアリング等も受け、おおむね夏を過ぎた頃から実績調査等をやるという動きで、最終的に、年度末ぐらいに交付を受けるというものもあります。","id":"exchange-031"},{"speaker":"須貝委員","kind":"提案","question":"ただ、このような流れを見ると、やはり２３区は国や都に監視されているみたいで、きちんとやらなければお金を交付しないよ、きちんとやれば交付するよ、それもいいかげんな提案だったらだめだよと、逆に国の施策、事業に対して、我々も言いたいことが山ほどあるけれども、本当にこういう国や都の補助金の概要を見ると、先ほどもありましたけれども、じくじたる思いというか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。私も初歩的な質問で恥ずかしいのですけれども、一番最初に事業計画書の提出があって、その事業計画に対してヒアリング・調査が１回行われるわけです。そのやりとりは、審査選考に至る事業計画書になるまでに、何回ぐらいやりとりがあるのかということ。それで、ここで１回審査に入りますよという内示なのですかね。その辺のことを教えていただきたいと思います。","respondent":"品川財政課長","answer":"それで、最終的に交付決定されるという流れになっていると思います。ですので、回数は何回ですかという質問に、なかなか具体的にお答えすることはできないのですけれども、そのような状況です。","id":"exchange-033"},{"speaker":"吉田委員","kind":"確認","question":"だから、そのようなやりとりがあるのかなと思ったのです。つまり、大体内示が出れば、何か微修正はあるにしろ交付決定という理解でよろしいでしょうか。１団体が国からの補助金をもらうことに比べたら、これは割とルーティン作業と言っては失礼かもしれませんけれども、そのような形になっていると理解してよろしいでしょうか。その辺だけ確認させてください。","respondent":"品川財政課長","answer":"具体的な金額の調整等は、その後の交付申請書の審査等で若干微調整があるというのが大きな流れかとは思います。これもケース・バイ・ケースでいろいろ違うとは思いますので、そこのところはご了承いただきたいと思います。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"この補助金申請事務の流れというのは、前年度に同様の補助金が出たのが例になっていますけれども、例えば、新しい制度が始まって、こういう事業に補助金を出すとなったときも、大体同じような感じなのか、それとも、始めの年は実績報告が出せないわけですから、何か手間がかかるのか、その辺のことも教えてください。","respondent":"品川財政課長","answer":"そのような形になりますと、国がスケジュールを組みまして、どのような流れになるかというところは、申し訳ございません。これもお答えになっていないかもしれないですけれども、ケース・バイ・ケースで流れは違ってくるかなと考えています。","id":"exchange-035"},{"speaker":"吉田委員","kind":"確認","question":"初年度でも、内示が出れば、大体大丈夫という感じですか。ケース・バイ・ケースだろうとは思いますけれども、おおよそということで理解していいか、少し確認させてください。","respondent":"品川財政課長","answer":"当然、事業計画という形で提出して、その計画の内容等を審査して内示を出しますので、基本的にはここで補助金の対象になるか、ならないかというところは決まるかと思います。しかし、何回も言いますけれども、これもケース・バイ・ケースでいろいろかとは思います。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"いろいろありがとうございました。今のお話を伺っていると、国や都が出す補助金だと、その意向に合わせて事業計画を出すみたいになっていくのだと思いますけれども、できることなら、その辺に区としての創意工夫をきちんと盛り込んだ形で、ぜひ出る補助金はきちんと活用していただけたらなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"須貝委員","kind":"質問","question":"すみません。この事務の流れを見ていて、民間会社なら、足しげく担当者に会いに行ったり、折半というか、個々にお金を出し合って食事会をしたりして、その人の気持ちを聞く、また、こちらから訴える気持ちを分かってもらうには、やはり会って話をしたり、聞いてもらうということも大事ではないですか。そのようなこともされるのか。それから、理不尽な対応もあるのか。","respondent":"品川財政課長","answer":"補助金制度として、２分の１まで出します、４分の１まで出しますとしっかりと書いてはあるのですけれども、実際にそこまで交付しているか、交付していないかというのは、やはり微妙なところがあります。","id":"exchange-038"},{"speaker":"須貝委員","kind":"意見","question":"本当にこれだと民間会社のサラリーマンの方が、会社でお得意先と対応しているような現状だと思います。国では忖度という話が出ていますので、私が思っていた以上に予算を持ってくる、補助金を持ってくるというのは大変なのだなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"}]},{"id":"topic-05","title":"今定例会の一般質問に関わる所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"今定例会の一般質問に関わる所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"実際、依命通達を自分でコピーして持ってきたのですけれども、８月３日に副区長が各部長宛てに出した依命通達です。具体的な質問は、原則１０％のマイナスシーリングを各部局にかけるということで、その趣旨、理由を質問したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=2178#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":30975,"voices":131}}]);
